COLLDATA("qenc","ur",[[252,"§حیۃ\nحیہ اس کی جمع حیات ہےاور اس کامعنی سانپ ہے۔سانپ زمین پر رینگنے والاجانور ہے۔ قرآن کریم کےاندر صرف موسیڠکےقصےمیں اس کاذکرآیا ہے۔جب اللہ تعالی نےموسیڠکو اپنی قدرت کی نشانی اور معجزہ دکھانا چاہا تو فرمایا:﴿وَمَا تِلۡكَ بِيَمِينِكَ يَٰمُوسَىٰ قَالَ هِيَ عَصَايَ﴾ [طه: ۱۷-۱۸] \"اےموسیٰ! یہ تیرے داہنے ہاتھ میں کیا ہے؟ موسیٰ علیہ السلام نے کہا: یہ میری لاٹھی ہے\"۔\nاللہ تعالیٰ کو تو معلوم ہی تھا کہ موسیٰ علیہ السلام کے داہنے ہاتھ میں لاٹھی ہے۔ لیکن اللہ تعالیٰ کو لاٹھی کو سانپ بنا کر دکھانا تھا اس لیے حکم ہوا:﴿قَالَ أَلۡقِهَا يَٰمُوسَىٰ فَأَلۡقَىٰهَا فَإِذَا هِيَ حَيَّةࣱ تَسۡعَىٰ قَالَ خُذۡهَا وَلَا تَخَفۡۖ سَنُعِيدُهَا سِيرَتَهَا ٱلۡأُولَىٰ﴾ [طه: ۱۹-۲۱] \"فرمایا:اے موسیٰ اسے ڈال دو۔ تو انھوں نے اس کو ڈال دیا اور وہ اچانک سانپ بن کر دوڑنے لگا۔ اللہ تعالیٰ نے فرمایا کہ اسے پکڑ لو اور ڈرنا مت۔ ہم اس کو ابھی اس کی پہلی حالت پر لوٹا دیں گے\"۔﴿فَأَلۡقَىٰ عَصَاهُ فَإِذَا هِيَ ثُعۡبَانࣱ مُّبِينࣱ‏﴾ [الاعراف: ۱۰۷] \"موسیٰ نے اپنا عصا (زمین پر) ڈال دیا تو وہ اچانک صاف ایک اژدھا بن گیا\"۔پھرجب موسیٰڠاور جادوگروں کے درمیان فرعون کےسامنے مقابلہ ہوا اور جادوگروں نے اپنی رسیاں اور لاٹھیاں ڈال دیں اور بولے:﴿فَأَلۡقَوۡاْ حِبَالَهُمۡ وَعِصِيَّهُمۡ وَقَالُواْ بِعِزَّةِ فِرۡعَوۡنَ إِنَّا لَنَحۡنُ ٱلۡغَٰلِبُونَ فَأَلۡقَىٰ مُوسَىٰ عَصَاهُ فَإِذَا هِيَ تَلۡقَفُ مَا يَأۡفِكُونَ فَأُلۡقِيَ ٱلسَّحَرَةُ سَٰجِدِينَ قَالُوٓاْ ءَامَنَّا بِرَبِّ ٱلۡعَٰلَمِينَ رَبِّ مُوسَىٰ وَهَٰرُونَ﴾ [الشعراء: ۴۴-۴۸] \"توجادوگروں نے اپنی رسیاں اور لاٹھیاں ڈالیں اور کہنے لگےکہ فرعون کے اقبال کی قسم،ہم ضرور غالب رہیں گے۔ پھرموسیٰ نے اپنی لاٹھی ڈالی تو وہ ان چیزوں کو جو جادوگروں نے بنائی تھیں یکایک نگلنے لگی۔تب جادوگر سجدےمیں گر پڑے۔(اور) کہنے لگے کہ ہم تمام جہان کے مالک پر ایمان لے آئے۔ جو موسیٰ اور ہارون کا مالک ہے\"۔","",{}],[253,"§حیض\nعورتوں کو ہر مہینے آنے والےخون کو حیض کہتے ہیں۔ اردو میں اسے ماہواری کہتے ہیں۔اس بارے میں قرآن کریم میں آیا ہے:﴿وَيَسۡـَٔلُونَكَ عَنِ ٱلۡمَحِيضِۖ قُلۡ هُوَ أَذࣰى فَٱعۡتَزِلُواْ ٱلنِّسَآءَ فِي ٱلۡمَحِيضِ وَلَا تَقۡرَبُوهُنَّ حَتَّىٰ يَطۡهُرۡنَۖ فَإِذَا تَطَهَّرۡنَ فَأۡتُوهُنَّ مِنۡ حَيۡثُ أَمَرَكُمُ ٱللَّهُۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّٰبِينَ وَيُحِبُّ ٱلۡمُتَطَهِّرِينَ نِسَآؤُكُمۡ حَرۡثࣱ لَّكُمۡ فَأۡتُواْ حَرۡثَكُمۡ أَنَّىٰ شِئۡتُمۡۖ﴾ [البقرة: ۲۲۲-۲۲۳] \"وہ لوگ آپ سے حیض کے بارے میں سوال کرتے ہیں۔کہہ دیجئےکہوہ گندگی ہے۔اس لیے حیض کے دنوں میں عورتوں سے الگ رہو اور (ہمبستری کےلیے)ان کےنزدیک نہ جاؤ،یہاں تک کہ وہ پاک ہوجائیں۔جب وہ پاک ہوجائیں تو ان کے پاس جاؤ جہاں سے اللہ تعالی نے تمھیں اجازت دی ہے۔بلاشبہ اللہ معافی مانگنے والوں اور پاک رہنے والوں سے محبت کرتاہے۔تمھاری عورتیں تمھارے لیے کھیتی کی طرح ہیں، جس طرح چاہو، اپنی کھیتی میں جاؤ\"۔\nحیض کی حالت میں عورتوں سے جماع منع ہے۔ جب وہ پاک ہوجائیں اور غسل کرلیں تو آگے سے مجامعت کی جاسکتی ہے،جس کے ذریعےسے اولاد پیدا ہوتی ہے۔عورتوں کے دُبر (پچھلے حصے) کو استعمال کرنا حرام ہے۔کیوں کہ اس کے ذریعے اولاد پیدا نہیں کی جاسکتی، جو مجامعت کا اصل مقصد ہے۔ حائضہ عورتوں کے بارے میں کچھ اسلامی احکام اس طرح ہیں:\n۱- حائضہ عورتوں کے لیے نماز کی ادائیگی ممنوع ہے۔\n۲- رمضان کے روزے رکھنا منع ہے۔لیکن جب وہ پاک ہوجائیں تو جتنے روزے چھوٹ گئے ہیں انھیں پورا کرنا لازم ہے،جن کو قضا کہتے ہیں۔\n۳- مکہ میں کعبہ کا طواف کرنا منع ہے۔اگروہ حج کرنے گئی ہیں تو ایسی حالت میں انتظار کریں،جب پاک ہوجائیں تو طواف کریں اور عمرہ کے دوسرے ارکان پورا کریں۔\n۴- حالت حیض میں عورتیں منی وعرفات میں جاسکتی ہیں،لیکن ’طواف افاضہ‘جو حج کا رکن ہے، نہیں کرسکتیں۔ بلکہ اپنے پاک صاف ہونے کا انتظارکریں گی۔البتہ ہاں ایسی حالت میں کہ ان کے ساتھی واپس جارہےہوں اوروہ اکیلی نہ رہ سکتی ہوں تووہ\"طواف افاضہ\"کرسکتی ہیں۔کیوں کہ اس طواف کے بغیر حج پورا نہیں ہوگا۔ ایسی عورتوں کے لیے علما کا فتوی ہے کہ خوب صفائی کرکےلنگوٹ باندھ لیں اور احتیاطاً ایک دم دیں، اگر دواؤوں کے ذریعے حیض کو ٹالا جاسکتا ہے تو ایسا کرنا بھی جائز ہے۔\n۵- ایسی عورت نہ قرآن چھو سکتی ہےاورنہ پڑھ سکتی ہے۔لیکن اگر قرآن کی معلمہ ہو تو اس کو چاہیے کہ ہاتھ میں دستانہ پہن لے اور قرآن کے اوراق کو کسی قلم وغیرہ سے الٹے۔اسی طرح اگروہ طالبہ ہے تو وہ بھی دستانہ پہن کر قرآن چھو سکتی ہے اور اسے پڑھ سکتی ہے۔کیوں کہ یہ ایک ضرورت ہے۔ورنہ ایسی حالت میں قرآن کو چھونا اور پڑھنا منع ہے۔\n۷- حیض ختم ہوتے ہی غسل لازمی ہے۔اگر وہ پانی نہ پاسکے یا پانی تو ہو،لیکن اس کے استعمال سے اسے نقصان پہنچنے کا اندیشہ ہو تو تیمم کر لےاور جیسے ہی یہ پریشانی دور ہو، غسل کر لے۔\n۸-ایسی خاتون سے صرف ہمبستری کرنا منع ہے۔ ورنہ اس کے ساتھ رہنا،سہنا،اٹھنا،بیٹھنا، کھانا، پینا،اس کو چھونا، بوس وکنار کرنا، پیار کرنااور ساتھ لیٹنا سب جائز ہے۔\nکچھ حدیثوں میں آیا ہے کہ ایسی حالت میں ہمبستری کرنے والا ایک دینا ر صدقہ کرے۔لیکن علماءکا کہنا ہے کہ وہ حدیثیں صحیح نہیں ہیں۔","",{}],[254,"§خاتم النبيين\nاللہ تعالی کا فرمان ہے:﴿مَّا كَانَ مُحَمَّدٌ أَبَآ أَحَدࣲ مِّن رِّجَالِكُمۡ وَلَٰكِن رَّسُولَ ٱللَّهِ وَخَاتَمَ ٱلنَّبِيِّـۧنَۗ وَكَانَ ٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمࣰ ا﴾ [الأحزاب: ۴۰] \"محمد تم لوگوں میں سے کسی کے باپ نہیں ہیں، وہ تو اللہ کے رسول اور انبیاء کے سلسلے کو ختم کرنے والے ہیں، اور اللہ ہر چیز کا علم رکھتا ہے\"۔\nاس آیت کریمہ میں اللہ تعالی نے ایک فتنے کا سد باب فرمایا ہے، درحقیقت اللہ کے رسول صلی اللہ علیہ وسلم نے زید بن حارثہ رضی اللہ عنہ کو اپنا منہ بولا بیٹا بنایا تھا، بعد کو ان کی طلاق شدہ بیوی سے نکاح بھی کرلیا، جس پر بعض منافقین اور کافروں نے شور مچایا کہ دیکھو محمد نے اپنے بیٹے کی مطلقہ سے نکاح کرلیا۔ اللہ تعالی نے ان کارد کرتے ہوئے یہ آیت نازل فرمائی کہ محمد صلی اللہ علیہ وسلم کسی شخص کے حقیقی باپ نہیں ہیں، بلکہ وہ تمام مسلمانوں کے مجازی والد ہیں اور آپ کی ازواج مطہرات ان کی مائیں ہیں۔ البتہ یہ ضرور ہے کہ وہ اللہ کے رسول اور انبیاء کے \"خاتم\" ہیں کہ ان کے بعد کوئی نبی نہیں آنے والا۔گویا اللہ تعالی نے \"نسبت ابوہ\" کو ختم کرکے \"نسبت نبوۃ\" اور \"ختم نبوت\" کو ثابت کیا ہے۔اور پھر یہ کہہ کر: [آیت] بیان فرمایا کہ اللہ ہی بہتر جانتا ہے کہ نبوت ورسالت کا مستحق کون ہے؟\nنبی اکرم صلی اللہ علیہ وسلم نے اپنی امت کو اس بات سے آگاہ کیا کہ اس دنیا میں تیس بڑے دجال اور کذاب آئیں گے جو نبوت کا دعوی کریں گے، ان میں سے ایک تو نبی کریم صلی اللہ علیہ وسلم کی وفات سے پہلے ظاہر ہوا جسے ابوبکر صدیق رضی اللہ عنہ نے اپنے دور خلافت میں قتل کیا۔ اس کے بعد بھی نبوت کے جھوٹے دعویدار اس دنیا میں پیدا ہوتے رہے ہیں اور قیامت تک یہ سلسلہ جاری رہے گا۔\nقرآن کریم نے نبوت ورسالت کے سلسلے میں کچھ اصولی باتیں بیان فرمائی ہیں جن کا سمجھنا ازحد ضروری ہے۔\nاللہ تعالی کا فرمان ہے:﴿وَمَآ أَرۡسَلۡنَا مِن رَّسُولٍ إِلَّا بِلِسَانِ قَوۡمِهِۦ لِيُبَيِّنَ لَهُمۡۖ فَيُضِلُّ ٱللَّهُ مَن يَشَآءُ وَيَهۡدِي مَن يَشَآءُۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ﴾ [إبراهیم: ۴] \"اور ہم نے جب بھی کوئی رسول بھیجا تو وہ اپنی قوم کی زبان جاننے والا ہوتا تھا، تاکہ وہ دین کی باتیں ان کے لئے کھول کر بیان کرے، پھر اللہ جسے چاہتا ہے گمراہ کردیتا ہے اور جسے چاہتا ہے ہدایت دیتا ہے، اور وہ بڑا زبردست، بڑی حکمتوں والا ہے\"۔\nیعنی ہر نبی اپنی قوم کی زبان میں دعوت وتبلیغ کا کام کرتا تھا اور اسی زبان میں اس پر وحی کا نزول ہوتا تھا۔ یہاں غور طلب بات یہ ہے کہ اللہ تعالی نے \"قوم\" کہا \"امت\" نہیں۔ اس لئے کہ امت میں بہت ساری قومیں اور زبانیں ہوتی ہیں، یہ امر محال ہے کہ ان تمام زبانوں میں وحی نازل کی جائے اور ان تمام زبانوں میں دعوت وتبیلغ کا کام ایک ہی نبی کو سونپا جائے۔\nاللہ تعالی نے اپنے آخری نبی محمد صلی اللہ علیہ وسلم پر عربی زبان میں وحی نازل کی، اس لئے کہ ان کے قوم کی زبان عربی تھی، البتہ امت محمدیہ میں عربی کے علاوہ اور بہت ساری زبانیں بولنے والے افراد موجود ہیں، لہٰذا نبی کے بعد اب دعاۃ اور مبلغین کی ذمہ داری بنتی ہے کہ وہ اپنی اپنی زبانوں میں نبوت ورسالت کے پیغام کو اپنی قوم تک پہنچائیں، یہی وجہ کہ قرآن کریم کا سینکڑوں زبانوں میں ترجمہ کیا گیا اور دنیا کے اطراف واکناف میں اسلام ڈنکا بجا۔ آج بھی الحمد للہ دعاۃ ومبلغین اپنے فریضے کو انجام دیتے ہوئے اپنی قوم کو انہیں کی زبان میں تبلیغ کرتے اور ان کی رہنمائی فرماتے ہیں۔\nانبیاء کرام اپنی طرف سے کتابیں تصنیف نہیں کرتے، بلکہ وہ تو محض وحی الہی کی تشریح کرتے ہیں۔ اسی لئے اللہ تعالی نے ایک جگہ ارشاد فرمایا:﴿وَلَوۡ تَقَوَّلَ عَلَيۡنَا بَعۡضَ ٱلۡأَقَاوِيلِ لَأَخَذۡنَا مِنۡهُ بِٱلۡيَمِينِ ثُمَّ لَقَطَعۡنَا مِنۡهُ ٱلۡوَتِينَ فَمَا مِنكُم مِّنۡ أَحَدٍ عَنۡهُ حَٰجِزِينَ﴾ [الحاقة: ۴۴-۴۷] \"اور اگر میرے نبی بعض باتیں گھڑ کر میری طرف منسوب کردیتے۔ تو ہم ان کا دایاں ہاتھ پکڑ لیتے۔ پھر ہم ان کی شہ رگ کاٹ دیتے۔ پھر تم میں سے کوئی ہمیں روکنے والا نہ ہوتا\"۔\nیعنی نبی صلی اللہ علیہ وسلم بھی اپنی طرف سے کتابیں لکھ کر ہماری طرف منسوب کرتے تو ہم ان کے بھی ہاتھ کاٹ دیتے۔ گویا کہ نبوت کے جھوٹے دعویدار کو اللہ دنیا میں ذلیل ورسوا کرے گا اور ان کے جھوٹ کو واضح کرکے رہے گا۔\nنبی اپنے اخلاق وکردار میں بلند مقام رکھتے ہیں۔ اللہ تعالی کا ارشاد ہے:﴿وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمࣲ‏﴾ [القلم: ۴] \"اور آپ یقینا عظیم اخلاق والے ہیں\"۔ یعنی نبوت سے پہلے بھی، اور نبوت کے بعد بھی۔\nسیدہ عائشہ رضی اللہ عنہا سے جب نبی اکرم صلی اللہ علیہ وسلم کے اخلاق کے بارے میں پوچھا گیا تو آپ نے فرمایا: \"کان خلقه القرآن\" مسند أحمد (۲۴۶۰۱)\nیعنی اگر کوئی قرآن کریم کو سمجھنا چاہتا ہے تو اسے نبی اکرم صلی اللہ علیہ وسلم کی سیرت کا مطالعہ کرنا چاہئے۔\nعام طور پر دنیا میں ظہور پذیر ہونے والے نبوت کے جھوٹے دعویدار وں کے اخلاق وکردار نہایت ہی خراب اور فاسد ہوا کرتے ہیں۔ سچے نبی کی ایک علامت یہ ہے کہ وہ وہ اخلاق وکردار کے اعلی مقام پر فائز ہوتا ہے۔\nنبی کا انتخاب قوم کے شریف ترین لوگوں میں سے ہوتا ہے۔\nآدم علیہ السلام کے متعلق قرآن میں کہا گیا کہ اللہ تعالی نے انہیں چن لیا ہے، جبکہ وہ اس دنیا کے پہلے انسان تھے اور اس وقت ان کے علاوہ کوئی اور نہ تھا، پھر بھی قرآن کہتا ہے:﴿وَعَصَىٰٓ ءَادَمُ رَبَّهُۥ فَغَوَىٰ ثُمَّ ٱجۡتَبَٰهُ رَبُّهُۥ فَتَابَ عَلَيۡهِ وَهَدَىٰ﴾ [ طه: ۱۲۱-۱۲۲] \"آدم نے اپنے رب کے حکم کی خلاف ورزی کی تو بھٹک گیا، پھر اس کے رب نے اس کو نوازا، اس کی توبہ قبول کی اور اس کو ہدایت بخشی\"۔\nاسی طرح ایک اور مقام پر ارشاد فرمایا:﴿مَّا كَانَ ٱللَّهُ لِيَذَرَ ٱلۡمُؤۡمِنِينَ عَلَىٰ مَآ أَنتُمۡ عَلَيۡهِ حَتَّىٰ يَمِيزَ ٱلۡخَبِيثَ مِنَ ٱلطَّيِّبِۗ وَمَا كَانَ ٱللَّهُ لِيُطۡلِعَكُمۡ عَلَى ٱلۡغَيۡبِ وَلَٰكِنَّ ٱللَّهَ يَجۡتَبِي مِن رُّسُلِهِۦ مَن يَشَآءُۖ فَـَٔامِنُواْ بِٱللَّهِ وَرُسُلِهِۦۚ وَإِن تُؤۡمِنُواْ وَتَتَّقُواْ فَلَكُمۡ أَجۡرٌ عَظِيمࣱ‏﴾ [آل عمران: ۱۷۹] \"اللہ تعالی مؤمنوں کو اس حال پر نہیں چھوڑنا چاہتا ہے جس پر تم لوگ ہو، یہاں تک کہ ناپاک کو پاک سے الگ کردے، اور نہ اللہ تمہیں غیب کی باتیں بتانا چاہتا ہے، لیکن اللہ اپنے رسولوں میں سے جنہیں چاہتا ہے چن لیتا ہے، پس تم اللہ اور اس کے رسول پر ایمان لے آؤ، اور اگر تم ایمان لے آؤگے اور تقوی کی راہ اختیار کروگے تو تمہیں بڑا اجر ملے گا\"۔\nاللہ تعالی کا یہ فرمان [آیت] یعنی یہ بات اللہ کی سنت کے خلاف ہے کہ وہ غیب سے ہر ایک کو واقف کرائے، بلکہ غیب کی باتوں کے لئے وہ اپنے رسولوں میں سے جن کو چاہتا ہے چن لیتا ہے، اور امور غیب میں سے سے جس چیز کے بارے میں چاہتا ہے انہیں آگاہ فرماتا ہے۔ گویا رسولوں کا چننا اور انہیں امور غیب سے واقف کرانا یہ سب اللہ تعالی نے اپنے ہاتھ میں رکھا ہے۔ کوئی خود ساختہ نہ رسول بن سکتا ہے اور نہ امور غیب سے واقف ہونے کا دعوی کرسکتا ہے۔\nاس کے علاوہ اللہ تعالی نے یونس علیہ السلام کے متعلق فرمایا:﴿فَٱجۡتَبَٰهُ رَبُّهُۥ فَجَعَلَهُۥ مِنَ ٱلصَّٰلِحِينَ﴾ [القلم: ۵۰] \"آخر کار اس کے رب نے اسے چن لیا اور اسے اپنے نیک وصالح بندوں میں شامل کرلیا\"۔\nیوسف علیہ السلام کے متعلق قرآن میں ہے:﴿وَكَذَٰلِكَ يَجۡتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِن تَأۡوِيلِ ٱلۡأَحَادِيثِ﴾ [یوسف: ۶] \"اور اس طرح تمہارا رب تمہیں چن لے گا اور تمہیں باتوں کی حقیقت تک پہنچادے گا\"۔\nنبوت کے انتخاب کے لئے قرآن مجید نے \"اصطفی\" کا لفظ بھی استعمال کیا ہے۔ اللہ تعالی کا ارشاد ہے:﴿إِنَّ ٱللَّهَ ٱصۡطَفَىٰٓ ءَادَمَ وَنُوحࣰ ا وَءَالَ إِبۡرَٰهِيمَ وَءَالَ عِمۡرَٰنَ عَلَى ٱلۡعَٰلَمِينَ﴾ [آل عمران: ۳۳] \"بے شک اللہ نے آدم، نوح، ابراہیم، اور آل عمران کو عالم کی رہنمائی کے لئے منتخب فرمایا\"۔\nیہاں آل عمران سے مراد سیدنا عیسی علیہ السلام ہیں۔ کیونکہ عمران بن ماتاں، عیسی علیہ السلام کی والدہ مریم کے والد تھے۔ آیت کریمہ میں ان کے ذکر کرنے کا مقصد یہ ہے کہ جب عیسی علیہ السلام کی والدہ، اور ان کے باپ دادا، یعنی عیسی علیہ السلام کے نانا اور نانا کے والد ایک عام انسان تھے، تو سیدنا عیسی علیہ السلام کو الوہیت کے مقام تک پہونچانا کیا معنی رکھتا ہے؟\nاسی طرح موسی علیہ السلام کے لئے بھی \"اصطفی\" کا لفظ وارد ہے۔ قرآن مجید میں ہے:﴿قَالَ يَٰمُوسَىٰٓ إِنِّي ٱصۡطَفَيۡتُكَ عَلَى ٱلنَّاسِ بِرِسَٰلَٰتِي وَبِكَلَٰمِي فَخُذۡ مَآ ءَاتَيۡتُكَ وَكُن مِّنَ ٱلشَّٰكِرِينَ﴾ [الأعراف: ۱۴۴] \"اے موسی! میں نے تمہیں لوگوں کے لئے اپنی رسالت وہم کلامی کے لئے منتخب کیا ہے، لہٰذا جو بھی میں نے تمہیں عطا کیا ہے اسے قبول کرو اور شکر گذار بندوں میں شامل ہوجاؤ\"۔\nاسی طرح فرشتوں اور انسانوں کو مخاطب کرکے فرمایا:﴿ٱللَّهُ يَصۡطَفِي مِنَ ٱلۡمَلَٰٓئِكَةِ رُسُلࣰ ا وَمِنَ ٱلنَّاسِۚ إِنَّ ٱللَّهَ سَمِيعُۢ بَصِيرࣱ‏﴾ [الحج: ۷۵] \"اللہ فرشتوں میں سے رسول کو منتخب کرتا ہے جس طرح وہ انسانوں میں سے چنتا ہے، بے شک اللہ تعالی سننے اور دیکھنے والا ہے\"۔\nیعنی یہ نادان، فرشتوں کو اللہ کی بیٹیاں سمجھ کر ان کی پوجا کرتے ہیں، جبکہ یہ بھی بالکل اسی طرح میرے پیغام رساں ہیں جس طرح انسانوں میں سے کچھ کو ہم نے پیغمبر بنایا ہیں۔\nمذکورہ آیتوں سے یہ بات واضح ہوجاتی ہے کہ انبیاء کرام اللہ تعالی کے برگزیدہ بندے ہیں، وہ جسے چاہتا ہے اس منصب کے لئے چن لیتا ہے۔یہ اس وقت تک نبوت ورسالت کا دعوی بھی نہیں کرسکتے جب تک کہ اللہ تعالی اپنی طرف سے ان کو منتخب نہ کرلے۔\nانبیاء کرام کے انتخاب کی بابت یہ وہ اصول وضوابط ہیں جنہیں بنیاد بنا کر انبیاء ورسل کو نبوت ورسالت کے لئے منتخب کیا جاتا ہے۔ نبوت ورسالت کا یہ سلسلہ اب ختم ہوچکا ہے، لہٰذا نبی اکرم محمد صلی اللہ علیہ وسلم کے بعد کوئی نبی اور رسول نہیں آسکتا، کیونکہ اس بات کی صراحت پیارے نبی صلی اللہ علیہ وسلم نے اپنی زبانی بھی کردی ہیں، اب اگر کوئی نبوت کا دعوی کرے گا تو حدیث کے مطابق اس کا شمار \"کذاب\" او ر \"دجالوں\" میں ہوگا۔","",{}],[255,"§خالق\nدیکھیے: اسماے حسنی","",{}],[256,"§خائن\nخیانت کو اردو میں دغابازی، بددیانتی، بے ایمانی اور امانت میں چوری کہتے ہیں۔اسی سے خائن کا لفظ ہے۔یعنی خیانت کرنےوالا۔ اللہ اوراس کےرسول اس بات کو پسند نہیں کرتے کہ کوئی شخص امانت میں خیانت کرے۔خواہ جس کے ساتھ یہ سلوک ہو وہ مسلمان ہو یا غیرمسلم۔ جب آپس میں کوئی عہد وپیمان اورمعاہدہ یا کسی بات پر اتفاق ہوجائے تو دوسرے کو بتائے بغیر یک طرفہ طور پر اس عہد و پیمان، معاہدہ کو توڑ نا، اس کی خلاف ورزی کرنا، دھوکا، فریب، غداری اور دغا بازی کہلاتا ہے۔\nقرآن کریم میں ہے:﴿وَإِمَّا تَخَافَنَّ مِن قَوۡمࣲ خِيَانَةࣰ فَٱنۢبِذۡ عَلَىٰ سَوَآءࣲۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡخَآئِنِينَ﴾ [الأنفال: ۵۸] \"اور اگر تم کو کسی قوم سے دغا بازی,خیانت کا خوف ہو تو (ان کا عہد و پیمان) ان کی طرف پھینک دو (اور) برابر (کا جواب دو) کچھ شک نہیں کہ اللہ تعالی خیانت کرنے والے، دغابازوں کو پسند نہیں کرتا\"۔\nاس سے اندازہ لگایا جا سکتا ہے کہ اسلام ہر معاملے میں حتی کہ حالت جنگ میں بھی دھوکا دہی، غداری، خیانت اور دغا بازی کو سخت ناپسند کرتا ہے۔ کیوں کہ یہ چیز اسلام کے منافی ہے۔ اللہ کے رسول کا فرمان ہے کہ ہم میں سے جو شخص دھوکا دہی، غدر و خیانت اور دغا بازی کرے وہ ہم مسلمانوں میں سے نہیں ہے۔","",{}],[257,"§خبیر\nدیکھیے: اسماے حسنی","",{}],[258,"§خچر\nدیکھیے: بغل","",{}],[259,"§ختنہ\nیہ لفظ قرآن مجید میں وارد نہیں، البتہ صحیح احادیث سے معلوم ہوتا ہے کہ ابراہیم علیہ السلام نے (۸۰) سال کی عمر میں خود اپنا ختنہ کیا۔ اسی طرح نبی اکرم صلی اللہ علیہ وسلم نے ختنہ کو پانچ فطری تقاضوں میں شمار کیا ہے۔ دیکھئے: صحیح بخاری (۵۸۸۹) وصحیح مسلم (۲۵۷)\nلوگ پوچھتے ہیں کہ آخر اللہ تعالی نے انسان کو سب سے بہتر اور اچھی صورت میں پیدا کیا ہے تو اسے ختنہ کرنے کی ضرورت کیوں درپیش ہوئی؟\nجواب: سب سے پہلی بات تو یہ کہ اللہ تعالی کے تخلیقی نظام میں ہمیں اعتراض کرنے کا کوئی حق نہیں ہے۔ انسانوں کو مختون پیدا کرنا اللہ تعالی کے لئے کوئی مشکل کام نہیں ہے، مگر چونکہ اسلام صفائی ستھرائی اور پاکیزگی کی تعلیم دیتا ہے تو اس کا تقاضہ ہے کہ وہ جس طرح ناخنوں کو کانٹنے اور مخصوص اعضاء کے بال کو صاف کرنے کا حکم دیتا ہے تاکہ عام طور جسم کے ان حصوں میں پیدا ہونے والی گندگی صاف ہوجائے، بالکل اسی طرح اس نے ختنہ کرنے کا بھی حکم دیا ہے تاکہ وہاں کی گندگی بھی صاف ہوجائے کہ اس کے اندرایم مدت کے بعد خطرناک جراثیم پیدا ہوجاتے ہیں۔\nآپ نے سوشل میڈیا یا اخبار میں ضرور پڑھا یا دیکھا ہوگا کہ ختنہ نہ کرنے والوں میں ایک جان لیوامرض پیدا ہوگیا۔ یہی وجہ ہے کہ بہت سارے لوگ اس مرض کے خوف سے اپنا ختنہ کرواتے ہیں۔\nابراہیم علیہ السلام نے اپنا ختنہ کرکے ایک سنت کو جاری فرمایا جو آپ کی نسل میں چلتی رہی، چنانچہ جب اسماعیل علیہ السلام تیرہ برس کے ہوئے تو ان کی ختنہ کی گئی، جسے \"سفر پیدائش \"(۱۷: ۲۶) میں بڑی تفصیل کے ساتھ ختنہ کے احکام کے ضمن میں ذکر کیا گیا ہے۔\nیہ سنت سیدنا موسی علیہ السلام تک چلتی رہی، انہوں نے بھی اس کو رواج دیا جیساکہ\" سفر احبار\"(۱۲: ۳) میں اس کا تذکرہ ملتا ہے۔ اس کے بعد بھی یہ سلسلہ جاری رہا یہاں تک کہ بولس یہودی نے جب عیسائیت کا دعوی کیا تو بنی اسرائیل کے علاوہ دیگر اقوام کو بھی عیسائیت میں داخل کرنے کا اعلان کیا، جو ختنہ نہیں کرتے تھے۔ پھر اس کے بعد \"ختنہ\" کو منسوخ ٹھہرایا اور لوگوں کو اس نے باور کرایا کہ \"خلاص\" یعنی گناہوں سے نجات حاصل کرنے کے لئے ختنہ کرنا ضروری نہیں۔ اسی لئے وہ عیسائی جو بنی اسرائیل کی نسل سے نہیں ہیں وہ آج بھی ختنہ نہیں کرتے جبکہ یہودی ختنہ کے قائل ہیں۔\nنبی اکرم صلی اللہ علیہ وسلم کو جب اللہ تعالی نے خاتم النبیین بناکر مبعوث فرمایا تو آپ کی زبانی دوبارہ ختنہ کی سنت کو جاری فرمایا۔\nکچھ لوگ یہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم مختون پیدا ہوئے تھے، یہ بات صحیح احادیث سے ثابت نہیں، البتہ صحیح روایتوں سے پتہ چلتا ہے کہ آپ صلی اللہ علیہ وسلم کا ختنہ آپ کے بچپن ہی میں مکہ کے معاشرتی اصولوں کے تحت ہوا تھا جسے اہل مکہ دین ابراہیم کی سنت مانتے تھے۔\nنبی اکرم صلی اللہ علیہ وسلم نے ختنہ کو فطرت کے تقاضوں میں شمار کرکے اسے اپنی امت میں قیامت تک کے لئے جاری فرما دیا۔\nکچھ لوگ یہ سوال کرتے ہیں کہ ختنہ کرنے کا صحیح وقت کیا ہے؟ تو اس کا جواب یہ ہے کہ اس کا کوئی وقت متعین نہیں، البتہ بچے کا ختنہ جتنی جلد ممکن ہوسکے وہ اس کے حق میں بہتر ہے۔\nختنہ سے متعلق مزید تفصیل کے لئے میری کتاب \"الجامع الکامل\" ملاحظہ فرمائیں۔","",{}],[260,"§خریدوفروخت\nدیکھیے: تجارت","",{}],[261,"§خضر علیہ السلام\nخضر علیہ السلام اللہ تعالی کے ایک صالح بندے اورنبی کانام ہے، جن کے بارے میں آتا ہے کہ وہ زمین پرجس جگہ بیٹھ جاتے، وہ سرسبز ہوکر لہلہانے لگتی۔(صحیح البخاری: ۳۴۰۲) اس لیے ان کا نام’خضر‘ پڑ گیا۔ خضرکےمعنی ہیں ہرا رنگ۔قرآن کریم میں تو آپ کا نام نہیں آیا ہے، لیکن سورہ الکہف میں موسیٰ علیہ السلام کی کہانی میں جس بندے کا بیان آیا ہے، صحیح حدیثوں میں انھیں خضر علیہ السلامبتایا گیا ہے۔قرآن کریم میں ان کا جو واقعہ آیا ہے اسےبیان کیا جاتا ہے:﴿وَإِذۡ قَالَ مُوسَىٰ لِفَتَىٰهُ لَآ أَبۡرَحُ حَتَّىٰٓ أَبۡلُغَ مَجۡمَعَ ٱلۡبَحۡرَيۡنِ أَوۡ أَمۡضِيَ حُقُبࣰ ا فَلَمَّا بَلَغَا مَجۡمَعَ بَيۡنِهِمَا نَسِيَا حُوتَهُمَا فَٱتَّخَذَ سَبِيلَهُۥ فِي ٱلۡبَحۡرِ سَرَبࣰ ا فَلَمَّا جَاوَزَا قَالَ لِفَتَىٰهُ ءَاتِنَا غَدَآءَنَا لَقَدۡ لَقِينَا مِن سَفَرِنَا هَٰذَا نَصَبࣰ ا قَالَ أَرَءَيۡتَ إِذۡ أَوَيۡنَآ إِلَى ٱلصَّخۡرَةِ فَإِنِّي نَسِيتُ ٱلۡحُوتَ وَمَآ أَنسَىٰنِيهُ إِلَّا ٱلشَّيۡطَٰنُ أَنۡ أَذۡكُرَهُۥۚ وَٱتَّخَذَ سَبِيلَهُۥ فِي ٱلۡبَحۡرِ عَجَبࣰ ا قَالَ ذَٰلِكَ مَا كُنَّا نَبۡغِۚ فَٱرۡتَدَّا عَلَىٰٓ ءَاثَارِهِمَا قَصَصࣰ ا فَوَجَدَا عَبۡدࣰ ا مِّنۡ عِبَادِنَآ ءَاتَيۡنَٰهُ رَحۡمَةࣰ مِّنۡ عِندِنَا وَعَلَّمۡنَٰهُ مِن لَّدُنَّا عِلۡمࣰ ا قَالَ لَهُۥ مُوسَىٰ هَلۡ أَتَّبِعُكَ عَلَىٰٓ أَن تُعَلِّمَنِ مِمَّا عُلِّمۡتَ رُشۡدࣰ ا قَالَ إِنَّكَ لَن تَسۡتَطِيعَ مَعِيَ صَبۡرࣰ ا وَكَيۡفَ تَصۡبِرُ عَلَىٰ مَا لَمۡ تُحِطۡ بِهِۦ خُبۡرࣰ ا قَالَ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ صَابِرࣰ ا وَلَآ أَعۡصِي لَكَ أَمۡرࣰ ا قَالَ فَإِنِ ٱتَّبَعۡتَنِي فَلَا تَسۡـَٔلۡنِي عَن شَيۡءࣲ حَتَّىٰٓ أُحۡدِثَ لَكَ مِنۡهُ ذِكۡرࣰ ا فَٱنطَلَقَا حَتَّىٰٓ إِذَا رَكِبَا فِي ٱلسَّفِينَةِ خَرَقَهَاۖ قَالَ أَخَرَقۡتَهَا لِتُغۡرِقَ أَهۡلَهَا لَقَدۡ جِئۡتَ شَيۡـࣰٔا إِمۡرࣰ ا قَالَ أَلَمۡ أَقُلۡ إِنَّكَ لَن تَسۡتَطِيعَ مَعِيَ صَبۡرࣰ ا قَالَ لَا تُؤَاخِذۡنِي بِمَا نَسِيتُ وَلَا تُرۡهِقۡنِي مِنۡ أَمۡرِي عُسۡرࣰ ا فَٱنطَلَقَا حَتَّىٰٓ إِذَا لَقِيَا غُلَٰمࣰ ا فَقَتَلَهُۥ قَالَ أَقَتَلۡتَ نَفۡسࣰ ا زَكِيَّةَۢ بِغَيۡرِ نَفۡسࣲ لَّقَدۡ جِئۡتَ شَيۡـࣰٔ ا نُّكۡرࣰ ا قَالَ أَلَمۡ أَقُل لَّكَ إِنَّكَ لَن تَسۡتَطِيعَ مَعِيَ صَبۡرࣰ ا قَالَ إِن سَأَلۡتُكَ عَن شَيۡءِۭ بَعۡدَهَا فَلَا تُصَٰحِبۡنِيۖ قَدۡ بَلَغۡتَ مِن لَّدُنِّي عُذۡرࣰ ا فَٱنطَلَقَا حَتَّىٰٓ إِذَآ أَتَيَآ أَهۡلَ قَرۡيَةࣲ ٱسۡتَطۡعَمَآ أَهۡلَهَا فَأَبَوۡاْ أَن يُضَيِّفُوهُمَا فَوَجَدَا فِيهَا جِدَارࣰ ا يُرِيدُ أَن يَنقَضَّ فَأَقَامَهُۥۖ قَالَ لَوۡ شِئۡتَ لَتَّخَذۡتَ عَلَيۡهِ أَجۡرࣰ ا قَالَ هَٰذَا فِرَاقُ بَيۡنِي وَبَيۡنِكَۚ سَأُنَبِّئُكَ بِتَأۡوِيلِ مَا لَمۡ تَسۡتَطِع عَّلَيۡهِ صَبۡرࣰ ا أَمَّا ٱلسَّفِينَةُ فَكَانَتۡ لِمَسَٰكِينَ يَعۡمَلُونَ فِي ٱلۡبَحۡرِ فَأَرَدتُّ أَنۡ أَعِيبَهَا وَكَانَ وَرَآءَهُم مَّلِكࣱ يَأۡخُذُ كُلَّ سَفِينَةࣲ غَصۡبࣰ ا وَأَمَّا ٱلۡغُلَٰمُ فَكَانَ أَبَوَاهُ مُؤۡمِنَيۡنِ فَخَشِينَآ أَن يُرۡهِقَهُمَا طُغۡيَٰنࣰ ا وَكُفۡرࣰ ا فَأَرَدۡنَآ أَن يُبۡدِلَهُمَا رَبُّهُمَا خَيۡرࣰ ا مِّنۡهُ زَكَوٰةࣰ وَأَقۡرَبَ رُحۡمࣰ ا وَأَمَّا ٱلۡجِدَارُ فَكَانَ لِغُلَٰمَيۡنِ يَتِيمَيۡنِ فِي ٱلۡمَدِينَةِ وَكَانَ تَحۡتَهُۥ كَنزࣱ لَّهُمَا وَكَانَ أَبُوهُمَا صَٰلِحࣰ ا فَأَرَادَ رَبُّكَ أَن يَبۡلُغَآ أَشُدَّهُمَا وَيَسۡتَخۡرِجَا كَنزَهُمَا رَحۡمَةࣰ مِّن رَّبِّكَۚ وَمَا فَعَلۡتُهُۥ عَنۡ أَمۡرِيۚ ذَٰلِكَ تَأۡوِيلُ مَا لَمۡ تَسۡطِع عَّلَيۡهِ صَبۡرࣰ ا﴾ [الکهف: ۶۰-۸۲] \"یاد کرو جب موسیٰ نے اپنے غلام سے کہا: جب تک کہ میں دو دریاؤں کے سنگم پر نہ پہنچ جاؤں چلنا نہیں چھوڑوں گا، چاہے میں ایک طویل عرصے تک چلتا رہوں۔ جب وہ دونوں (دو دریاؤں کے) سنگم پر پہنچے تو وہ اپنی مچھلی سے غافل ہوگئے اور اس (مچھلی)نے دریامیں سرنگ جیسے راستے پر چلی گئی۔پھر جب وہ آگے چلے تو (موسیٰ علیہ السلام نے) اپنے غلام سے کہا: ہمارے دن کا کھانا ہمیں دو۔ اپنے اس سفر میں تو ہمیں بہت تھکاوٹ پہنچی ہے۔اس نے کہا: کیا آپ نے دیکھا، جب ہم اس چٹان کےپاس ٹھیرے ہوے تھے، تو میں مچھلی بھول گیا اور شیطان ہی نے مجھےبھلادیا کہ میں اس کا ذکر کرتا اور اس نے دریا میں عجیب انداز سے اپنی راہ لی۔ (موسیٰ نے) کہا:یہی وہ جگہ ہے جو ہم چاہتے تھے۔پھر وہ دونوں اپنے پاؤں کی نشانیوں کو دیکھتے ہوے واپس ہوے۔تو انھوں نے ہمارے بندوں میں سے ایک بندے کو پایا، جسے ہم نے اپنے پاس سے خاص رحمت عطا کی تھی اور جسے ہم نے اپنے پاس سے خاص علم سکھایا تھا۔ موسیٰ نے اس سے کہا:کیا میں آپ کے ساتھ رہ سکتا ہوں، تاکہ آپ مجھے اس سوجھ بوجھ اور نیک باتوں کی تعلیم دیں جن کی تعلیم آپ کو دی گئی ہے؟اس نے کہا:آپ میرےساتھ صبر نہ کر سکیں گے اور جوچیز آپ کے علم کے دائرے سے باہر ہو اس پر آپ صبربھی کیسے کرسکتےہیں؟(موسیٰ نے)کہا،اللہ نے چاہا، توآپ مجھے صبرکرنے والوں میں سے پائیں گے اور میں کسی حکم کو نہ ٹالوں گا۔ اس نے کہا:اچھا، اگر آپ میرے ساتھ چلتے ہیں، تومجھ سے کوئی بات نہ پوچھیں،جب تک کہ میں خود آپ سے اس کا ذکر نہ کروں۔اب دونوں چلے، یہاں تک کہ جب کشتی میں سوار ہوے تو اس نے اس میں سوراخ کر دیا۔ (موسیٰ نے ) کہا:کیا آپ نے اس میں سوراخ کردیا تاکہ اس (کشتی) کے لوگوں کو ڈبودیں؟ آپ نے تو ایک عجیب حرکت کر ڈالی۔ اس نے کہا:کیا میں نے کہا نہیں تھا کہ آپ میرے ساتھ صبر نہیں کر سکیں گے؟(موسیٰ نے ) کہا:جو غلطی مجھ سے ہوئی اس پر میری گرفت نہ کریں، میرے سلوک پر آپ مجھ پر سختی نہ برتیں۔پھر وہ دونوں چلے یہاں تک کہ وہ ایک لڑکے سے ملے، تو اس نے لڑکے کو قتل کردیا۔(موسیٰ نے) کہا:کیا آپ نے ایک بے قصور جان کی بغیر کسی جان کے (قتل کے) بدلے قتل کر ڈالا؟ آپ نے بہت ہی برا کا م کیا۔اس نے کہا:کیا میں نے آپ سے کہا نہیں تھا کہ آپ میرے ساتھ صبر نہ کرسکیں گے؟موسیٰ نے کہا:اس کے بعد اگر میں آپ سے کچھ سوال کروں، تو آپ مجھے اپنے ساتھ نہ رکھیں۔اب میری طرف سے آپ تک معذرت پورے طور پرپہنچ چکے ہیں۔پھر وہ دونوں چلے، یہاں تک ایک بستی کے لوگوں تک پہنچے، تو وہاں کے لوگوں سے کھانا مانگا، لیکن انھوں نے انھیں مہمان بنانے سے انکار کردیا۔ پھر وہاں انھیں ایک دیوار ملی جو گری جارہی تھی تو اس نے اسے سیدھا کھڑا کردیا۔(موسیٰ نے) کہا:اگر آپ چاہتے، تواس کی اجرت لے سکتے تھے۔اس نے کہا: یہ میرے اور آپ کے درمیان جدائی ہے! میں آپ کو ان (امور)کی حقیقت بتادے رہاہوں جن پر آپ صبر نہ کرسکے۔ وہ جو کشتی تھی وہ محتاجوں کی تھی جو دریا میں کام کرتے تھے، میں نے چاہا کہ اسے عیب دار کردوں، کیونکہ وہاں پر ایک بادشاہ تھا جو ہر کشتی کو چھین لیتا تھا۔ رہا وہ لڑکا، تو اس کے ماں باپ ایمان والے تھے۔ ہمیں خوف تھا کہ وہ (اپنی) سرکشی اور کفر سے انھیں تنگ کرے گا۔ اس لیے ہم نے چاہا کہ ان کا رب انھیں اس کے بدلے دوسری (اولاد) دے جو نیکی میں اس ِسے اچھا اور رحم کرنے والاہو۔ اور رہی دیوار تویہ دو یتیم بچوں کی ہے، جو اس بستی میں رہتے ہیں اور اس(دیوار)کے نیچےان (بچوں)کا ایک خزانہ ہے اور ان کا باپ نیک تھا، تو آپ کے رب نے چاہا کہ وہ (بچے) ہوشمند ہوجائیں اور اپنا خزانہ نکال لیں، یہ آپ کے رب کی رحمت کی وجہ سے ہوا اورمیں نے کچھ اپنے حکم سے نہیں کیا۔ یہ ہے حقیقت ان چیزوں کی جن پر آپ صبر نہ کر سکے\"۔\nصحیح بخاری میں ہے: «عَنْ ابْنِ عَبَّاسٍ أَنَّهُ تَمَارَی هُوَ وَالْحُرُّ بْنُ قَيْسِ بْنِ حِصْنٍ الْفَزَارِيُّ فِي صَاحِبِ مُوسَی، قَالَ ابْنُ عَبَّاسٍ: هُوَ خَضِرٌ، فَمَرَّ بِهِمَا أُبَيُّ بْنُ کَعْبٍ فَدَعَاهُ ابْنُ عَبَّاسٍ فَقَالَ: إِنِّي تَمَارَيْتُ أَنَا وَصَاحِبِي هَذَا فِي صَاحِبِ مُوسَی الَّذِي سَأَلَ مُوسَی السَّبِيلَ إِلَی لُقِيِّهِ، هَلْ سَمِعْتَ النَّبِيَّ صلی اللہ علیہ وسلم يَذْکُرُ شَأْنَهُ؟ قَالَ: نَعَمْ سَمِعْتُ رَسُولَ اللَّهِ صلی اللہ علیہ وسلم يَقُولُ: بَيْنَمَا مُوسَی فِي مَلإٍ مِنْ بَنِي إِسْرَائِيلَ جَاءَهُ رَجُلٌ فَقَالَ: هَلْ تَعْلَمُ أَحَدًا أَعْلَمَ مِنْکَ؟ قَالَ مُوسَی: لا، فَأَوْحَی اللَّهُ عَزَّ وَجَلَّ إِلَی مُوسَی: بَلَی عَبْدُنَا خَضِرٌ، فَسَأَلَ مُوسَی السَّبِيلَ إِلَيْهِ، فَجَعَلَ اللَّهُ لَهُ الْحُوتَ آيَةً، وَقِيلَ لَهُ: إِذَا فَقَدْتَ الْحُوتَ فَارْجِعْ فَإِنَّکَ سَتَلْقَاهُ، وَکَانَ يَتَّبِعُ أَثَرَ الْحُوتِ فِي الْبَحْرِ، فَقَالَ لِمُوسَی فَتَاهُ: أَرَأَيْتَ إِذْ أَوَيْنَا إِلَی الصَّخْرَةِ فَإِنِّي نَسِيتُ الْحُوتَ وَمَا أَنْسَانِيهِ إِلا الشَّيْطَانُ أَنْ أَذْکُرَهُ، قَالَ: ذَلِکَ مَا کُنَّا نَبْغِي فَارْتَدَّا عَلَی آثَارِهِمَا قَصَصًا فَوَجَدَا خَضِرًا فَکَانَ مِنْ شَأْنِهِمَا الَّذِي قَصَّ اللَّهُ عَزَّ وَجَلَّ فِي کِتَابِهِ». (صحیح البخاری: ۷۴) \"عبداللہ بن عباس اور حر بن قیس کے درمیان ایک بار موسی علیہ السلام والے آدمی کے بارے میں بحث ہوئی۔ ابن عباس رضی اللہ عنہما نے کہا کہ وہ خضر علیہ السلام تھے۔ اتنے میں ابی بن کعب رضی اللہ عنہ کا وہاں سےگزر ہوا، ابن عباس نے انھیں بلایا اور کہا: میرے اور میرے ان ساتھی کے درمیان یہ بات موضوع بحث ہے کہ موسی علیہ السلام والے آدمی کون تھے جن تک پہنچنے کا راستا موسی علیہ السلام نے اللہ سے پوچھا تھا۔ کیا آپ نے اس بارے میں رسول اللہ صلی اللہ علیہ وسلم سے کچھ سنا ہے؟ تو ابی بن کعب رضی اللہ عنہ نےفرمایا:ہاں میں نے سنا کہ آپ فرمارہے تھے۔ایک بار موسیٰ علیہ السلام بنی اسرائیل میں تقریر کرنے کے لیے کھڑے ہوے، تو ایک شخص نے آپ سے پوچھا: کیا آپ اپنے سے کسی بڑے عالم کو جانتے ہیں؟موسی علیہ السلام نے جواب دیا: نہیں، تب اللہ نے موسیٰ علیہ السلام کو وحی کے ذریعے سے بتایا: کیوں نہیں،ہمارا بندہ خضر آپ سے بڑا عالم ہے۔ موسی علیہ السلام نے ان سے ملنے کی خواہش ظاہر کی، تو اللہ نے مچھلی کو علامت بناکر بتایا کہ جہاں وہ سمند ر میں چلی جائے گی، وہاں میرا بندہ ملے گااور پھر ایسا ہی ہوا، جس طرح قرآن نے بیان کیا ہے\"۔\nصحیح بخاری کی ایک دوسری روایت میں ہے:\n\"ایک بار نوف بکالی نے کہا کہ موسیٰ علیہ السلام والے صاحب خضر نہیں ہیں تو ابن عباس رضی اللہ عنہما نے نوف کو غلط ٹھیرایا اور عرض کیا کہ ابی بن کعب رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے سنا ہے کہ جب موسی علیہ السلام سے ان سے بڑے عالم کے بارے میں پوچھا گیا تو انھوں نے نفی میں جواب دیا۔ اس پر اللہ تعالی نے ان کو اپنے بندےسے ملنے کا حکم دیا اور ان سے ملنے کی نشانی بتائی۔ پس جب اس جگہ موسی علیہ السلام اور ان کے خادم پہنچے تو ایک آدمی چادر ڈھانکے ہوے ملا۔ موسی علیہ السلام نےسلام کیا توخضر علیہ السلام نےکہا: اس سرزمین میں سلام کہاں؟ تو موسی علیہ السلام نے کہا: میں موسی ہوں۔ خضر علیہ السلام نے پوچھا: کیا بنی اسرائیل کے موسی؟ کہا: ہاں، میں آپ کے پاس اس لیےآیا ہوں کہ آپ مجھے اس علم سے باخبر کر یں جو اللہ تعالی نے آپ کو عطا کیا ہے۔ خضر علیہ السلام نے کہا: موسی! آپ میرا ساتھ نہیں دے سکیں گے۔ اللہ نے جو علم مجھے عطا کیا ہے وہ آپ کے پاس نہیں ہے اور اللہ تعالی نے جو علم آپ کو عطا کیا ہے وہ میرے پاس نہیں ہے۔موسی علیہ السلام نے کہا: ان شاء اللہ آپ مجھ کو صبر کرنے والا پائیں گے۔ میں آپ کی مخالفت نہیں کروں گا۔ خضر علیہ السلام نے کہا: اگر آپ کو میری پیروی کرنی ہے تو کسی چیز کے بارے میں اس وقت تک سوال نہ کریں جب تک کہ خود میں اس کا ذکر نہ کردوں۔ وہ دونوں ساحل دریا پر چلتے ہوے آگے بڑھے،ایک کشتی آئی، ان لوگوں نےکشتی والوں سے بات کی کہ دریا پار کرادیں، کشتی والے نے خضر علیہ السلام کو پہچان لیا اور مفت میں سوار کرلیا، دونوں جوں ہی کشتی میں سوار ہوے خضر علیہ السلام نے کشتی کا ایک تختہ اُکھاڑ ڈالا۔ موسی علیہ السلام نے کہا: کشتی والوں نے بغیر کرایہ کے ہم کو سوار کرلیا تب بھی آپ نے ان کی کشتی کا ایک تختہ اکھاڑ دیا تاکہ اس کے سوار ڈوب جائیں، آپ نے بڑا غلط کام کیا،خضر علیہ السلام نے کہا: کیا میں نے یہ نہیں کہاتھا کہ آپ میرے ساتھ صبر نہیں کرپائیں گے؟موسی علیہ السلام نے کہا: میری بھول پر میری گرفت نہ کیجیےاور مجھے پریشانی میں نہ ڈالیے۔ رسول اکرم صلی اللہ علیہ وسلم نے فرمایا: موسی علیہ السلام کی یہ پہلی بھول تھی۔ آپ نے یہ بھی فرمایا: ایک چڑیا نے آکر ایک چونچ پانی میں ماری، اس پر خضر علیہ السلام نے موسی علیہ السلام سے کہا: اے موسی!میرا اور آپ کا علم اللہ تعالی کےعلم کے مقابلے میں ایسا ہی ہے جیسے چڑیا کا دریا سے ایک قطرہ پانی لینا۔پھر وہ لوگ کشتی سے باہر نکل کرساحل پر چلتے رہے۔ اتنے میں خضر علیہ السلام نے ایک بچے کو دیگر بچوں کےساتھ کھیلتے ہوے دیکھا تو سر پکڑ کر اسے قتل کرڈالا۔ موسی علیہ السلام نے کہا: آپ نے ایک بے قصور جان کو بغیر قصاص کے مار ڈالا؟ آپ نے بڑا غلط کام کیا۔ اس پرخضر علیہ السلام نے عرض کیا: کیا میں نے یہ نہیں کہا تھا کہ آپ میرے ساتھ صبر نہ کرپائیں گے؟ یہ تو پہلی غلطی سے بڑی غلطی ہے۔موسی علیہ السلام نے کہا: اگر اس کے بعد میں نے آپ سے کچھ پوچھا (اعتراض کیا) تو اس کے بعد آپ مجھے اپنے ساتھ نہ رکھیں۔ آپ میرے بارے میں معذور ہوں گے۔ وہ آگے بڑھے،یہاں تک کہ ایک بستی میں آئے، بستی والوں سے میزبانی کے لیےکہاتو انھوں نے انکار کردیا۔ان دونوں نے بستی میں ایک دیوار دیکھی جوگری جارہی تھی، خضر علیہ السلام نے اسے سیدھی کردی، موسی علیہ السلام نے کہا: ان لوگوں نے ہمیں کھانا کھلانے سے انکار کیا، آپ چاہتے تو آپ اس کی مزدوری لے لیتے۔ خضر علیہ السلام نے کہا: اب میرے اور آپ کے درمیان جدائی ہے۔ نبی اکرم صلی اللہ علیہ وسلم نےفرمایا: کاش موسی علیہ السلام صبر کا دامن نہ چھوڑتے تواللہ تعالیٰ ہمیں ان کی مزید باتیں بتاتا (راوی حدیث) سعید بن جبیر رضی اللہ عنہ کہتے ہیں: ابن عباس رضی اللہ عنہما (سورہ الکہف کی یہ آیت) پڑھا کرتے تھے: +وًَکَانَ أَمَامَهُمْ مَلِکٌ يَأْخُذُ کُلَّ سَفِينَةٍ صَالِحَةٍ غَصْبًا\" (آگے ایک بادشاہ تھا جو ہر اچھی کشتی کوزبردستی غصب کرلیا کرتا تھا) ابن عباس یہ بھی پڑھا کرتے تھے: +وَأَمَّا الْغُلامُ فَکَانَ کَافِرًا وَکَانَ أَبَوَاهُ مُؤْمِنَيْنِ\" (یعنی لڑکا کافر تھا اور اس کے والدین مومن تھے)\"۔\nمختصریہ کہ اللہ تعالیٰ نے خضر کوغیب کی باتیں بھی بتائی تھیں اور موسی علیہ السلام کو ظاہری شریعت کا علم عطا کیا تھاکیونکہ بنی اسرائیل کی اصلاح کے لیے ظاہری علم ہی سے کام لیا جاسکتا تھا۔ جب کہ خضر کو ان غیبی باتوں کے علم دینے کا مطلب اورموسی علیہ السلام سےاس ملاقات میں یہ بتانامقصودتھاکہ اس دنیا میں اللہ تعالیٰ کے ایسے بندے بھی ہیں، جن کے پاس موسی علیہ السلام زیادہ علم ہے۔ارشادباری تعالیٰ ہے:﴿وَفَوۡقَ كُلِّ ذِي عِلۡمࣲ عَلِيمࣱ﴾ [یوسف: ۷۶] \"یعنی: ہر عالم سے اونچا بھی کوئی عالم ہوتا ہے\"۔\nہمارا علم بھی خضر کے بارے میں اس سے زیادہ نہیں ہے۔ہمارا اپنا ایمان یہ ہے کہ وہ ایک نیک بندے ہی نہیں بل کہ اللہ کے نبی بھی تھے، جن کو اللہ تعالیٰ نے علم غیب عطاکیاتھا، جیساکہ ارشادباری ہے : ﴿فَوَجَدَا عَبۡدࣰ ا مِّنۡ عِبَادِنَآ ءَاتَيۡنَٰهُ رَحۡمَةࣰ مِّنۡ عِندِنَا وَعَلَّمۡنَٰهُ مِن لَّدُنَّا عِلۡمࣰ ا﴾ [الکهف: ۶۵] \"پس ہمارے بندوں میں سے ایک بندے کو پایا، جسے ہم نے اپنے پاس کی خاص رحمت عطا فرما رکھی تھی اور اسے اپنے پاس سے خاص علم سکھا رکھا تھا\"۔\nخضر علیہ السلام کے بارے میں قدیم زمانے سے اختلاف رہاہے کہ وہ نبی ہیں یاولی یا فرشتہ اوروہ زندہ ہیں یامردہ۔صحیح یہ ہے کہ وہ نبی تھے، جس کی دلیل قرآن کریم کی یہ آیت کریمہ ہے: ﴿فَوَجَدَا عَبۡدࣰ ا مِّنۡ عِبَادِنَآ ءَاتَيۡنَٰهُ رَحۡمَةࣰ مِّنۡ عِندِنَا وَعَلَّمۡنَٰهُ مِن لَّدُنَّا عِلۡمࣰ ا﴾ [الکهف: ۶۵] \" جسے ہم نے اپنے پاس کی خاص رحمت عطا فرما رکھی تھی اور اسے اپنے پاس سے خاص علم سکھا رکھا تھا\"۔\nاللہ تعالیٰ کا یہ تخاطب انبیاکے ساتھ ہی ہوسکتا ہے۔ باقی یہ کہنا کہ وہ فرشتہ تھے اور اب تک زندہ ہیں، ان باتوں کی قرآن وحدیث میں کوئی دلیل نہیں ہے۔ اگروہ زندہ ہوتے تو یقیناً نبی اکرم صلی اللہ علیہ وسلم کی زیارت کے لیے تشریف لاتے۔","",{}],[262,"§خلاق\nدیکھیے: اسماے حسنی","",{}],[263,"§خلع\nجس طرح طلاق کے ذریعے سےشوہر اپنی بیوی سے الگ ہوسکتا ہے، اسی طرح خلع کے ذریعے سےبیوی اپنے شوہر سے الگ ہوسکتی ہے۔ یہ بھی مذہب اسلام کی ایک خُصوصيت ہے کہ اس نے مرد وعورت دونوں کواس مسئلے میں برابر کاحق دیا ہے۔کیونکہ جس طرح کوئی شوہر اپنی بیوی کے برے برتاؤ سے تنگ آکر اس کے ساتھ خوش گوار اور پرسکون زندگی نہیں گزارسکتا۔اسی طرح عورت اپنے شوہر کی بد اخلاقی اور برے برتاؤ سےتنگ آکراس کے ساتھ خوش گوار زندگی نہیں گزار سکتی۔ اس لیے اسلام نے عورت کو بھی اپنے شوہرسے الگ ہونے کا حق دیا ہے، جس کوشریعت کی اصطلاح میں\" خلع\" کہتے ہیں۔قرآن مجیدمیں آیا ہے:﴿ٱلطَّلَٰقُ مَرَّتَانِۖ فَإِمۡسَاكُۢ بِمَعۡرُوفٍ أَوۡ تَسۡرِيحُۢ بِإِحۡسَٰنࣲۗ وَلَا يَحِلُّ لَكُمۡ أَن تَأۡخُذُواْ مِمَّآ ءَاتَيۡتُمُوهُنَّ شَيۡـًٔا إِلَّآ أَن يَخَافَآ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِۖ فَإِنۡ خِفۡتُمۡ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِ فَلَا جُنَاحَ عَلَيۡهِمَا فِيمَا ٱفۡتَدَتۡ بِهِۦۗ تِلۡكَ حُدُودُ ٱللَّهِ فَلَا تَعۡتَدُوهَاۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَأُوْلَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ﴾ [البقرة: ۲۲۹] \"یہ طلاقیں دو مرتبہ ہیں، پھر یا تو اچھائی سے روکنا یا عمدگی کے ساتھ چھوڑ دینا ہے اور تمھارے لیے حلال نہیں کہ تم نے بیویوں کو جو دے دیا ہے اس میں سے کچھ بھی واپس لو۔ ہاں یہ اور بات ہے کہ دونوں (میاں بیوی) کواللہ تعالی کی حدیں قائم نہ رکھ سکنے کا خوف ہو اس لیے اگر تمھیں ڈر ہو کہ یہ دونوں اللہ تعالیٰ کی حدیں قائم نہ رکھ سکیں گے (ازدواجی زندگی اجیرن ہوجائے گی اور شرعی احکام کا پاس نہ پائے گا) تو عورت مرد سے چھٹکارا پانے کے لیے کچھ دے ڈالے۔اس میں دونوں پر گناہ نہیں۔ یہ اللہ تعالیٰ کی حدود (احکام وفرائض) ہیں۔ خبردار ان سے آگے نہ بڑھنا۔ جو لوگ اللہ تعالی کے حدود سے تجاوز کرجائیں وہ ظالم ہیں\"۔\nاس آیت میں کچھ دے دینے کا مطلب یہ ہے کہ شوہر عورت سے اپنا دیا ہوا مہر واپس لے سکتا ہے۔ اس لیے انصاف یہی کہتا ہے کہ اس کا مال اس کو واپس کر دیا جائےاورعورت اپنے ماں باپ کے پاس چلی جائے۔کیونکہ مرد کو دوسری شادی کرنے لیے پھر مہر دینا ہوگا۔\nفقہاےکرام نے اس بات کو ناپسند کیا ہے کہ عورت سے مہر سےزیادہ بھی کچھ مانگا جائے۔ کیونکہ عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں: «إِنَّ امْرَأَةَ ثَابِتِ بْنِ قَيْسٍ أَتَتْ النَّبِيَّ صلی اللہ علیہ وسلم فَقَالَتْ: يَا رَسُولَ اللَّهِ صلی اللہ علیہ وسلم ثَابِتُ بْنُ قَيْسٍ مَا أَعْتِبُ عَلَيْهِ فِي خُلُقٍ وَلا دِينٍ وَلَکِنِّي أَکْرَهُ الْکُفْرَ فِي الإِسْلامِ، فَقَالَ رَسُولُ اللَّهِ صلی اللہ علیہ وسلم : أَتَرُدِّينَ عَلَيْهِ حَدِيقَتَهُ قَالَتْ: نَعَمْ قَالَ رَسُولُ اللَّهِ صلی اللہ علیہ وسلم : اقْبَلْ الْحَدِيقَةَ وَطَلِّقْهَا تَطْلِيقَةً». (صحیح البخاری: ۵۲۷۳) \"ثابت بن قیس کی بیوی نبی اکرم صلی اللہ علیہ وسلم کے پاس آئی اورکہا:اللہ کے رسول!مجھے ثابت کے دین اور اخلاق پر کوئی شکایت نہیں، لیکن مجھے مسلمان ہوتے ہوے بھی کفر کاخوف ہے۔(میں اس کے ساتھ زندگی نہیں گزار سکتی) اس پر آپنے فرمایا: کیا تم اس کا باغ واپس کرسکتی ہو؟اس نے کہا: ہاں کر سکتی ہوں۔تو آپنے فرمایا: اس سے باغ واپس لے لو اور اس کو ایک طلاق دے دو\"۔\nایک دوسری حدیث میں یہ بھی آیا ہے کہ باغ بھی واپس کرسکتی ہوں اور کچھ زیادہ مال بھی دے سکتی ہوں۔ مگر اس حدیث کی سند صحیح نہیں ہے۔\nزیادہ ترعلماءکا خیال ہے کہ خلع طلاق نہیں بلکہ فسخ ہے۔ کیونکہ دونوں میں مندرجہ ذیل فرق ہیں:\n۱- طلاق میں رجوع ہے، خلع میں نہیں۔\n۲- طلاق طہر کی اس حالت میں دی جاتی ہے، جس میں شوہر نے ہم بستری نہ کی ہو۔ خلع میں ایسی کوئی شرط نہیں ہے۔\n۳- تین طلاقیں پوری ہونے کی صورت میں ضروری ہے کہ کسی اور سے نکاح ہو اور پھر جب وہ بھی طلاق دے دےتو پہلے شوہر کے ساتھ دوبارہ شادی ہوسکتی ہے۔ خلع میں ایسا نہیں ہے، عورت جب چاہے پہلے شوہر سے نئے مہر کے ساتھ نکاح کرسکتی ہے۔\nطلاق کی عدت تین ماہ ہے۔ جب کہ خلع کی عدت ایک ماہ ہے۔(کچھ علما کا خیال ہےکہ خلع کی عدت بھی وہی ہے جو طلاق کی ہے)ان اختلافات کی وجہ سے یہی صحیح لگتا ہے کہ خلع طلاق نہیں بلکہ فسخ ہے۔","",{}],[264,"§خلیفہ\nخلیفہ کےمعنی ہیں: نائب، جانشین یا وہ آدمی جو کسی دوسرے کے بعد آئے۔ ابوبکر رضی اللہ عنہ کو اس لیے خلیفہ (جانشین) کہتے ہیں کہ وہنبی اکرم صلی اللہ علیہ وسلم کےبعد مسلمانوں کے رہنما بنے۔ ان کے بعد عمر رضی اللہ عنہ خلیفہ بنے، پھر اسی طرح یہ خلافت کا سلسلہ چلتا رہا۔\nقرآن میں خلیفہ بنا نے کا بیان ہے: ﴿يَٰدَاوُۥدُ إِنَّا جَعَلۡنَٰكَ خَلِيفَةࣰ فِي ٱلۡأَرۡضِ فَٱحۡكُم بَيۡنَ ٱلنَّاسِ بِٱلۡحَقِّ﴾ [ص: ۲۶] \"اے داود، ہم نے تمھیں زمین پر خلیفہ بنایا، تاکہ تم لوگوں کے درمیان حق کے ساتھ فیصلہ کرو\"۔\nداود علیہ السلام کو خلیفہ اس لیے کہا گیاکہ ان کو’شاول‘کے بعدبنی اسرائیل کا بادشاہ بنایا گیاتھا۔ اس سے یہ بات بھی ظاہر ہوتی ہے کہ بادشاہ کو بھی خلیفہ کہا جا سکتا ہے۔ اللہ نے آدم علیہ السلام اور انھی کے ساتھ ان کی اولاد بنی نوع انسان کو بھی ایک کے بعدایک کاخلیفہ بنایا۔اللہ تعالیٰ کا ارشادہے:\n۱- ﴿وَإِذۡ قَالَ رَبُّكَ لِلۡمَلَٰٓئِكَةِ إِنِّي جَاعِلࣱ فِي ٱلۡأَرۡضِ خَلِيفَةࣰۖ قَالُوٓاْ أَتَجۡعَلُ فِيهَا مَن يُفۡسِدُ فِيهَا وَيَسۡفِكُ ٱلدِّمَآءَ وَنَحۡنُ نُسَبِّحُ بِحَمۡدِكَ وَنُقَدِّسُ لَكَۖ قَالَ إِنِّيٓ أَعۡلَمُ مَا لَا تَعۡلَمُونَ﴾ [البقرة: ۳۰] \"جب تمھارے ربنے فرشتوں سے کہا کہ میں زمین پر ایک خلیفہ بنارہا ہوں، تو انھوں نے کہا:کیا تو اس میں ایسے لوگوں کوپیدا کرے گا، جو اس میں بگاڑپیدا کریں گے اور خوں ریزی کریں گے۔ جب کہ ہم تیری تعریف کے ساتھ تیری عظمت بیان کرتے ہیں اس نے کہا: جو میں جانتا ہوں، تم نہیں جانتے\"۔\nحافظ ابن کثیرکہتے ہیں: بنی آدم کی پیدایش سے قبل اللہ تعالیٰ نےملأاعلی میں اس کی تعریف کاتذکرہ فرمایا۔اپنےاس احسان کی خبردیتےہوےاللہ تعالیٰ ارشادفرماتاہےکہ اے محمد! اپنی قوم کویہ واقعہ بتائیےکہ جب آپ کے رب نے فرشتوں سے کہاتھا کہ میں زمین میں خلیفہ بنانےوالاہوں، یعنی ایک ایسی قوم بنانے والاہوں، جو صدی درصدی اورنسل درنسل ایک دوسرے کے پیچھے آئیں گے اورایک دوسرے کی نیابت کریں گے، جیساکہ اللہ تعالیٰ نے ایک دوسری آیت میں فرمایا: ﴿وَهُوَ ٱلَّذِي جَعَلَكُمۡ خَلَٰٓئِفَ ٱلۡأَرۡضِ﴾ [الأنعام: ۱۶۵] \"وہی ہے جس نے تمھیں زمین پر خلیفہ بنایا \"۔خلیفہ کی تفسیرمیں یہی بات صحیح ہے۔ان لوگوں کاقول صحیح نہیں ہے،جوآیت کریمہ : ﴿إِنِّي جَاعِلࣱ فِي ٱلۡأَرۡضِ خَلِيفَةࣰۖ﴾ [البقرة: ۳۰] \"میں زمین پر ایک خلیفہ بنانے جارہا ہوں\"سےاستدلال کرتے ہوےیہ کہتے ہیں کہ آدم زمین میں اللہ کے خلیفہ ہیں۔(تفسیرابن کثیر)\nآدم کوخلیفۃ اللہ اس معنی میں کہناکہ ان کواللہ کی طرف سے خلافت عطاہوئی اوریہ نسبت تشریفی ہے۔حافظ ابن کثیرتفسیرکےمطابق سورہ بقرہ اورسورہ آل عمران کی مذکوربالادونوں آیتوں سے آدم کے خلیفہ بنائے جانے کامطلب یہ ہے کہ سابق اقوام کی جگہ آدم کونیابت عطاکی گئی ہےاوریہ خلافت اللہ کی طرف سے عطاکردہ ہے، اس لیے اس کی طرف نسبت ہے۔ورنہ اصل میں اللہ تعالیٰ انسانوں کا خلیفہ ہے، کیوں کہ خلیفہ گزرجانے والے کا نائب ہوتاہےاوراللہ رب العزت حی وقیوم ہے۔بعض لوگوں نے آدم کی خلافت ارضی سے استدلال کرکے یہ ثابت کرنا چاہے کہ انسان اللہ تعالیٰ کا خلیفہ ہے اور اس پر مرتب ہونے والے احکام کاذکرکیاہے۔ لیکن یہ استدلال صحیح نہیں ہے۔ قدیم زمانے میں ملحدصوفیوں نےآدم کواللہ کے خلیفہ ہونےکے اعتقادکورائج کیا۔ جدیدزمانےمیں اسلامی نظام کے نفاذاوراسلامی حکومت کےقیام،اقامت دین اورخلافت الٰہیہ کے حوالے سےلوگوں نےسیاسی میدان میں آدم کے خلیفۃ اللہ ہونےاورخلافت الٰہیہ کی باتیں زوروشورسے پھیلائیں،جب کہ لفظ خلیفہ کاقرآن مجید میں جو استعمال ہے وہ نیابت کے معنی میں ہے۔شیخ محمدنسیب رفاعی مختصرتفسیرابن کثیرمیں لکھتے ہیں: خلیفہ کا معنی قطعی طورپراس بات کومستلزم ہے کہ آدمی جس کا خلیفہ بن رہا ہے، وہ کلی یاجزئی طورپر غائب ہو۔ وہ مرگیاہو،سفرکرگیاہو،عہدے سے ہٹ گیاہو، ہٹادیاگیاہو،کسی اوروجہ سےسابق اپنے کام کونہ کرسکتاہو۔مثلاجیسےتم کہتے ہو: ابوبکر رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کے خلیفہ ہیں یعنی آپ کی موت کےبعد۔ ایسے ہی تم کہتے ہوکہ رسول اللہ صلی اللہ علیہ وسلم نے علی رضی اللہ عنہ کومدینے پرخلیفہ بنایایعنی کسی غزوے میں آپ کی غیرموجودگی میں ان کو یہ نیابت ملی۔اس بات کے واضح ہوجانےاوراس معنی پرمطمئن ہوجانےکے بعداس آدمی کی غلطی کاادراک کرو، جس کواس بات پراطمینان ہے کہ آدم علیہ السلام کواللہ تعالیٰ نے زمین پر اپنا خلیفہ بنایا۔ اس کے دلائل درج ذیل ہیں:\n۱- اللہ تعالیٰ کے حق میں یہ محال ہے کہ وہ اپنی حکمرانی سے کلی یاجزئی طورپرغائب ہو۔وہ آسمانوں اور زمین کا قیوم ہےاوراس کے علم سے زمین وآسمان کاذرہ بھی نہیں اوجھل ہوتا، اس لیے اللہ رب العزت کسی خلیفہ،وکیل، نائب اور کسی کے کام کامحتاج نہیں ہے۔اللہ رب العزت سارےجہان سے بے نیاز ہے۔\n۲- آدم یاکوئی انسان اللہ تعالیٰ کی خلافت کے لیےمناسب ہو تو اس کے لیے یہ لازم ہے کہ اس کی کچھ ایسی صفات اورخوبیاں بھی ہوں جواللہ تعالیٰ کی صفات اورخوبیوں کےمماثل اورمشابہ ہواورساری مخلوقات کی طرح جب انسان اللہ تعالیٰ کی کسی بھی صفت میں اس کے مشابہ نہیں ہے،بل کہ اپنی ساری صفات میں وہ ناقص ہے اور اللہ تعالیٰ اپنی ساری صفات میں کامل ہے۔تویہاں سے کلی طورپرخالق اور مخلوق کے درمیان فرق ظاہرہوگیا۔اس لیےکامل کی خلافت ناقص کے لیے کیسے جائزہوسکتی ہے۔اللہ تعالیٰ ہرمثیل ونظیرسے بلندوبرترہے۔اس کا فرمان ہے: ﴿لَيۡسَ كَمِثۡلِهِۦ شَيۡءࣱۖ وَهُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ﴾ [الشوری: ۱۱] \"اس {اللہ}جیسی کوئی چیز نہیں اور وہ سمیع وبصیر (سب کچھ سننے اور دیکھنے والا)ہے\"۔\n۳- یہ بات ثابت ہوگئی کہ کتاب وسنت میں کوئی واضح،مخفی یااستنباطی دلیل اس بات پر نہیں ہے کہ انسان زمین میں اللہ کا خلیفہ ہے،اس لیے کہ اس کا ارشادہے: ﴿إِنِّي جَاعِلࣱ فِي ٱلۡأَرۡضِ خَلِيفَةࣰۖ﴾ [البقرة: ۳۰] \"میں زمین پر ایک خلیفہ بنارہا ہوں\"۔اس قول سے یہ نہیں سمجھاجاسکتاکہ آدم علیہ السلام زمین میں اللہ کاخلیفہ ہیں۔ہاں، اللہ تعالیٰ نے یہ بات کہی ہے، لیکن یہ نہیں کہا ہے کہ اپنے لیےیااپناخلیفہ بنانےوالا ہوں، توکہاں سے ہم نے یہ نتیجہ نکال لیاکہ آدم علیہ السلام یا نوع انسانی زمین میں خلیفہ ہے؟اللہ رب العزت کی شان اس سے بہت بڑی ہے۔یہ بھی یادرہے کہ اکثرمفسرین کا قول ہے کہ خلافت کا مطلب یہ ہےکہ ایک قوم دوسرے کی صدی درصدی اورنسل درنسل نیابت اورخلافت کرے گی۔ (مختصرتفسیر ابن کثیر)\nآدم اور ان کی اولاد سے قبل زمین پر کون لوگ تھے جن کی جگہ پر انسانوں کو ان کا خلیفہ بنایا گیا؟ اس بارے میں ایک روایت یہ ہے کہ وہ جن رہے ہوں گے، جن کی شرارتوں کو دیکھ کر فرشتوں نے کہا تھا کہ یہ فساد پھیلائیں گے۔ یہ بھی ہوسکتا ہے کہ اللہ نے یہ بتادیا ہو کہ میں زمین پر ایسے لوگوں کو خلیفہ بنا رہا ہوں جن کو سوچنے سمجھنے اور پھر ان کو حسن سلوک کرنے اور عمل کے تئیں پابند ہونے کی پوری آزادی ہوگی۔اس سے فرشتوں نے یہ معنیٰ نکالا ہوگا کہ پھر تو بڑا فساد پھیلے گا۔\nاسی طرح نوح علیہ السلام کے طوفان کے بعد ہود کی قوم کو خلیفہ بنایا:﴿وَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ قَوۡمِ نُوحࣲ وَزَادَكُمۡ فِي ٱلۡخَلۡقِ بَصۜۡطَةࣰۖ﴾ [الأعراف: ۶۹] \"یاد کرو جب اللہ نے نوح کی قوم کی جگہ پرتمھیں (قوم ہود کو)خلیفہ بنایا اور جسمانی طور سے بھی تمھیں مضبوطی عطا کی\"۔\nاسی طرح عاد نامی قوم کے بعد اس کی جگہ پرثمود کی قوم کو خلیفہ بنایا:﴿وَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ عَادࣲ وَبَوَّأَكُمۡ فِي ٱلۡأَرۡضِ﴾ [الأعراف: ۷۴] \"وہ وقت یاد کرو جب اللہ نے عاد کے بعد تمھیں (ثمود کی قوم کو) خلیفہ بنایا اور تمھیں زمین پر ٹھکانا دیا\"۔\nان آیتوں میں خلیفہ کے معنیٰ کسی ایک قوم کی جگہ پر دوسری قوم کوزمین پر آباد کرنا ہے۔ جیسا کہ یہی معنیٰ ایک دوسری جگہ پر بھی آیا ہے:﴿ثُمَّ جَعَلۡنَٰكُمۡ خَلَٰٓئِفَ فِي ٱلۡأَرۡضِ مِنۢ بَعۡدِهِمۡ لِنَنظُرَ كَيۡفَ تَعۡمَلُونَ﴾ [یونس: ۱۴] \"پھر ان کے بعد ہم نے زمین پر تم کو ان کی جگہ پر بسایا، تاکہ ہم دیکھیں تم کیا کیا عمل کرتے ہو\"۔\nاسی لیے حاکم (بادشاہ) کو خلیفہ کہتے ہیں کہ وہ اپنے سے پہلے والے بادشاہ کی جگہ پر منتخب کیا جاتا ہے۔ اور یہی معنیٰ سلف(پہلے کے اسلامی علماء) کے یہاں زیادہ مشہور اور رائج ہے۔ ابن جریر طبری نے ایک دوسرامعنیٰ بھی بتایا ہے کہ، یہاں خلیفہ کا استعمال اللہ کےاحکام کو زمین پررہنے والے انسانوں پر نافذ کرنے والےنمایندوں کے لیے کیا گیا ہے۔ اللہ کی طرف سے اس کے پیغامات کو عام کرنے کے لیے آدم علیہ السلام اور پھر نبی اکرم صلی اللہ علیہ وسلم کی امت کو اللہ کا خلیفہ بنایاگیا، مگر زیادہ صحیح پہلا معنیٰ ہی ہے، کیونکہ اگر دوسرا معنیٰ صحیح ہوتا تو فرشتوں کو بحث کرنے کی کیا ضرورت تھی؟","",{}],[265,"§خمر\nخمر کا مطلب:شراب ہے۔ شراب نوشی، شراب بنانا اور بیچنا اسلام میں سب حرام ہے:﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّمَا ٱلۡخَمۡرُ وَٱلۡمَيۡسِرُ وَٱلۡأَنصَابُ وَٱلۡأَزۡلَٰمُ رِجۡسࣱ مِّنۡ عَمَلِ ٱلشَّيۡطَٰنِ فَٱجۡتَنِبُوهُ لَعَلَّكُمۡ تُفۡلِحُونَ إِنَّمَا يُرِيدُ ٱلشَّيۡطَٰنُ أَن يُوقِعَ بَيۡنَكُمُ ٱلۡعَدَٰوَةَ وَٱلۡبَغۡضَآءَ فِي ٱلۡخَمۡرِ وَٱلۡمَيۡسِرِ وَيَصُدَّكُمۡ عَن ذِكۡرِ ٱللَّهِ وَعَنِ ٱلصَّلَوٰةِۖ فَهَلۡ أَنتُم مُّنتَهُونَ﴾ [المائدة: ۹۰-۹۱] \"اے ایمان والو! شراب، جوا، تھان (کعبہ کے ارد گرد کھڑے کیے گئے پتھر جہاں غیر اللہ کے نام پر جانورذبح کیے جاتے تھے) اور فال نکالنے کے پانسے کے تیر یہ سب گندی باتیں شیطانی کام ہیں۔ اس لیے تم ان سے دور رہو تاکہ کامیابی پاسکو۔ شیطان تو یہی چاہتا ہے کہ شراب اور جوئے کے ذریعے تمھارے درمیان دشمنی اور بغض پیدا کردے اور تمھیں اللہ کی یاد سے اور نماز سے روک دے۔ تو کیا تم (ان چیزوں سے) رک نہیں جاؤگے\"۔\nجب یہ آیتیں نازل ہوئیں تو عمر رضی اللہ عنہ نے کہا:اےہمارے رب!ہم رک گئے، ہم رک گئے۔پھر لوگوں نے مٹکوں میں بھری ہوئی شراب کو اس طرح انڈیل دیا کہ مدینے کی گلیوں میں شراب کی ندیاں بہنے لگیں۔ اس لیے اب مسلم علما کا اس بات پر اتفاق ہے کہ شراب بنانا، شراب فروخت کرنااور شراب پینا سب حرام ہیں۔\nاسی طرح فقہا کا اس بات پر بھی اتفاق ہے کہ شراب پینے والے کو چالیس کوڑے لگائے جائیں گے۔ لیکن وہ پھر بھی نہیں رکتا تو اسی کوڑے بھی لگائے جاسکتے ہیں جیسا کہ علی رضی اللہ عنہ کہتے ہیں: «جَلَدَ النَّبِيُّ صلی اللہ علیہ وسلم أَرْبَعِينَ وَجَلَدَ أَبُو بَکْرٍ أَرْبَعِينَ وَعُمَرُ ثَمَانِينَ وَکُلٌّ سُنَّةٌ، وَهَذَا أَحَبُّ إِلَيَّ». (صحیح مسلم: ۳۸/۱۷۰۷) \"نبی اکرم صلی اللہ علیہ وسلم نے شرابی کو چالیس کوڑے لگائے۔ابوبکرنے چالیس کوڑے لگائے اور عمر رضی اللہ عنہ نے اسی کوڑے لگائے۔ یہ سب سنت ہے۔ مگر یہ(چالیس کوڑے) مجھے زیادہ پسند ہیں \"۔\nیہ سزا عدالت ہی دے سکتی ہے۔ سزا دینے کے لیے ضروری ہے کہ یاتو شراب نوشی کرنے والا خود اپنے جرم کو قبول کرے،یا پھر دو گواہ لائے جائیں اور دونوں گواہی دیں کہ ہم نے اسے شراب پیتے دیکھا ہے۔ اگر ایسا نہیں ہو سکتاتو شک کا فائدہ ہمیشہ ملزم کو پہنچتا ہے۔\nقرآن نے شراب کو ہمیشہ کےلیے ممنوع قرار دیا ہے۔اسلام پانچ چیزوں کے تحفظ کاحکم دیتا ہے۔ وہ یہ ہیں:دین ومذہب کی حفاظت، جان کی حفاظت،مال کی حفاظت، عزت و آبرواورعصمت وعفت کی حفاظت اور عقل کی حفاظت۔ان کے خلاف چلنے والوں کےلیے سخت سزا مقرر کی گئی ہے۔اب عقل کی حفاظت کےلیے ضروری تھا کہ شراب اور ہر نشہ آور چیزکو ہمیشہ کےلیے ممنوع کردیا جائے۔لیکن جس ملک میں قرآن نازل ہورہاتھا وہاں جگہ جگہ شراب خانے کھلے ہوے تھے۔جہاں لوگ کھلے عام شراب پیا کرتے تھے۔ ایسی حالت میں شراب کو منع کردینا بہت مشکل تھا۔اس لیے اللہ نے پہلے یہ آیت اتاری: ﴿يَسۡـَٔلُونَكَ عَنِ ٱلۡخَمۡرِ وَٱلۡمَيۡسِرِۖ قُلۡ فِيهِمَآ إِثۡمࣱ كَبِيرࣱ وَمَنَٰفِعُ لِلنَّاسِ وَإِثۡمُهُمَآ أَكۡبَرُ مِن نَّفۡعِهِمَاۗ﴾ [البقرة: ۲۱۹] \"وہ تم سے شراب اور جوئے کے بارے میں پوچھتےہیں۔کہہ دو ان دونوں میں بڑا گنا ہ ہے اور لوگوں کےلیے تھوڑے بہت فائدے بھی ہیں لیکن ان کا گناہ ان کے فائدے سے کہیں زیادہ ہے\"۔\nشراب کے بارے میں یہ پہلا حکم ہے۔اس میں صرف یہ اشارہ کیا گیا ہے کہ اس کا نقصان اس کے فائدے سے کہیں زیادہ ہے۔کچھ سمجھ دار لوگ سوچنے لگے تھےکہ شاید اب شراب کو حرام کیا جانے والا ہے۔اس کے بعد یہ آیت نازل ہوئی:﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَقۡرَبُواْ ٱلصَّلَوٰةَ وَأَنتُمۡ سُكَٰرَىٰ حَتَّىٰ تَعۡلَمُواْ مَا تَقُولُونَ﴾ [النساء: ۴۳] \"اے ایمان والو!جب تم نشے میں ہوتو نماز کے نزدیک مت جاؤ،جب تک تم یہ نہ جان لو کہ تم کیا کہہ رہے ہو\"۔\nیعنی شراب پینے والوں کو نماز پڑھنے سے روک دیا گیا اور اس کے بعد یہ آیت نازل ہوئی:﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّمَا ٱلۡخَمۡرُ وَٱلۡمَيۡسِرُ وَٱلۡأَنصَابُ وَٱلۡأَزۡلَٰمُ رِجۡسࣱ مِّنۡ عَمَلِ ٱلشَّيۡطَٰنِ فَٱجۡتَنِبُوهُ لَعَلَّكُمۡ تُفۡلِحُونَ إِنَّمَا يُرِيدُ ٱلشَّيۡطَٰنُ أَن يُوقِعَ بَيۡنَكُمُ ٱلۡعَدَٰوَةَ وَٱلۡبَغۡضَآءَ فِي ٱلۡخَمۡرِ وَٱلۡمَيۡسِرِ وَيَصُدَّكُمۡ عَن ذِكۡرِ ٱللَّهِ وَعَنِ ٱلصَّلَوٰةِۖ فَهَلۡ أَنتُم مُّنتَهُونَ وَأَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَ وَٱحۡذَرُواْۚ فَإِن تَوَلَّيۡتُمۡ فَٱعۡلَمُوٓاْ أَنَّمَا عَلَىٰ رَسُولِنَا ٱلۡبَلَٰغُ ٱلۡمُبِينُ﴾ [المائدة: ۹۰-۹۲] \"اے ایمان والو! یہ شراب اور جوا اور تھان اور پانسے کے تیر توگندے شیطانی کام ہیں۔اس لیے تم ان سے الگ رہو۔تاکہ تم کامیاب ہوسکو۔شیطان تو یہچاہتاہےکہ شراب اور جوئے کے ذریعےسےتمھارے درمیان دشمنی اور بغض پیدا کردے اور تمھیں اللہ کی یاد سے اور نماز سے روک دے۔پھر کیا تم (ان چیزوں سے) نہیں رکوگے؟اور اللہ اور اس کے رسول کی بات مانو اور ان باتوں سے بچولیکن اگر نافرمانی کی تو جان لو کہ ہمارے رسول پر صرف صاف صاف بات پہنچادینے کی ذمہ داری ہے\"۔\nاس آیت کے نازل ہوتے ہی شرا ب مدینے کی گلیوں میں پانی کی طرح بہا دی گئی۔لوگوں نے اسے ہمیشہ کےلیے چھوڑدیا۔یہ قرآن اورنبی اکرم صلی اللہ علیہ وسلم کا ایک حیرت انگیزمعجزہ ہے،جس نے ایسی قوم کو جس کی گھٹی میں شرا ب داخل ہوگئی تھی، ایک لحظہ میں اس سے آزادی دلادی۔\nآج شراب اور جوا خود ساختہ مہذب قوموں کی دو بڑی برائیاں ہیں،جن سے ان کے سمجھ دار لوگ چھٹکارہ چاہتے ہیں۔لیکن اسلام کے سوا کسی اورمذہب میں ان کا کوئی علاج نہیں ہے۔کچھ ممالک تو اس کو ممنوع قرار دینے کےلیے کئی طرح کی تجاویز پر غور کرتے ہیں،لیکن ان کی ان تجاویز سے ابھی تک کوئی خاطر خواہ کامیابی نہیں ملی ہے۔","",{}],[266,"§خنزير\nاردو میں خنزیرکوسور کہتے ہیں۔سور کا گوشت کھانا، اس کو پالنا اور اس کا کاروبار کرنا یہ سب کچھ حرام ہیں۔ کیوں کہ یہ جانور نجس ہے۔ ارشاد باری تعالیٰ ہے:\n۱- ﴿إِنَّمَا حَرَّمَ عَلَيۡكُمُ ٱلۡمَيۡتَةَ وَٱلدَّمَ وَلَحۡمَ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ بِهِۦ لِغَيۡرِ ٱللَّهِۖ فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغࣲ وَلَا عَادࣲ فَلَآ إِثۡمَ عَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِيمٌ﴾ [البقرة: ۱۷۳] \"اس نے تم پر مرے ہوئے جانور، خون، سور کا گوشت اور جس چیز پر اللہ تعالی کے سوا کسی اور کا نام لیا جائے حرام کردیا ہے، ہاں جو مجبور ہوجائے بشرطے کہ اللہ تعالی کی نافرمانی نہ کرے اور حد (ضرورت) سے باہر نہ نکل جائے اس پر کچھ گناہ نہیں۔ بےشک اللہ تعالی غفور ورحیم( بخشنے والا اوررحم کرنے والا)ہے\"۔\n۲- ﴿حُرِّمَتۡ عَلَيۡكُمُ ٱلۡمَيۡتَةُ وَٱلدَّمُ وَلَحۡمُ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦ وَٱلۡمُنۡخَنِقَةُ وَٱلۡمَوۡقُوذَةُ وَٱلۡمُتَرَدِّيَةُ وَٱلنَّطِيحَةُ وَمَآ أَكَلَ ٱلسَّبُعُ إِلَّا مَا ذَكَّيۡتُمۡ وَمَا ذُبِحَ عَلَى ٱلنُّصُبِ وَأَن تَسۡتَقۡسِمُواْ بِٱلۡأَزۡلَٰمِۚ ذَٰلِكُمۡ فِسۡقٌۗ ٱلۡيَوۡمَ يَئِسَ ٱلَّذِينَ كَفَرُواْ مِن دِينِكُمۡ فَلَا تَخۡشَوۡهُمۡ وَٱخۡشَوۡنِۚ ٱلۡيَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِينَكُمۡ وَأَتۡمَمۡتُ عَلَيۡكُمۡ نِعۡمَتِي وَرَضِيتُ لَكُمُ ٱلۡإِسۡلَٰمَ دِينࣰ اۚ فَمَنِ ٱضۡطُرَّ فِي مَخۡمَصَةٍ غَيۡرَ مُتَجَانِفࣲ لِّإِثۡمࣲ فَإِنَّ ٱللَّهَ غَفُورࣱ رَّحِيمࣱ‏﴾ [المائدة: ۳] \"تم پر مرا ہوا جانور اور (بہتا) خون اور سور کا گوشت اور جس چیز پر اللہ تعالی کے سوا کسی اور کا نام پکارا جائے اور جو جانور گلا گھٹ کر مر جائے اور جو چوٹ لگ کر مر جائے اور جو گر کر مر جائے اور جو سینگ لگ کر مر جائے یہ سب حرام ہیں اور وہ جانور بھی جس کو درندے پھاڑ کھائیں۔ مگر جس کو تم (مرنے سے پہلے) ذبح کرلو اور وہ جانور بھی جو استھانوں پر ذبح کیا جائے اور یہ بھی کہ پانسوں سے قسمت معلوم کرو یہ سب گناہ (کے کام) ہیں۔ آج کافر تمھارے دین سے ناامید ہو گئے ہیں، لیکن ان سے مت ڈرو اور مجھ ہی سے ڈرتے رہو (اور) آج ہم نے تمھارے لیے تمھارا دین کامل کر دیا اوراپنی نعمتیں تم پر پوری کر دیں اور تمھارے لیے اسلام کو دین پسند کیا، ہاں جو شخص بھوک سے مجبور ہو جائے (بشرطیکہ) گناہ کی طرف مائل نہ ہو تو اللہ تعالی غفورورحیم( بخشنے والا مہربان) ہے\"۔\n۳- ﴿إِنَّمَا حَرَّمَ عَلَيۡكُمُ ٱلۡمَيۡتَةَ وَٱلدَّمَ وَلَحۡمَ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦۖ فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغࣲ وَلَا عَادࣲ فَإِنَّ ٱللَّهَ غَفُورࣱ رَّحِيمࣱ‏﴾ [النحل: ۱۱۵] \"اس نے تم پر مُردار اور خون اور سور کا گوشت حرام کردیا ہے اور جس چیز پر اللہ تعالی کے سوا کسی اور کا نام لیا گیا ہو۔ ہاں اگر کوئی شخص مجبور اور بے بس کردیا جائے، نہ وہ خواہش مند ہواور نہ حد سے گزرنے والا تو اللہ تعالی غفورورحیم( بخشنے والا مہربان) ہے\"۔\nتورات میں بھی سور کے گوشت کھانے کی حرمت آئی ہے۔ اس کی تعلیم عیسیٰ علیہ السلام بھی دیتے تھے۔لیکن جب سینٹ پال نے نصرانیت قبول کی تو اس نے سور کا گوشت حلال کردیا۔ جب عیسیٰ علیہ السلام زمین پر واپس آئیں گے تو دوبارہ سور کا گوشت حرام کریں گے۔ اپنے ہاتھوں سے اسے قتل کریں گے۔ ابوہریرہ رضی اللہ عنہ سےمروی حدیث میں رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «وَالَّذِي نَفْسِي بِيَدِهِ لَيُوشِکَنَّ أَنْ يَنْزِلَ فِيکُمْ ابْنُ مَرْيَمَ وَيَقْتُلَ الْخِنْزِيرَ». (صحیح البخاری: ۲۲۲۲، وصحیح مسلم: ۱۵۵/۲۴۲۶)۔\" اس ذات کی قسم جس کے ہاتھ میں میری جان ہے، وہ زمانہ آنے والا ہے جب ابن مریم عیسیٰ علیہ السلامزمین پر نازل ہوں گے اورسور مار ڈالیں گے\"۔\nتورات کی کتاب ’احبار‘ میں جائز اور ناجائز چوپایوں اور جانوروں کا ذکر صریحی طور پر آیا ہے: \"سور جو چرے ہوئے کھر کا ہوتا ہے لیکن جگالی نہیں کرتا (چباتا نہیں ہے) اس لیے وہ تمھارے لیے جائز نہیں ہے۔ اس کے گوشت میں سے کچھ نہ کھانا اور اس کے چمڑے کو بھی نہ چھونا۔ یہ تمھارے لیے ناپاک ہے\"۔ [احبار: ۱۱: ۷، ۸]","",{}],[267,"§خواہش\nدیکھیے: اشتہا","",{}],[268,"§خوشی اور غم\nاللہ تعالی نے انسانی فطرت میں خوشی اور غم کو ودیعت کردیا ہے , تاکہ خوشی کے موقع پر انسان اپنے رب کا شکر ادا کرے اور مصیبت وپریشانی کے عالم میں صبر کا دامن نہ چھوڑے۔ اور ان دونوں حالتوں میں وہ اللہ کے نیک اور صالح بندوں میں شمار ہوگا۔\nاللہ تعالی کا ارشاد ہے: ﴿وَأَنَّهُۥ هُوَ أَضۡحَكَ وَأَبۡكَىٰ﴾ [النجم: ۴۳]\nترجمہ: اور یہ کہ وہی ہنساتا اور وہی رلاتا ہے۔\nگویا خوشی اور غم دونوں اللہ ہی کی طرف سے ہوتے ہیں۔ اسی لئے شریعت نے خوشی اور غم دونوں حالتوں میں ہماری رہنمائی فرمائی ہے۔\nخوشی میں اللہ کا شکر ادا کرنا چاہئے۔ شکر ادا کرنے کے مختلف طریقے ہیں۔ مثال کے طور پر زبان سے اللہ کی حمد وثناء کرنا اور اس کا شکر بجالانا تاکہ اللہ تعالی مزید نعمتیں عطا کرے۔ فرمان باری تعالی ہے: ﴿لَئِن شَكَرۡتُمۡ لَأَزِيدَنَّكُمۡ﴾ [إبراهيم: ۷]\nترجمہ: اگر تم شکر کروگے تو تمہیں اور زیادہ دوں گا۔\nاسی طرح خوشی کے موقع پر غریبوں, بیواؤں, اور یتیموں کے ساتھ حسن سلوک کرنا بھی \"شکر\" کے مفہوم میں داخل ہے۔ یہ شکر ادا کرنے کا دوسرا طریقہ ہے جس کا تعلق عمل سے ہے۔ اس اعتبار سے شکر ادا کرنے کے پہلے طریقے کو \"لفظی شکر\" جبکہ دوسرے کو \"عملی شکر\" کہا جاتا ہے۔ اور ان دونوں حالتوں میں ایک مؤمن کو فرحت اور شادمانی حاصل ہوتی ہے۔\nکچھ لوگ خوشیوں میں اللہ تعالی کے بنائے ہوئے اصولوں سے انحراف کرلیتے ہیں, حلال وحرام کی تمییز نہیں کرتے اور شریعت کے حدود سے تجاوز کرجاتے ہیں, یہ شکر کے منافی ہے جس سے لوگوں کو بچنا چاہئے۔\nشریعت نے خوشیوں کے موقع پر جہاں شکر بجالانے کا حکم دیا ہے وہی غم اور پریشانی کے عالم میں صبر کرنے کی تلقین بھی کی ہے۔ لہٰذا مصیبت وپریشانی میں صبر کرنا چاہئے اور اللہ تعالی سے غم کے ازالہ کے لئے دعائیں کرنی چاہئے۔\nبسا اوقات مصیبت اور پریشانی بطور آزمائش ہوتی ہے , اس کے آنے پر تقدیر کو کوسنا یا اللہ تعالی کی ذات کو برا بھلا کہنا کفر اور نفاق کی علامت ہے۔ مومن آزمائش کے بعد نکھرتا ہے جبکہ کافر اور منافق غم کے عالم میں ڈپریشن کا شکار ہوکر خودکشی کرنے پر آمادہ ہوتا ہے۔\nخوشی ہو یا غم؟ بندہ مومن کے لئے دونوں خیر کا باعث ہے۔ خوشی کے موقع پر وہ رب کا شکر بجالاتا ہے تو پروردگار اسے مزید نعمتیں عنایت فرماتا ہے جبکہ غم وتکلیف پر وہ صبر کرتا ہے جو اس کے حق میں خیر وبھلائی ہے۔\nنبی صلی اللہ علیہ وسلم نے فرمایا : «عَجَبًا لِأَمْرِ الْمُؤْمِنِ، إِنَّ أَمْرَهُ کُلَّهُ خَيْرٌ، وَلَيْسَ ذَاکَ لِأَحَدٍ إِلَّا لِلْمُؤْمِنِ، إِنْ أَصَابَتْهُ سَرَّاءُ شَکَرَ، فَکَانَ خَيْرًا لَهُ، وَإِنْ أَصَابَتْهُ ضَرَّاءُ، صَبَرَ فَکَانَ خَيْرًا لَهُ » صحیح مسلم (۲۹۹۹)\nترجمہ: مومن کا معاملہ بڑا عجیب ہے! ہر حال میں اس کے لئے خیر اور بھلائی ہے, اور یہ محض صرف بندہ مومن کے لئے ہے۔ جب اسے کوئی خوشی نصیب ہوتی ہے تو وہ اس پر (رب کا) شکر ادا کرتا ہے جو اس کے لئے خیر ہی خیر ہے اور جب اسے کوئی مصیبت لاحق ہوتی ہے تو وہ اس پر صبر کرتا ہے جو اس کے حق میں خیرہے۔","",{}],[269,"§خون کا بدلہ خون\nدیکھیے: قصاص","",{}],[270,"§خون\nدیکھیے: دم","",{}],[271,"§خيانت\nدیکھیے: خائن","",{}],[272,"§خيل\nقرآن میں گھوڑے کے لیے دو الفاظ استعمال کیے گئے ہیں۔ پہلا لفظ جیادسلیمان علیہ السلام کے قصےمیں آیاہے: ﴿إِذۡ عُرِضَ عَلَيۡهِ بِٱلۡعَشِيِّ ٱلصَّٰفِنَٰتُ ٱلۡجِيَادُ فَقَالَ إِنِّيٓ أَحۡبَبۡتُ حُبَّ ٱلۡخَيۡرِ عَن ذِكۡرِ رَبِّي حَتَّىٰ تَوَارَتۡ بِٱلۡحِجَابِ رُدُّوهَا عَلَيَّۖ فَطَفِقَ مَسۡحَۢا بِٱلسُّوقِ وَٱلۡأَعۡنَاقِ﴾ [ص: ۳۱-۳۳] \"یاد کرو جب شام کے وقت ان(سلیمان)کے سامنے سکھائے ہوے تیز رفتار گھوڑے لائے گئے تو انھوں نے کہا:میں اپنے رب کی یاد کو چھوڑ کرمال کی محبت میں لگ گیا۔یہاں تک کہ سورج ڈوب گیا\"۔اس کے بعد سلیمان علیہ السلام نے کیاکیا اس کےلیے دیکھیے: لفظ ’سلیمان‘۔\nدوسرا لفظ خیل ہے۔اس کے معنیٰ بھی گھوڑے کے ہیں۔یہ لفظ قرآن میں ایک سے زیادہ جگہوں پر مختلف مقاصد کےلیے استعمال ہوا ہے۔کبھی تو یہ کہا گیا: ﴿زُيِّنَ لِلنَّاسِ حُبُّ ٱلشَّهَوَٰتِ مِنَ ٱلنِّسَآءِ وَٱلۡبَنِينَ وَٱلۡقَنَٰطِيرِ ٱلۡمُقَنطَرَةِ مِنَ ٱلذَّهَبِ وَٱلۡفِضَّةِ وَٱلۡخَيۡلِ ٱلۡمُسَوَّمَةِ وَٱلۡأَنۡعَٰمِ وَٱلۡحَرۡثِۗ ذَٰلِكَ مَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَٱللَّهُ عِندَهُۥ حُسۡنُ ٱلۡمَـَٔابِ﴾ [آل عمران: ۱۴] \"لوگوں کے لیے پسندیدہ چیزوں: عورتوں، بیٹوں، سونےچاندی کے ڈھیر اور نشان لگے ہوے گھوڑوں، چوپایوں اور کھیتی سے مزین کیا گیا ہے۔ یہ سب دنیوی زندگی کی چیزیں ہیں اور اللہ کے پاس ہی اچھا ٹھکانا ہے\"۔\nکہیں ارشادہے: ﴿وَأَعِدُّواْ لَهُم مَّا ٱسۡتَطَعۡتُم مِّن قُوَّةࣲ وَمِن رِّبَاطِ ٱلۡخَيۡلِ تُرۡهِبُونَ بِهِۦ عَدُوَّ ٱللَّهِ وَعَدُوَّكُمۡ﴾ [الأنفال: ۶۰] \"تم ان (دشمنوں) کے مقابلے کے لیے بھر پور قوت اکھٹا کرو اور گھوڑے تیار رکھو اس سے تم اللہ کے اور اپنے دشمنوں کو خوف زدہ رکھ سکو اور ان کے سوا اوروں کو بھی\"۔\nاس کی وجہ یہ ہے کہ قدیم زمانے میں گھوڑوں پر بیٹھ کر ہی جنگجو جنگ کیا کرتے تھے۔\nایک جگہ یہ کہا گیاہے:﴿وَٱلۡخَيۡلَ وَٱلۡبِغَالَ وَٱلۡحَمِيرَ لِتَرۡكَبُوهَا وَزِينَةࣰۚ وَيَخۡلُقُ مَا لَا تَعۡلَمُونَ﴾ [النحل: ۸] \"اللہ تعالی نے گھوڑوں کو، خچروں کو اور گدھوں کو تمہاری سواری کے لیے پیدا کیا جوباعث زینت بھی ہیں۔ اور بھی ایسی بہت سی چیزیں پیدا کرتا ہے جن کا تمھیں علم نہیں \"۔\nقرآن میں گھوڑوں کی تعریف کرتے ہوے بتایا گیا ہے:﴿وَٱلۡعَٰدِيَٰتِ ضَبۡحࣰ ا فَٱلۡمُورِيَٰتِ قَدۡحࣰ ا فَٱلۡمُغِيرَٰتِ صُبۡحࣰ ا فَأَثَرۡنَ بِهِۦ نَقۡعࣰ ا فَوَسَطۡنَ بِهِۦ جَمۡعًا إِنَّ ٱلۡإِنسَٰنَ لِرَبِّهِۦ لَكَنُودࣱ‏﴾ [العادیات: ۱-۶] \"ہانپتے ہوے دوڑنے والے گھوڑوں کی قسم، پھر ٹاپ مار کرآگ نکالنے والوں کی قسم، پھر صبح کو حملہ کرنے والوں کی قسم، جو اس وقت گرد وغبار اڑاتے ہیں، پھر اسی کے ساتھ لشکر میں جا گھستےہیں۔بلا شبہ انسان اپنے رب کا بڑا ناشکراہے\"۔\nان آیتوں میں گھوڑے کی قسم کھا کر انسان کا ناشکراہونا بیان کیا گیاہے۔ گھوڑے اپنے مالک کے کتنےفرماں بردار ہیں کہ اس کے ایک اشارے پر دشمن پر حملہ کردیتے ہیں اور اپنی جان کی پروا نہیں کرتے۔ لیکن انسان کتنا ناشکراہے کہ اپنے ’رب‘کی ایک نہیں سنتا جب کہ اس کے لیے اللہ نے پوری دنیا بنائی اور اسے اس کے ماتحت کردیا۔ اللہ تعالیٰ ایسے انسان کو جو اپنے رب کی یاد سے غافل ہوگئے ہیں، خبردار کرتے ہوے قرآن کریم میں کہتا ہے:﴿إِنَّ ٱلۡإِنسَٰنَ لِرَبِّهِۦ لَكَنُودࣱ وَإِنَّهُۥ عَلَىٰ ذَٰلِكَ لَشَهِيدࣱ وَإِنَّهُۥ لِحُبِّ ٱلۡخَيۡرِ لَشَدِيدٌ أَفَلَا يَعۡلَمُ إِذَا بُعۡثِرَ مَا فِي ٱلۡقُبُورِ وَحُصِّلَ مَا فِي ٱلصُّدُورِ إِنَّ رَبَّهُم بِهِمۡ يَوۡمَئِذࣲ لَّخَبِيرُۢ﴾ [العادیات: ۶-۱۱] \"بےشک انسان اپنے رب کا بڑا ناشکرا ہے اور وہ خود اس بات کےلیے گواہ ہے۔ اور وہ مال کے حرص میں بڑا ہی پکا ہے۔تو کیا وہ جانتا نہیں، جب اگلوا دیا جائے گاجو کچھ قبروں میں ہےاور کھول کر رکھ دیا جائے گا جو کچھ سینوں (دلوں ) میں ہے۔بےشک ان کا رب اس دن ان سے پوری طرح باخبر ہوگا\"۔","",{}],[273,"§دابۃ الارض\nدابہ کا ترجمہ بالعموم جاندار اور جانور سے کیا جاتا ہے۔ لیکن قرآن کی سورہ سبا میں دابہ کا استعمال گھن کے کیڑے (دیمک) کے معنی میں ہوا ہے:﴿فَلَمَّا قَضَيۡنَا عَلَيۡهِ ٱلۡمَوۡتَ مَا دَلَّهُمۡ عَلَىٰ مَوۡتِهِۦٓ إِلَّا دَآبَّةُ ٱلۡأَرۡضِ تَأۡكُلُ مِنسَأَتَهُۥۖ فَلَمَّا خَرَّ تَبَيَّنَتِ ٱلۡجِنُّ أَن لَّوۡ كَانُواْ يَعۡلَمُونَ ٱلۡغَيۡبَ مَا لَبِثُواْ فِي ٱلۡعَذَابِ ٱلۡمُهِينِ﴾ [سبأ: ۱۴] \"پھر جب ہم نے ان (سلیمان) پر موت کا فیصلہ کر دیا تو ان کی موت کی خبر جنات کو گھن کے کیڑے نے دی جو ان کی بیساکھی کو کھا رہا تھا۔جب سلیمان علیہ السلام گرپڑےتو جنات کو ان کی موت کا علم ہوا۔ اگر وہ (جن) غیب کا علم رکھتے تو اس ذلت کا عذاب نہ جھیلتے\"۔(مزیدمعلومات کے لیے سلیما ن علیہ السلام کی کہانی دیکھیے )","",{}],[274,"§دابّہ\nدابہ (مخلوق یا جاندار) کا ذکر قرآن مجید میں باربار آیا ہے۔ اس میں بھی اللہ تعالیٰ کی بے شمار نشانیاں پوشیدہ ہیں : ﴿وَمِنۡ ءَايَٰتِهِۦ خَلۡقُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَثَّ فِيهِمَا مِن دَآبَّةࣲۚ وَهُوَ عَلَىٰ جَمۡعِهِمۡ إِذَا يَشَآءُ قَدِيرࣱ‏﴾ [الشوری: ۲۹] \"اوراس کی نشانیوں میں سے آسمان و زمین کی تخلیق ہے اور وہ جاندار مخلوق بھی جو اس نے ان دونوں (آسمانوں اور زمین) میں پھیلا رکھی ہے۔ وہ جب چاہے ان کو یکجا کرنے کی قدرت بھی رکھتا ہے\"۔\nاس آیت سے معلوم ہوتا ہے کہ زمین کی طرح آسمانوں میں بھی زندگی پائی جاتی ہے، جس کی دریافت میں آج ساینس داں لگے ہوے ہیں۔\n§دابہ کا بارش ہوتے ہی نکل آنا:\nکچھ دابہ ایسے بھی ہیں جوبارش ہوتے ہی زمین سے نکل آتے ہیں، جیساکہ ارشادباری تعالیٰ ہے : ﴿إِنَّ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ وَٱلۡفُلۡكِ ٱلَّتِي تَجۡرِي فِي ٱلۡبَحۡرِ بِمَا يَنفَعُ ٱلنَّاسَ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن مَّآءࣲ فَأَحۡيَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَا وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةࣲ وَتَصۡرِيفِ ٱلرِّيَٰحِ وَٱلسَّحَابِ ٱلۡمُسَخَّرِ بَيۡنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ لَأٓيَٰتࣲ لِّقَوۡمࣲ يَعۡقِلُونَ﴾ [البقرة: ۱۶۴] \"یقینا آسمانوں اور زمین کی پیدایش،رات دن کا ہیر پھیر، کشتیوں کا لوگوں کو نفع دینے والی چیزیں کو لیےہوے سمندروں میں چلنا۔ آسمان سے پانی اتار کر، مردہ زمین کو زندہ کر دینا اس میں ہر قسم کے جانوروں کو پھیلا دینا، ہواؤں کے رخ بدلنا اور بادل، جو آسمان اور زمین کے درمیان مسخر ہیں، ان میں عقلمندوں کے لئے قدرت الٰہی کی نشانیاں ہیں\"۔\n§دابہ کا سجدہ کرنا:\nارشادباری تعالیٰ ہے: ﴿وَلِلَّهِۤ يَسۡجُدُۤ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ مِن دَآبَّةࣲ وَٱلۡمَلَٰٓئِكَةُ وَهُمۡ لَا يَسۡتَكۡبِرُونَ يَخَافُونَ رَبَّهُم مِّن فَوۡقِهِمۡ وَيَفۡعَلُونَ مَا يُؤۡمَرُونَ۩﴾ [النحل: ۴۹-۵۰] \"تمام جاندار جوآسمان اور زمین دونوں میں ہیں اللہ تعالیٰ کو سجدہ کرتے ہیں اور فرشتے بھی اور وہ غرور اور تکبر بھی نہیں کرتے۔(بلکہ)اپنے رب سے جو ان کے اوپر ہے، ڈرتے ہیں اور جو انھیں حکم دیا جاتا ہے بجالاتے ہیں\"۔\nاللہ تعالیٰ کو سجدہ کرنا اور اس کی عبادت کرنا ہی پوری مخلوق کا اولین مقصدہے۔ لیکن ضروری نہیں کہ وہ سجدہ انسانوں کی طرح ہو۔ اسی طرح اللہ تعالیٰ سے ڈرنا بھی فطری ہے۔لیکن دوسری مخلوق کے ڈرنےاور انسانوں کے ڈرنے میں فرق ہے۔ ہمارا علم ابھی تک محدودہے اور ہمیشہ ہی محدود رہےگا۔ کبھی ہم اللہ تعالیٰ کے لامحدود علم کو نہیں جان سکیں گے۔ اس لیے اللہ تعالیٰ کی بتائی ہوئی ان باتوں پر ہم کو اسی طرح یقین کرنا چاہیے،جس طرح ظاہر اور دیکھی ہوئی باتوں پر یقین کرتے ہیں۔\n§دابہ کے گروہ:\nارشادباری تعالیٰ ہے: ﴿وَمَا مِن دَآبَّةࣲ فِي ٱلۡأَرۡضِ وَلَا طَٰٓئِرࣲ يَطِيرُ بِجَنَاحَيۡهِ إِلَّآ أُمَمٌ أَمۡثَالُكُمۚ مَّا فَرَّطۡنَا فِي ٱلۡكِتَٰبِ مِن شَيۡءࣲۚ ثُمَّ إِلَىٰ رَبِّهِمۡ يُحۡشَرُونَ﴾ [الأنعام: ۳۸] \"زمین میں چلنے والا کوئی بھی جاندارہو اور اپنے دو پرسے اڑنے والا کوئی بھی پرندہ ہو،ان سب کے تمھارے جیسے گروہ ہیں۔ہم نے کتاب میں کوئی چیز لکھنے سے چھوڑی نہیں۔ پھر وہ اپنے رب کی طرف جمع کیے جائیں گے\"۔\nکوئی بھی جاندار اور مخلوق زمین اور آسمانوں میں تنہا نہیں ہے۔ بلکہ ان کی بھی نسل ہوتی ہے اور انسانوں کی طرح ان کے بھی گروہ ہوتے ہیں۔جس طرح انسانوں کی تقدیرکتاب (لوح محفوظ ) میں لکھی ہوئی ہے، اسی طرح ان تمام مخلوقات کی تقدیربھی تحریر کی ہوئی ہے۔اسی تقدیر کے مطابق ان کو رزق حاصل ہوتا ہے۔ پھر عمر گزرنے کے بعد موت آجاتی ہے۔ یہ سب کچھ اللہ تعالیٰ نے اپنے ابدی اور ازلی علم سے لوح محفوظ میں لکھ رکھا ہے۔\n§دابہ کا رزق:\nقرآن کریم میں ہے: ﴿وَمَا مِن دَآبَّةࣲ فِي ٱلۡأَرۡضِ إِلَّا عَلَى ٱللَّهِ رِزۡقُهَا وَيَعۡلَمُ مُسۡتَقَرَّهَا وَمُسۡتَوۡدَعَهَاۚ كُلࣱّ فِي كِتَٰبࣲ مُّبِينࣲ‏﴾ [ہود: ۶] \"زمین پر چلنے والی کوئی ایسی مخلوق نہیں ہے،جس کی روزی اللہ تعالیٰ کے ذمہ نہ ہو اور جس کے رہنے کی جگہ اورجس کے سونپے جانے(مرنے) کی جگہ وہ نہ جانتا ہو۔سب کچھ ایک کھلی کتاب میں لکھا ہوا ہے\"۔\nسونپے جانے کی جگہ سےمراد اس کے مرنے کی جگہ ہے۔\nاس آیت کا مطلب جاننے کے لیے،اس صحیح حدیث کو دیکھنا ضروری ہے:عبداللہ بن عمرو بن العاص رضی اللہ عنہما کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کوفرماتے سنا: «کَتَبَ اللَّهُ مَقَادِيرَ الْخَلائِقِ قَبْلَ أَنْ يَخْلُقَ السَّمَاوَاتِ وَالأَرْضَ بِخَمْسِينَ أَلْفَ سَنَةٍ، قَالَ: وَعَرْشُهُ عَلَی الْمَاءِ». (صحیح مسلم: ۲۶۵۳) \"اللہ تعالیٰ نے آسمان اورزمین بنانے سے پچاس ہزار سال قبل ساری مخلوقات کی قسمت لکھ دی تھی۔اس وقت اس کا عرش پانی پر تھا\"۔\n§اللہ تعالیٰ کی پکڑ میں ڈھیل:\nقرآن کریم میں ہے: ﴿وَلَوۡ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِظُلۡمِهِم مَّا تَرَكَ عَلَيۡهَا مِن دَآبَّةࣲ وَلَٰكِن يُؤَخِّرُهُمۡ إِلَىٰٓ أَجَلࣲ مُّسَمࣰّ ىۖ فَإِذَا جَآءَ أَجَلُهُمۡ لَا يَسۡتَـٔۡخِرُونَ سَاعَةࣰ وَلَا يَسۡتَقۡدِمُونَ﴾ [النحل: ۶۱] \"اگر اللہ تعالیٰ لوگوں کو ان کے ظلم پر پکڑنے لگے تو زمین پر ایک جاندار کو بھی نہ چھوڑے۔ لیکن وہ انھیں ایک خاص وقت تک ڈھیل دیتا ہے۔ پھر جب ان کا مقررہ وقت آجائے گا تو نہ وہ ایک لمحہ پیچھے رہ سکتے ہیں اور نہ آگے بڑھ سکتے ہیں\"۔\n§قیامت سے پہلے نکلنے والا دابہ:\nقیامت کی نشانیوں میں سے ایک نشانی وہ دابہ ہے جو لوگوں سے باتیں کرےگا:﴿وَإِذَا وَقَعَ ٱلۡقَوۡلُ عَلَيۡهِمۡ أَخۡرَجۡنَا لَهُمۡ دَآبَّةࣰ مِّنَ ٱلۡأَرۡضِ تُكَلِّمُهُمۡ أَنَّ ٱلنَّاسَ كَانُواْ بِـَٔايَٰتِنَا لَا يُوقِنُونَ﴾ [النمل: ۸۲] \"جب ان کے اوپر عذاب کاقول ثابت ہوجائے گاتوہم زمین سے ان کے لیے ایک دابہ(جانور) نکالیں گے جو ان سے باتیں کرتا ہوگا۔ لوگ ہماری آیتوں پر یقین نہیں کرتے تھے\"۔\nیہ جانور ان لوگوں کو بتائے گا کہ انبیاورسل کی تعلیمات سچ تھیں۔لیکن تم نے اسے ٹھکرا دیا۔ اب اللہ تعالیٰ کے عذاب کے لیے تیار ہوجاؤ۔ اس دابہ کی زبان سے توحید کا بیان حقیقت میں اللہ تعالیٰ کی طرف سے ایک تنبیہ ہے کہ تم نے اپنے جیسے انسانوں کی باتوں کو ٹھکرا دیا۔لیکن اب تم اس دابہ کی بات کیسے ٹھکراؤگے کیونکہ اس وقت ایمان لانے کا وقت نکل چکا ہوگا۔","",{}],[275,"§دال\nدیکھیے: عدس","",{}],[276,"§داود علیہ السلام\nداود علیہ السلام بنی اسرئیل کے عظیم نبی تھے۔اُن کا ذکر قرآن مجیدمیں بھی آیا ہے۔بائبل کے زیادہ تر مزامیر(مدح) انھیں کی طرف منسوب کیے جاتے ہیں۔بائبل کے مطابق داود علیہ السلام تقریباً ایک ہزار سال قبل مسیح بیت اللحم (فلسطین) میں پیدا ہوے۔ان کے والد کا نام پسی تھا جو ابراہیم علیہ السلام کےخاندان سے تھے۔ اللہ تعالیٰ نے ان کو بہت طاقتوربنایا تھا۔ایک بار جب وہ بکریاں چرارہے تھے تو ایک شیر اور بھالو نے ان پر حملہ کردیا۔ انھوں نے اکیلے دونوں کامقابلہ کیااور دونوں کو مار دیا۔ (بائبل-شمویل اول:۱۷،۱۶۱۱:۳۴ـ۳۶)\nقرآن مجید نے بھی ان کے طاقتور ہونے کی طرف کا اشارہ کیا ہے:﴿وَلَقَدۡ ءَاتَيۡنَا دَاوُۥدَ مِنَّا فَضۡلࣰ اۖ يَٰجِبَالُ أَوِّبِي مَعَهُۥ وَٱلطَّيۡرَۖ وَأَلَنَّا لَهُ ٱلۡحَدِيدَ أَنِ ٱعۡمَلۡ سَٰبِغَٰتࣲ وَقَدِّرۡ فِي ٱلسَّرۡدِۖ﴾ [سبأ: ۱۰-۱۱] \"اورہم نے داود کو اپنی طرف سے عظمت عطا کی تھی۔ اے پہاڑو! اس کے ساتھ مل کر تسبیح کرو اور اے پرندوں! تم بھی۔ ہم نے اس کے لیے لوہے کو نرم کردیا کہ پوری پوری زرہیں بناؤ اور کڑیوں کو ٹھیک اندازہ سے جوڑ دو\"۔\nایک دوسری جگہ پر نبی صلی اللہ علیہ وسلم کوتسلی دی جارہی ہےکہ آپ بھی داود علیہ السلام کی طرح صبرکریں کیونکہ داود بہت طاقتور تھے۔ لیکن ان کو بھی تکلیف اٹھانی پڑی۔مگر وہ اللہ تعالیٰ کی طرف ہی دھیان لگائے رہے: ﴿ٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَٱذۡكُرۡ عَبۡدَنَا دَاوُۥدَ ذَا ٱلۡأَيۡدِۖ إِنَّهُۥٓ أَوَّابٌ﴾ [ص: ۱۷] \"ان کی باتوں پر صبر سے کام لو اورہمارے بندے داود کو یاد کرو جو بہت طاقتورتھا۔ یقینا وہ اللہ تعالیٰ کی طرف بہت دھیان لگائے رہتا تھا\"۔\nنتیجۃً اللہ تعالی نے داود علیہ السلام کو حاکم بنادیا:﴿يَٰدَاوُۥدُ إِنَّا جَعَلۡنَٰكَ خَلِيفَةࣰ فِي ٱلۡأَرۡضِ فَٱحۡكُم بَيۡنَ ٱلنَّاسِ بِٱلۡحَقِّ وَلَا تَتَّبِعِ ٱلۡهَوَىٰ فَيُضِلَّكَ عَن سَبِيلِ ٱللَّهِۚ﴾ [ص: ۲۶] \"اے داود!ہم نے تمھیں زمین میں خلیفہ (بادشاہ) بنایا ہے۔اس لیے لوگوں کے درمیان حق کے ساتھ فیصلہ کرو اور اپنی خواہش کی پیروی نہ کرنا کہ وہ تجھے اللہ کی راہ سے گمراہ کردے گی\"۔\nپھر ایسا ہوا کہ بنی اسرائیل کی درخواست پر اللہ تعالی نے طالوت نامی شخص کو ان کا حاکم بنادیا تاکہ وہ جالوت نامی حاکم سے محفوظ رہ سکیں جو لگاتار ان پر حملہ کررہا تھا۔قرآن مجید اسی طرف اشارہ کرتا ہے:\n۱- ﴿أَلَمۡ تَرَ إِلَى ٱلۡمَلَإِ مِنۢ بَنِيٓ إِسۡرَٰٓءِيلَ مِنۢ بَعۡدِ مُوسَىٰٓ إِذۡ قَالُواْ لِنَبِيࣲّ لَّهُمُ ٱبۡعَثۡ لَنَا مَلِكࣰ ا نُّقَٰتِلۡ فِي سَبِيلِ ٱللَّهِۖ﴾ [البقرة: ۲۴۶] \"کیا تم نےبنی اسرائیل کے سرداروں کو نہیں دیکھا،جب موسیکے بعد انھوں نے اپنے ایک نبی سے کہا کہ ہمارے لیے ایک حاکم مقرر کردیں، تاکہ ہم اللہ تعالیٰ کے راستامیں جنگ کریں\"۔\n۲- ﴿وَقَالَ لَهُمۡ نَبِيُّهُمۡ إِنَّ ٱللَّهَ قَدۡ بَعَثَ لَكُمۡ طَالُوتَ مَلِكࣰ اۚ﴾ [البقرة: ۲۴۷] \"ان کے نبی نے ان سے کہا: اللہ تعالیٰ نے تمھارے لیےطالوت کو حاکم مقرر کیا ہے\"۔\n۳- ﴿فَهَزَمُوهُم بِإِذۡنِ ٱللَّهِ وَقَتَلَ دَاوُۥدُ جَالُوتَ وَءَاتَىٰهُ ٱللَّهُ ٱلۡمُلۡكَ وَٱلۡحِكۡمَةَ وَعَلَّمَهُۥ مِمَّا يَشَآءُۗ﴾ [البقرة: ۲۵۱] \"(مومنوں نے) اللہ کے حکم سے ان کو شکست دی اور داود نے جالوت کو قتل کردیا اور اللہ نے داود کو بادشاہی اور حکمت عطا کی اور جو چاہا سکھایا\"۔\nبائبل میں اس کا بیان اس طرح آیا ہے:\nجالوت جسے بائبل میں جلیاط کہا گیاہے۔بڑا ظالم تھا۔بنی اسرائیل پر کئی بارحملے کر چکا تھا۔یہاں تک کہ ان کا وہ تابوت بھی چھین کر لے گیا، جس کو وہ مصر سے لائے تھے۔ اس لیے بنی اسرائیل نے اپنے نبی شموئیل سے التجا کی کہ ہمارے لیے بھی کوئی حاکم مقرر کردیں تاکہ اس کے ساتھ مل کرفلسطینیوں اور قریب کے دوسرے سرداروں کے خلاف جنگ کریں۔ان کے نبی نے شاؤل نام کا ایک بادشاہ مقررکردیا،جس کو قرآن مجید میں طالوت کہا گیا ہے۔ جو اپنے ساتھیوں کو لے کر جالوت سے جنگ کرنے نکل پڑا دونوں کی فوجیں بیت اللحم کے قریب کوئی پندرہ میل مغرب میں جمع ہوگئیں۔داود کے والد پسی کے دو بیٹے جنگ میں شامل تھے۔اس لیے پسی نے داود کو بھیجا کہ اپنے بھائیوں کی خبر لے کر آئے۔جب داود وہاں پہنچے تو دیکھا کہ جالوت طالوت کے جوانوں کو للکار رہا ہے۔ لیکن اس کے لمبے چوڑے جسم کی وجہ سے کسی نے ہمت نہیں کی کہ آگے بڑھے۔یہ دیکھ کر داود سے نہ رہا گیا۔وہ آگے بڑھے اور موقع دیکھ کر اس کی پیشانی پہ تین پتھرمارے جس سے خون بہنے لگا اور وہ چکرکھاکرزمین پرگر پڑا۔داود آگے بڑھے اور اسی کی تلوارسے اسے موت کے گھاٹ اتار دیا۔یہ تقریباً ۱۰۱۰ قبل مسیح کا واقعہ ہے۔جب یہ خبرطالوت تک پہنچی تو وہ بہت خوش ہوا اور اپنی بیٹی کی شادی داود کے ساتھ کردی اور انھیں اپنی فوج کا سردار بنا دیا۔داود کی بہادری سے بنی اسرائیل بہت متاثر ہوے اور ان کی بہادری کےنغمے گانے لگے جس سے طالوت حسد کرنے لگا اور طرح طرح سے ان کے قتل کی سازش کرنے لگا۔ اس لیے وہ اس کے دربار سے نکل کر ہبرون چلے گئے جہاں لوگوں نے ان کو اپنا بادشاہ بنا لیا۔ ساڑھے سات سال تک وہ حکمرانی کرتے رہے۔ طالوت کی موت کے بعد بنی اسرائیل نے ان کو اپنا حاکم بنا لیا۔\n۹۷۱قبل مسیح میں ان کا انتقال ہوا۔ان کے بعد ان کے بیٹے سلیمان علیہ السلام تخت نشین ہوے۔\nداود علیہ السلام ایکعظیم حاکم ہونے کے ساتھ ساتھ ایک عظیم نبی بھی تھے۔جو بنی اسرائیل کی اصلاح کےلیے بھیجے گئے تھے۔اللہ تعالیٰ نے ان پر زبور نازل کی۔قرآن مجید میں ہے:﴿وَءَاتَيۡنَا دَاوُۥدَ زَبُورࣰ ا﴾ [النساء: ۱۶۳] \"ہم نے داود کو زبور عطا کیا\"۔\nوہ زبوراتنی دلکش آواز میں پڑھتے تھےکہ پرندےاور پہاڑ بھی ان کے ساتھ جمع ہوکر اللہ تعالیٰ کی تسبیح (بڑائی) بیان کرنے لگتے تھے:﴿وَسَخَّرۡنَا مَعَ دَاوُۥدَ ٱلۡجِبَالَ يُسَبِّحۡنَ وَٱلطَّيۡرَۚ وَكُنَّا فَٰعِلِينَ﴾ [الأنبیاء: ۷۹] \"اور داود کے ساتھ ہم نے پہاڑوں اور پرندوں کوماتحت کر دیا تھا کہ وہ اللہ تعالیٰ کی تسبیح کریں اورہم ہی ایسا کرنے والے تھے\"۔\nاورفرمایا: ﴿وَلَقَدۡ ءَاتَيۡنَا دَاوُۥدَ مِنَّا فَضۡلࣰ اۖ يَٰجِبَالُ أَوِّبِي مَعَهُۥ وَٱلطَّيۡرَۖ وَأَلَنَّا لَهُ ٱلۡحَدِيدَ﴾ [سبأ: ۱۰] \"ہم نےداود پر بڑا احسان کیا تھا۔اے پہاڑو اور پرندوں! اس کے ساتھ تسبیح کو بلند آواز میں کہو اورہم نے اس کے لیے لوہے کو نرم کر دیا\"۔\nمزیدارشادہے: ﴿إِنَّا سَخَّرۡنَا ٱلۡجِبَالَ مَعَهُۥ يُسَبِّحۡنَ بِٱلۡعَشِيِّ وَٱلۡإِشۡرَاقِ وَٱلطَّيۡرَ مَحۡشُورَةࣰۖ كُلࣱّ لَّهُۥٓ أَوَّابࣱ‏﴾ [ص: ۱۸-۱۹] \"ہم نے پہاڑوں کو اس کے ماتحت کر دیا کہ شام اور صبح کے اوقات میں تسبیح کرتےرہیں اور پرندوں کو جو جمع ہوجاتے تھے سب اس کے حکم کی پیروی کرنے والے تھے\"۔\nداود علیہ السلام کی شیریں آواز کا تذکرہ بائبل میں بھی بہت تفصیل سے آیا ہے۔ (تواریخ اوّل: ۶:۳۱؛۱۶:۷؛۴۱ـ۴۳؛ ۲۵:۱)\nداود علیہ السلام پر اللہ تعالی نے زبور کو نازل کیا تھا جسے بہت دنوں تک لوگ پڑھا کرتے رہے اور یاد کرتے رہے۔\nحقیقت یہ ہےکہ پانچویں صدی قبل مسیح میں ماہرین نے زبور کی دریافت کی۔یہ زبور اس وقت نغمے کی شکل میں تھی۔پھر بعد میں ان کو کچھ اور نغمے مل گئے۔سب کو ملاکر انھوں نے ایک کتاب کی شکل دےدی،جس میں کل ۱۵۰ نغمے تھے۔اس میں سے تہتّر(۷۳) داود کےہیں،باقی دوسروں کے۔ان کو پانچ کتابوں میں تقسیم کیا گیا ہے۔پہلی کتاب میں کل ۴۱ نغمے ہیں۔جن میں سے ۳۷ داود کے اور باقی دوسروں کےہیں جن کا صحیح پتہ لگانا مشکل ہے کہ کس کے ہیں۔اس لیے ان کو لاوارث نغمےکہتے ہیں۔دوسری کتاب میں کل ۳۱ نغمے ہیں، جن میں سے۱۸داود کے اور باقی دوسروں کے ہیں۔تیسری کتاب میں کل ۱۷ نغمے ہیں، جن میں سے صرف ایک داود کا ہےباقی دوسروں کے ہیں۔ چوتھی کتاب میں بھی کل ۱۷ نغمے ہیں، جن میں سے صرف ۲ داود کےہیں، باقی دوسروں کے۔پانچویں کتاب میں ۴۴ نغمے میں، جن میں سے ۱۵ داود کے، باقی کے دوسروں کے ہیں۔ (دیکھیے: قاموس کتاب مقدس: صفحہ۴۳۰، ۴۳۱)\nقرآن کریم کے مطابق داود علیہ السلام کو اعلی مرتبہ عطاکیا گیا تھا?وہ اس طرح کہ اللہ تعالیٰ نے ان کی ریاست کو مستحکم کردیا تھا اور ان کو عقل مند بنایاتھا جو سخت سے سخت پریشانی میں بھی آسانی کے ساتھ مسئلہ حل کردیتے تھے۔ ارشادباری تعالیٰ ہے: ﴿وَشَدَدۡنَا مُلۡكَهُۥ وَءَاتَيۡنَٰهُ ٱلۡحِكۡمَةَ وَفَصۡلَ ٱلۡخِطَابِ﴾ [ص: ۲۰] \"ہم نے اس کی ریاست کو مستحکم کردیا تھا، اسے عقل مند بنایا تھا اور فیصلہ کن بات کرنے کی قابلیت عطاکی تھی\"۔\nقرآن مجید میں ان کی حکمت اور عقل مندی کے ایک واقعےکا ذکر کیا گیا ہے۔ ان کے پاس دوشخص اپنا مقدمہ لے کر پہنچے۔ان میں سے ایک نے کہا:﴿إِنَّ هَٰذَآ أَخِي لَهُۥ تِسۡعࣱ وَتِسۡعُونَ نَعۡجَةࣰ وَلِيَ نَعۡجَةࣱ وَٰحِدَةࣱ فَقَالَ أَكۡفِلۡنِيهَا وَعَزَّنِي فِي ٱلۡخِطَابِ﴾ [ص: ۲۳] \"یہ میرا بھائی ہے اس کے پاس ننانوے بکریاں ہیں اور میرے پاس صرف ایک بکری ہے۔اب اس کا کہنا ہے کہ یہ (ایک بکری) بھی میرے حوالے کردو اور اس نے بات چیت سے مجھے دبالیا\"۔\nداود علیہ السلام نے اس کےبهائی کی حرکت کو غلط بتاتےہوے صحیح فیصلہ سنادیا۔ اسی وقت ان کو اپناکوئی واقعہ یاد آگیا اوروہ فوراً سجدہ میں گر کر اپنے رب سے معافی کی دعا کرنے لگے۔وہ کیا واقعہ تھا، قرآن اور صحیح احادیث میں اس کا ذکر نہیں آیا ہے۔لیکن ہوسکتا ہے کہ سورہ ص کی آیت: ۲۳میں جوننانوےبکریوں کاذکرہواہے،اس سےمرادان کی بیویاں ہوسکتی ہیں۔ کیونکہ عربی زبان میں عورتوں کی بکریوں سےمثال دی جاتی ہے۔\nعبداللہ بن عباس رضی اللہ عنہما کاایک صحیح قول آیا ہے کہ داود علیہ السلام نےاس شخص سے(جس کا نام بائبل میں حتیّ آیا ہے)درخواست کی کہ وہ اپنے بیوی سے الگ ہوجائے۔جیسا کہ ابو المظفر سمعانی (وفات۴۸۹ھ)نے اپنی تفسیر میں ذکر کیا ہے۔\nتوجب داود علیہ السلام کو اپنی غلطی کا احساس ہوا تو سجدے میں گر گئے اور اللہ تعالیٰ سے معافی مانگنے لگے۔\nاتنی سی بات کو بائبل میں بڑھا چڑھا کراور اضافہ کرکے اس طرح بیان کیا گیا ہے کہ انھوں نے حتّی کی بیوی سے زنا کیا اورحتی کہ جان بوجھ کر ایک جنگ میں قتل کرادیا اور اس کی بیوی سے شادی کرلی۔ (اس کی پوری تفصیل شمویل۲، باب۱۱ـ۱۲ میں دیکھیں)\nداود علیہ السلام کو اللہ تعالی نے جو معجزے دیے تھے ان میں ایک یہ تھا کہ ان کے لیے لوہے کو موم جیسا نرم اور ملائم بنادیا۔قرآن مجید میں ہے:﴿وَلَقَدۡ ءَاتَيۡنَا دَاوُۥدَ مِنَّا فَضۡلࣰ اۖ يَٰجِبَالُ أَوِّبِي مَعَهُۥ وَٱلطَّيۡرَۖ وَأَلَنَّا لَهُ ٱلۡحَدِيدَ أَنِ ٱعۡمَلۡ سَٰبِغَٰتࣲ وَقَدِّرۡ فِي ٱلسَّرۡدِۖ وَٱعۡمَلُواْ صَٰلِحًاۖ إِنِّي بِمَا تَعۡمَلُونَ بَصِيرࣱ‏﴾ [سبأ: ۱۰-۱۱] \"اور ہم نے داود پر اپنا فضل کیااے پہاڑو! اس کے ساتھ رغبت سے تسبیح پڑھا کرو اور پرندوں کو بھی(یہی حکم ہے) اور ہم نے اسی لئے لوہا نرم کر دیا کہ تو پوری پوری زرہیں بنا اور جوڑوں میں اندازہ رکھ تم سب نیک کام کرویقین مانو کہ میں تمھارے اعمال دیکھ رہا ہوں\"۔\nاسی طرح اللہ تعالی نے داود علیہ السلام پر بہت احسانات کیے کیونکہ وہ اللہ کے سچے بندے تھے: ﴿وَٱذۡكُرۡ عَبۡدَنَا دَاوُۥدَ ذَا ٱلۡأَيۡدِۖ إِنَّهُۥٓ أَوَّابٌ﴾ [ص: ۱۷] \"اور ہمارے بندے داود کو یاد کرو جو بہت طاقتور تھا۔ یقیناًوہ اللہ تعالیٰ کی طرف دھیان دینے والا تھا\"۔\nاللہ تعالی نبی محمد صلی اللہ علیہ وسلم کوداود علیہ السلام کی کہانی بتاکرصبرکرنے کاحکم دے رہا ہے کہ جس طرح ہم نے داود علیہ السلام کو اس کے اعمال کا بدلہ دیا اور اس کو دنیا میں حکمرانی بخشی اسی طرح آپ کو بھی ایک دن دنیا میں حکمرانی حاصل ہوگی۔","",{}],[277,"§دعا\nدعاکرنا حقیقت میں اللہ تعالیٰ کی عبادت کرنا ہے۔ کیونکہ دعاکے ذریعے سے بندہ اپنے آپ کو اللہ تعالیٰ کےسامنے بہت کمزور حالت میں پیش کرتا ہے اوراس بات کا دل میں یقین رکھتا ہے کہ دینے والا صرف اللہ ہے۔اس لیے اسی سے مانگنا چاہیے۔اللہ تعالی نے قرآن مجید میں خود حکم دیا ہے کہ مجھ سے ہی مانگو، میں ہی دوں گا: ﴿وَقَالَ رَبُّكُمُ ٱدۡعُونِيٓ أَسۡتَجِبۡ لَكُمۡۚ إِنَّ ٱلَّذِينَ يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِي سَيَدۡخُلُونَ جَهَنَّمَ دَاخِرِينَ﴾ [غافر: ۶۰] \"تمھارے رب نے کہا: مجھ سے ہی مانگو۔میں ہی تمھاری دعاقبول کروں گا بےشک جولوگ میری عبادت کے معاملے میں غرور سے کام لیتے ہیں وہ جلدہی ذلیل ہوکر جہنم میں پہنچ جائیں گے\"۔\nاورفرمایا: ﴿ٱدۡعُواْ رَبَّكُمۡ تَضَرُّعࣰ ا وَخُفۡيَةًۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ﴾ [الأعراف: ۵۵] \"اپنے رب کو گڑ گراکر اورتنہائی میں پکارو۔بےشک وہ حد سے آگے بڑھنے والوں سے محبت نہیں کرتا\"۔\nدعا کرنا حقیقت میں اللہ تعالیٰ کی عبادت کرنا ہے: نعمان بن بشیر رضی اللہ عنہما سے مروی حدیث میں آیا ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «الدُّعَاءُ هُوَ الْعِبَادَةُ، [آیت] \" [غافر: ۶۰]». (سنن ابی داود: ۱۴۷۹، سنن الترمذی: ۲۹۶۹، وسنن ابن ماجہ: ۳۸۲۸ ومسند احمد: ۸: ۲۶۷) \"دعا عبادت ہی ہے،پھرآپ نے سورہ مومن کی آیت پڑھی: [آیت] \"۔\nہر مسلمان پر لازم ہے کہ وہ اللہ سے دعا کرتا رہے کیونکہ دعا سے قسمت بدل سکتی ہےسلمان فارسی رضی اللہ عنہ سے مروی حدیث میں نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «لاَ يَرُدُّ الْقَضَاءَ إِلاَّ الدُّعَاءُ وَلاَ يَزِيدُ فِی الْعُمُرِ إِلاَّ الْبِرُّ». \"قسمت کو دعا کے علاوہ کوئی اور چیز نہیں بدل سکتی\"۔\nلیکن قسمت میں جو لکھا ہے وہ تو مٹ نہیں سکتا۔ اس لیے اس حدیث کا مطلب یہ ہے کہ وہی دعا قبول کی جائے گی جو قسمت سے منسلک ہو، اس سے ٹکراتی نہ ہو، چونکہ ہمیں قسمت کا علم نہیں اس لیے دعا کرنی چاہیے کہ قسمت سے ٹکرائے بنا ہماری دعا قبول کرلی جائے۔کیونکہ دعا خود قسمت کا ایک حصہ ہے۔\nاسی لیے انبیاکرام نے دعا کی: ﴿وَأَيُّوبَ إِذۡ نَادَىٰ رَبَّهُۥٓ أَنِّي مَسَّنِيَ ٱلضُّرُّ وَأَنتَ أَرۡحَمُ ٱلرَّٰحِمِينَ﴾ [الأنبیاء: ۸۳] \"اورایوب کویاد کرو جب اس نے اپنے رب سے دعا کی: مجھے بیماری لگ گئی ہے اور تو سب سے بڑھ کر رحم کرنے والا ہے\"۔\nدعا قبول ہویا نہ ہو بہر حال اس سے دل کو سکون ملتا ہےاور پریشانیوں پر صبرسے کام لینے کی ہمت بڑهی ہے۔ایک حدیث میں نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «مَا مِنْ مُسْلِمٍ يَدْعُو بِدَعْوَةٍ لَيْسَ فِيهَا إِثْمٌ، وَلاَ قَطِيعَةُ رَحِمٍ، إِلاَّ أَعْطَاهُ اللَّهُ بِهَا إِحْدَی ثَلاَثٍ: إِمَّا أَنْ تُعَجَّلَ لَهُ دَعْوَتُهُ، وَإِمَّا أَنْ يَدَّخِرَهَا لَهُ فِي الآخِرَةِ، وَإِمَّا أَنْ يَصْرِفَ عَنْهُ مِنَ السُّوءِ مِثْلَهَا، قَالُوا: إِذًا نُکْثِرُ، قَالَ: اللَّهُ أَکْثَرُ». (مسنداحمد ۱۱۱۵۰، ۱۱۱۳۳ بروایت ابوسعیدخدری رضی اللہ عنہ ) \"کوئی مسلمان جب دعا کرتا ہے، اگر اس میں گناہ نہ ہو اور نہ رشتے داری کاٹنے کی بات ہو تو اللہ مندرجہ ذیل تین چیزوں میں سے ایک چیزضرور ہی دیتا ہے:یا تو اس کی دعا فوراً قبول کرلی جاتی ہے یا اسے قیامت کے دن کے لیے محفوظ کرلیا جاتا ہےیا اس کی جگہ پر اس کی کوئی مصیبت دورکردی جاتی ہے؟\"لوگوں نے کہا: \"تب تو ہم خوب دعاکیا کریں گے\"? نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اللہ اس سے بھی زیادہ دینے والا ہے\"۔\nاس سے معلوم ہوا کہ دعاخود ایک عبادت ہے اور دوسری عبادات کی طرح یہ عبادت بھی صرف اللہ کے لیے مخصوص ہے۔اب اللہ تعالیٰ کو چھوڑ کر کوئی کسی غیر کو پکارتا ہے، اس سے اپنی حاجات مانگتا ہے تو ایک طرح سے وہ شرک کرتا ہے۔\nارشاد باری تعالی ہے:\n۱-﴿وَأَنَّ ٱلۡمَسَٰجِدَ لِلَّهِ فَلَا تَدۡعُواْ مَعَ ٱللَّهِ أَحَدࣰ ا﴾ [الجن: ۱۸] \"اورمسجدیں تو صرف اللہ تعالیٰ کے لیے ہیں اس لیے اللہ کے سوا کسی اور کو نہ پکارو\"۔\n۲- ﴿إِنَّ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِ عِبَادٌ أَمۡثَالُكُمۡۖ فَٱدۡعُوهُمۡ فَلۡيَسۡتَجِيبُواْ لَكُمۡ إِن كُنتُمۡ صَٰدِقِينَ﴾ [الأعراف: ۱۹۴] \"تم لوگ اللہ کے سوا جنھیں پکارتے ہو وہ تو تمھاری طرح ہی بندے ہیں اس لیے پکار لو ان کو اگر تم سچے ہو، تو انھیں چاہیے وہ تمھیں جواب دیں\"۔\nسچ تو یہ ہے: ﴿وَٱلَّذِينَ تَدۡعُونَ مِن دُونِهِۦ لَا يَسۡتَطِيعُونَ نَصۡرَكُمۡ وَلَآ أَنفُسَهُمۡ يَنصُرُونَ﴾ [الأعراف: ۱۹۷] \"جنھیں تم اللہ کو چھوڑکر پکارتے ہوان میں نہ تمھاری مددکرنے صلاحیت ہے اور نہ وہ تمھاری مدد کرسکتے ہیں\"۔\nاورفرمایا: ﴿ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡ لَهُ ٱلۡمُلۡكُۚ وَٱلَّذِينَ تَدۡعُونَ مِن دُونِهِۦ مَا يَمۡلِكُونَ مِن قِطۡمِيرࣲ إِن تَدۡعُوهُمۡ لَا يَسۡمَعُواْ دُعَآءَكُمۡ وَلَوۡ سَمِعُواْ مَا ٱسۡتَجَابُواْ لَكُمۡۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ يَكۡفُرُونَ بِشِرۡكِكُمۡۚ وَلَا يُنَبِّئُكَ مِثۡلُ خَبِيرࣲ﴾ [فاطر: ۱۳-۱۴] \"یہی تمھارا رب ہے، اسی کی بادشاہت ہے،اسے چھوڑ کر جن کو تم پکارتے ہو وہ تو ایک قطمیر(کھجور کی گٹھلی کی جھلی) کے بھی مالک نہیں ہیں۔ اگر تم انھیں پکارو تووہ تمھاری پکار نہیں سنیں گےاور اگر سنتے تو بھی تمھارا جواب نہ دیتے اور قیامت کے دن وہ تمھارے شرک کا انکار کردیں گے(اللہ تعالیٰ کی طرح ) تم کوکوئی خبر دینے والا نہیں\"۔\nالیاس علیہ السلام ایک رسول تھے انھوں نے اپنی قوم سے کہا: ﴿وَإِنَّ إِلۡيَاسَ لَمِنَ ٱلۡمُرۡسَلِينَ إِذۡ قَالَ لِقَوۡمِهِۦٓ أَلَا تَتَّقُونَ أَتَدۡعُونَ بَعۡلࣰ ا وَتَذَرُونَ أَحۡسَنَ ٱلۡخَٰلِقِينَ ٱللَّهَ رَبَّكُمۡ وَرَبَّ ءَابَآئِكُمُ ٱلۡأَوَّلِينَ﴾ [الصافات: ۱۲۳-۱۲۶] \"الیاس بھی نبیوں میں سے تھے۔ انھوں نے اپنی قوم سے کہا: کیا تم اللہ سے ڈرتے نہیں۔ کیا تم بعل کو پکارتے ہو اور سب سے اچھے پیدا کرنے والے کو چھوڑ دیتے ہو۔ اس اللہ تعالیٰ کو جو تمھارا بھی رب ہے اور تمھارے اگلے آبا واجدادکا بھی رب ہے\"۔\nجب یہ بات ہے تو ہماری تمام دعائیں صرف اللہ ہی کے لیے ہی ہونی چاہییں۔اس لیے نبی اکرم صلی اللہ علیہ وسلم نےمختلف حالات میں اور مختلف اوقات کے لیے دعائیں بتائی ہیں۔جیسے قرض اتارنے کی دعا، بیماری سے شفا پانے کی دعا، سفر پر نکلنے سے پہلے کی دعا، کسی پریشانی سےنکلنے کی دعاوغیرہ۔یہ دعائیں حدیث کی کتابوں میں موجود ہیں۔\nاس لیے ایک مسلمان کو چاہیے کہ ان دعاؤں کو یاد کرلےاور پابندی کے ساتھ اپنی ضروریات کی تکمیل کےلیے صرف اللہ تعالیٰ سے دعا کرے۔امیدہے کہ اس کی دعائیں قبول ہوں گی اورمرادیں پوری بھی ہوں گی۔قیامت کے دن بہت حیرت انگیز نظارہ ہوگا جب وہ جن کو دنیامیں لوگ اپنی حاجتوں کے لیے پکارا کرتے تھے اپنے کو اللہ تعالیٰ کا شریک ٹھہرانے سے انکارکریں گے اور کہیں گے: ہم نے کب کہا تھا کہ اللہ تعالیٰ کو چھوڑ کر ہمیں پکارو،ہم تمھاری حاجتوں کوپورا کریں گے۔ہم تمھارے اس شرک سے انکار کررہے ہیں۔ ہم تو خود اللہ تعالیٰ سے اپنی کامیابی اور نجات کے لیے دعا کرتے ہیں۔ بھلا ہم تمھیں کیا فائدہ پہنچا سکیں گے۔","",{}],[278,"§دم\nدم کے معنی خون کے ہیں۔خون کاپینا حرام ہے۔ قرآن مجید میں ارشاد ہے:﴿إِنَّمَا حَرَّمَ عَلَيۡكُمُ ٱلۡمَيۡتَةَ وَٱلدَّمَ وَلَحۡمَ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ بِهِۦ لِغَيۡرِ ٱللَّهِۖ﴾ [البقرة: ۱۷۳] \"اس نے تو تم پر صرف مردہ اور خون اورخنزیر کا گوشت اور جس پر اللہ تعالیٰ کےسوا کسی اور کا نام لیا گیا ہو،حرام ٹھہرایا ہے\"۔\nلہٰذا ضروری ہے کہ جانور کو ذبح کیا جائے۔ تاکہ اس کا خون نکل جائے۔ اس لیے بجلی سے مرے ہوے، گلے کو ایک ہی جھٹکے میں کاٹ دیے جانے سے مرے ہوےیافطری موت مرے ہوے جانور کا گوشت کھانا حرام ہے۔ کیونکہ اس طرح سے مرنے پر جانور کے جسم میں اس کا خون رہ جاتا ہے۔","",{}],[279,"§دنوں کا الٹ پھیر\nدیکھیے: تداول ایام","",{}],[280,"§د ودھ\nدیکھیے: لبن","",{}],[281,"§دوزخ\nدیکھیے: جہنم","",{}],[282,"§دوست\nدیکھیے: ولی","",{}],[283,"§دينی گفتگو\nدیکھیے: کلمہ (مکالمہ)","",{}],[284,"§دین پر مضبوطی سے جمے رہنا\nدیکھیے: اعتصام بحبل اللہ","",{}],[285,"§دیہاتی\nدیکھیے: اعراب","",{}],[286,"§ذباب\nذباب کے معنی ہیںمکھی۔ یہ کیڑے مکوڑوں میں سے ایک حقیرچیزہے۔زیادہ ترمشرقی ممالک میں مکھیاں پائی جاتی ہیں۔جہاں گرمی زیادہ پڑتی ہے۔جہاں یہ لوگوں کو پریشان کرتی ہیں،وہیں ان کی کچھ قسمیں زہریلی بھی ہوتی ہیں۔\nقرآن مجیدمیں ایک ہی آیت میں دو بار اس کا ذکر آیا ہے اور دونوں بار اس کی حقارت اور کم مائیگی کی مثال دی گئی ہے: ﴿يَٰٓأَيُّهَا ٱلنَّاسُ ضُرِبَ مَثَلࣱ فَٱسۡتَمِعُواْ لَهُۥٓۚ إِنَّ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِ لَن يَخۡلُقُواْ ذُبَابࣰ ا وَلَوِ ٱجۡتَمَعُواْ لَهُۥۖ وَإِن يَسۡلُبۡهُمُ ٱلذُّبَابُ شَيۡـࣰٔ ا لَّا يَسۡتَنقِذُوهُ مِنۡهُۚ ضَعُفَ ٱلطَّالِبُ وَٱلۡمَطۡلُوبُ﴾ [الحج: ۷۳] \"اےلوگو! ایک مثال دی جارہی ہے،جس کو توجہ سےسنو۔ اللہ کے سوا تم جن جن کو پکارتے ہو وہ ایک مکھی بھی تو پیدا نھیں کرسکتے،خواہ سارے کے سارے جمع ہوجائیں، بلکہ مکھی ان سے کوئی چیز لے بھاگے تو یہ تو اس سے چھین بھی نہیں سکتے۔مانگنے والا اور جس سے مانگا جائے دونوں ہی کتنے لاچار ہیں\"۔\nجو لوگ اللہ کو چھوڑ کر کسی دیوی دیوتا،قبر،اینٹ،پتھروغیرہ کو اپنا معبود اور مشکل کشا بنا بیٹھے ہیں ان کے لیے اس مثال میں بڑی نصیحت ہے۔","",{}],[287,"§ذبح\nجانوروں کو ایک مخصوص طریقے (اسلامی طریقے) سےقتل کرنے کو ذبح کہتے ہیں۔\nجانوروں کو ذبح کرتے وقت اللہ کا نام لینا لازم ہے۔ اگر اس کو کسی اور کے نام پر ذبح کیا گیا تو اسلامی تعلیمات کے مطابق وہ حرام ہوجائے گا۔(سورہ البقرہ: ۱۷۳)\nاسی طرح اگر کسی دیوی دیوتا اور قبر وغیرہ کی جگہ پر ذبح کیا جائے تو وہ بھی حرام ہوجاتا ہے۔( المائدہ: ۳)\nسورہ المائدہ کی اسی آیت میں ان جانوروں کا کھانا بھی حرام بتایا گیا ہے جو سانس گھٹ کریا چوٹ کهاکر یا اونچائی سے گر کراور سینگ لگنے سے مر گئے ہوں سوائے ان کے جنھیں کوئی زندہ پاکر ذبح کرلے۔","",{}],[288,"§ذکر\nذکرکا لفظ قرآن مجیدمیں کئی معنوں میں استعمال ہوا ہے۔\n۱- عام طورپرذکرسے مراد اللہ کاذکرہے۔ذکرالٰہی کے سارے معانی کاخلاصہ صرف اللہ تعالیٰ کی عبادت اوراس کی اطاعت اوراس کی حمدوثناہے۔صرف اسی کوپکارنا اور اسی سے سوال کرنا ہے۔یہ ذکر دل وزبان سے،خفیہ اورعلانیہ اورہرحال میں مطلوب ہے۔اللہ کو یاد کرنے،اس کے نام کے ذکر،اس کی حکومت اور اس کی عظمت کے گن گانے سے انسان کی روح کو سکون حاصل ہوتا ہے: ﴿بِذِكۡرِ ٱللَّهِ تَطۡمَئِنُّ ٱلۡقُلُوبُ﴾ [الرعد: ۲۸] \"سن لو، اللہ کے ذکر سے ہی دلوں کو سکون حاصل ہوتا ہے\"۔\nاور ایمان والوں کی یہ نشانی بتائی گئی ہے: ﴿ٱلَّذِينَ ءَامَنُواْ وَتَطۡمَئِنُّ قُلُوبُهُم بِذِكۡرِ ٱللَّهِۗ أَلَا بِذِكۡرِ ٱللَّهِ تَطۡمَئِنُّ ٱلۡقُلُوبُ﴾ [الرعد: ۲۸] \"جو ایمان لائے ان کے دلوں کو اللہ کے ذکر سے چین اور سکون ملتاہےسن لو،اللہ کے ذکر ہی سے دلوں کو سکون حاصل ہوتا ہے\"۔\nایک دوسری جگہ پرآیا ہے :﴿إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ وَإِذَا تُلِيَتۡ عَلَيۡهِمۡ ءَايَٰتُهُۥ زَادَتۡهُمۡ إِيمَٰنࣰ ا﴾ [الأنفال: ۲] \"ایمان والے تو وہی ہیں کہ جب اللہ کا ذکر کیاجائے تو ان کے دل کانپ اٹھتے ہیں اور جب اللہ کی آیتیں ان کوپڑھ کر سنائی جاتی ہیں، تو وہ ان کے ایمان کو اور زیادہ کرتی ہیں\"۔\n§اللہ کو یاد کرنے کا مناسب وقت :\nقرآن مجیدمیں ہے: ﴿وَٱذۡكُر رَّبَّكَ فِي نَفۡسِكَ تَضَرُّعࣰ ا وَخِيفَةࣰ وَدُونَ ٱلۡجَهۡرِ مِنَ ٱلۡقَوۡلِ بِٱلۡغُدُوِّ وَٱلۡأٓصَالِ وَلَا تَكُن مِّنَ ٱلۡغَٰفِلِينَ﴾ [الأعراف: ۲۰۵] \"اور اے شخص! اپنے رب کی یاد کیا کر اپنے دل میں عاجزی کے ساتھ اور خوف کے ساتھ اور زور کی آواز کی نسبت کم آواز کے ساتھ صبح اور شام اور اہل غفلت میں سے مت ہونا\"۔\nنماز کے بعد :\nقرآن مجیدمیں ہے: ﴿فَإِذَا قَضَيۡتُمُ ٱلصَّلَوٰةَ فَٱذۡكُرُواْ ٱللَّهَ قِيَٰمࣰ ا وَقُعُودࣰ ا وَعَلَىٰ جُنُوبِكُمۡۚ فَإِذَا ٱطۡمَأۡنَنتُمۡ فَأَقِيمُواْ ٱلصَّلَوٰةَۚ إِنَّ ٱلصَّلَوٰةَ كَانَتۡ عَلَى ٱلۡمُؤۡمِنِينَ كِتَٰبࣰ ا مَّوۡقُوتࣰ ا﴾ [النساء: ۱۰۳] \"پھر جب تم نماز ادا کر چکو تو اٹھتے بیٹھتے اور لیٹے اللہ تعالیٰ کا ذکر کرتے رہو اور جب اطمینان پاؤ تو نماز قائم کرو۔ یقیناً نماز مومنوں پر مقررہ وقتوں پر فرض ہے\"۔\n۲- قرآن کو بھی ذکر کہا گیا ہے۔ مکہ کے کافروں نے کہا :﴿أَءُنزِلَ عَلَيۡهِ ٱلذِّكۡرُ مِنۢ بَيۡنِنَاۚ بَلۡ هُمۡ فِي شَكࣲّ مِّن ذِكۡرِيۚ بَل لَّمَّا يَذُوقُواْ عَذَابِ﴾ [ص: ۸] \"کیا ہم سب میں سے صرف اس پر (محمدپر) ذکر (قرآن) نازل کیا گیا ہے۔بل کہ وہ تو میرے ذکر کے بارے میں شک میں مبتلا ہیں۔ نہیں، بل کہ انھوں نے میرا عذاب چکھا ہی نہیں\"۔\nاورفرمایا: ﴿إِنَّا نَحۡنُ نَزَّلۡنَا ٱلذِّكۡرَ وَإِنَّا لَهُۥ لَحَٰفِظُونَ﴾ [الحجر: ۹] \"بلاشبہ یہ ذکر (قرآن) ہم نے ہی اتارا ہے اور ہم ہی اس کے محافظ ہیں\"۔\nاور اللہ کا یہ وعدہ کہ ہم ہی قرآن کے محافظ ہیں آج بھی اسی طرح سچ ہے جس طرح آج سے ڈیڑھ ہزار سال (۱۵۰۰) قبل سچا تھا۔\n۲- صلاۃ(نماز)کی اقامت خود کا اللہ کا ذکر ہے: ﴿وَأَقِمِ ٱلصَّلَوٰةَ لِذِكۡرِيٓ﴾ [طه: ۱۴] \"میرے ذکر کے لیے نماز قائم کرو\"۔\nاس لیے مسلمانوں کو حکم دیا جارہا ہے کہ اللہ کا زیادہ سے زیادہ ذکر کیا کریں: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ ٱللَّهَ ذِكۡرࣰ ا كَثِيرࣰ ا وَسَبِّحُوهُ بُكۡرَةࣰ وَأَصِيلًا﴾ [الأحزاب: ۴۱-۴۲] \"اے اہل ایمان اللہ تعالیٰ کا بہت ذکر کیا کرو۔ اورصبح اور شام اس کی پاکی بیان کرتے رہو\"۔\nقرآن مجیدمیں ان لوگوں کی سخت مذمت کی گئی ہے جو اللہ کے ذکر سے غافل ہیں:﴿وَمَن يَعۡشُ عَن ذِكۡرِ ٱلرَّحۡمَٰنِ نُقَيِّضۡ لَهُۥ شَيۡطَٰنࣰ ا فَهُوَ لَهُۥ قَرِينࣱ‏﴾ [الزخرف: ۳۶] \"جو رحمن کے ذکر سے اندھا بن کر زندگی گزارے ہم اس پر ایک شیطان مقرر کردیتے ہیں، وہی اس کا ساتھی رہتا ہے\"۔\nاورفرمایا: ﴿وَمَنۡ أَعۡرَضَ عَن ذِكۡرِي فَإِنَّ لَهُۥ مَعِيشَةࣰ ضَنكࣰ ا وَنَحۡشُرُهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ أَعۡمَىٰ قَالَ رَبِّ لِمَ حَشَرۡتَنِيٓ أَعۡمَىٰ وَقَدۡ كُنتُ بَصِيرࣰ ا قَالَ كَذَٰلِكَ أَتَتۡكَ ءَايَٰتُنَا فَنَسِيتَهَاۖ وَكَذَٰلِكَ ٱلۡيَوۡمَ تُنسَىٰ﴾ [طه: ۱۲۴-۱۲۶] \"اور جو میرے ذکر سے منہ موڑے گا، اس کی زندگی تنگ ہو جائے گی اور قیامت کے دن ہم اسے اندھا اٹھائیں گے۔وہ کہےگا:اے رب! تونے مجھے اندھا کیوں اٹھایا جب کہ میں آنکھوں والا تھا؟اللہ تعالی کہے گا: اسی طرح تو دنیا میں اندھا رہا تھا۔تیرے پاس میری آیتیں آئی تھیں تو تونے ان کو بھلادیا تھا۔ اسی طرح آج تو بھلادیاجاتا ہے\"۔\n۴- نصیحت پکڑنا:\nقرآن کوتذکرہ کہاگیا ہے، جس کے معنی نصیحت کے ہیں:﴿طه مَآ أَنزَلۡنَا عَلَيۡكَ ٱلۡقُرۡءَانَ لِتَشۡقَىٰٓ إِلَّا تَذۡكِرَةࣰ لِّمَن يَخۡشَىٰ﴾ [طه: ۱-۳] \"(اے نبی!)ہم نے تم پریہ قرآن اس لیے نہیں اتارا کہ آپ مشکل میں پڑجائیں، بلکہ یہ تو ایک نصیحت ہے اس کے لیے جو اللہ سے ڈرتاہے\"۔\nاللہ تعالیٰ کا ارشادہے: ﴿أَوَلَا يَذۡكُرُ ٱلۡإِنسَٰنُ أَنَّا خَلَقۡنَٰهُ مِن قَبۡلُ وَلَمۡ يَكُ شَيۡـࣰٔ ا﴾ [مریم: ۶۷] \"کیاانسان اس بات سے نصیحت نہیں پکڑتا کہ ہم نے اسے پہلے اس حالت میں پیدا کیا کہ وہ کچھ بھی نہیں تھا\"۔\n۵- پرانی تاریخ :\nقرآن میں تاریخی واقعات کو بھی ذکر کہا گیا ہے: ﴿وَيَسۡـَٔلُونَكَ عَن ذِي ٱلۡقَرۡنَيۡنِۖ قُلۡ سَأَتۡلُواْ عَلَيۡكُم مِّنۡهُ ذِكۡرًا﴾ [الکهف: ۸۳] \"(اے محمد)، وہ تم سے ذوالقرنین کے بارے میں پوچھتے ہیں۔ کہہ دو میں تم کو اس کا کچھ ذکر کرتا (تاریخ بتاتا)ہوں\"۔\n۶- کسی چیزکو یاد رکھنا جیسے موسیٰ علیہ السلام کے ساتھ سفر میں جانے والے نوجوان نے کہا:﴿وَمَآ أَنسَىٰنِيهُ إِلَّا ٱلشَّيۡطَٰنُ أَنۡ أَذۡكُرَهُۥۚ وَٱتَّخَذَ سَبِيلَهُۥ فِي ٱلۡبَحۡرِ عَجَبࣰ ا﴾ [الکهف: ۶۳] \"شیطان نے اس کو (یعنی مچھلی کو) یاد رکھنے سے مجھے غافل کردیا اور اس نے عجیب و غریب طرح سے دریا میں اپنی راہ لی\"۔\nیہ ہیں ذکر کے کچھ معانی جن کا تذکرہ قرآن کریم میں آیا ہے۔ ان سب میں ایک بات یکساں طور پر پائی جاتی ہے کہ اللہ کی یاد اور اس کی عبادت ہی حقیقت میں ذکرہے۔ یہ سارے معانی کسی نہ کسی شکل میں اسی معنی کے طرف اشارہ کرتے ہیں۔اس لیے قرآن اورصحیح احادیث کی روشنی میں ایسی کتابیں لکھی گئی ہیں جن کوکتاب الذکر و الاذکار کہتے ہیں جن میں صبح سے لےکر شام تک کے ذکر کا بیان کیا گیا ہے۔","",{}],[289,"§ذو الکفل\nذوالکفل کا بیان قرآن میں دو بار آیا ہے۔ ایک جگہ ہے: ﴿وَإِسۡمَٰعِيلَ وَإِدۡرِيسَ وَذَا ٱلۡكِفۡلِۖ كُلࣱّ مِّنَ ٱلصَّٰبِرِينَ وَأَدۡخَلۡنَٰهُمۡ فِي رَحۡمَتِنَآۖ إِنَّهُم مِّنَ ٱلصَّٰلِحِينَ﴾ [الأنبیاء: ۸۵-۸۶] \"اور یاد کرو اسماعیل، ادریس اورذوالکفل کو۔یہ سب صابر لوگ تھے۔ ہم نے انھیں اپنی رحمت کی آغوش میں لیا۔ یہ سب لوگ نیک وصالح تھے\"۔\nدوسری جگہ ارشادباری تعالیٰ ہے:﴿وَٱذۡكُرۡ إِسۡمَٰعِيلَ وَٱلۡيَسَعَ وَذَا ٱلۡكِفۡلِۖ وَكُلࣱّ مِّنَ ٱلۡأَخۡيَارِ﴾ [ص: ۴۸] \"اور اسماعیل، یسع اورذوالکفل کو بھی یاد کرو۔ یہ سب بہترین لوگ تھے\"۔\nان میں کہیں بھی یہ نہیں بتایا گیا ہے کہ ذوالکفل کی طرف وحی کی گئی ہے۔ نہ ہی صحیح حدیثوں میں ان کے نبی ہونے کا ذکر آیا ہے،جس سے ہم یقین کے ساتھ کہہ سکیں کہ وہ بھی نبی تھے۔لیکن نبیوں کے ساتھ ان کا ذکر اشارہ کرتا ہے کہ شاید وہ بھی نبی تھے۔کچھ عالموں کا خیال ہے کہ وہ نبی نہیں بلکہ ایک متقی اور انصاف پرورشخص تھے،جو لوگوں کو ہمیشہ عدل وانصاف کا حکم دیتے تھے۔ تفسیر کے ایک بڑے امام مجاہد کا خیال ہے کہ یسع کے بعد ذوالکفل ان کے خلیفہ بنے۔\nاس کے علاوہ کچھ نہیں بتایا کہ وہ کہاں پیدا ہوے، ان کا دور کیا تھا؟ لیکن اگر ہم مجاہد کی بات کو صحیح مان لیں تو پھر یہ کہناپڑے گا کہ وہ اُردن(Jordan)میں پیداہوئے، کیونکہ یسع۔وہیں پیدا ہوئے تھے۔ان کے دور کا پورا علم نہیں ہے، مگر ایسا مانا جاتا ہے کہ وہ تقریباً ۸۳۸-۸۷۸ قبل مسیح میں تھے۔ اندازہ ہے کہ وہ ۸۷۸قبل مسیح میں خلیفہ بنے ہوں گے (ان کا تعلق بھی اُردن سے ہی رہا ہوگا)۔\nبعض علماء کےنزدیک ذوالکفل وہی ہے جنھیں بائبل میں (حزقیل) کہا گیا ہے۔لیکن دونوں کے قصے میں کوئی ایسی بات مشترک نہیں ملتی، جس سے اس خیال کی تصدیق ہوتی ہو۔اس لیے ہم جو بات یقین کے ساتھ کہہ سکتے ہیں وہ صرف یہ ہے کہ ذوالکفل ایک متقی اور انصاف پرور شخص تھے اور لوگوں کو تقوی کی تلقین کرتے تھے۔\nموجودہ دور کے کچھ نام نہادمحققین کا یہ دعوی بالکل بے بنیاد ہے کہ \"ذوالکفل\"سے مراد\"کپل وستو\"والے \"گوتم بدھ\" ہیں۔\nیہ دعویٰ اس لیے بے بنیاد ہے کہ قرآن وحدیث میں انھی انبیا ورسل کا تذکرہ کیا گیا ہے، جن کو قریش یا عرب کےلوگ جانتے تھے، کسی ہندی نبی یا رسول کو بالکل نہیں جانتے تھے۔","",{}],[290,"§ذوالقرنین\nذوالقرنین دو لفظوں سے مل کر بنا ہے۔ اس کے معنیٰ ہیں: دو سینگوں والا۔ ذوالقرنین کا بیان قرآن میں اس طرح آیا ہے:﴿وَيَسۡـَٔلُونَكَ عَن ذِي ٱلۡقَرۡنَيۡنِۖ قُلۡ سَأَتۡلُواْ عَلَيۡكُم مِّنۡهُ ذِكۡرࣰ ا إِنَّا مَكَّنَّا لَهُۥ فِي ٱلۡأَرۡضِ وَءَاتَيۡنَٰهُ مِن كُلِّ شَيۡءࣲ سَبَبࣰ ا فَأَتۡبَعَ سَبَبࣰ ا حَتَّىٰٓ إِذَا بَلَغَ مَغۡرِبَ ٱلشَّمۡسِ وَجَدَهَا تَغۡرُبُ فِي عَيۡنࣲ حَمِئَةࣲ وَوَجَدَ عِندَهَا قَوۡمࣰ اۖ قُلۡنَا يَٰذَا ٱلۡقَرۡنَيۡنِ إِمَّآ أَن تُعَذِّبَ وَإِمَّآ أَن تَتَّخِذَ فِيهِمۡ حُسۡنࣰ ا قَالَ أَمَّا مَن ظَلَمَ فَسَوۡفَ نُعَذِّبُهُۥ ثُمَّ يُرَدُّ إِلَىٰ رَبِّهِۦ فَيُعَذِّبُهُۥ عَذَابࣰ ا نُّكۡرࣰ ا وَأَمَّا مَنۡ ءَامَنَ وَعَمِلَ صَٰلِحࣰ ا فَلَهُۥ جَزَآءࣰ ٱلۡحُسۡنَىٰۖ وَسَنَقُولُ لَهُۥ مِنۡ أَمۡرِنَا يُسۡرࣰ ا ثُمَّ أَتۡبَعَ سَبَبࣰ ا حَتَّىٰٓ إِذَا بَلَغَ مَطۡلِعَ ٱلشَّمۡسِ وَجَدَهَا تَطۡلُعُ عَلَىٰ قَوۡمࣲ لَّمۡ نَجۡعَل لَّهُم مِّن دُونِهَا سِتۡرࣰ ا كَذَٰلِكَۖ وَقَدۡ أَحَطۡنَا بِمَا لَدَيۡهِ خُبۡرࣰ ا ثُمَّ أَتۡبَعَ سَبَبࣰ ا حَتَّىٰٓ إِذَا بَلَغَ بَيۡنَ ٱلسَّدَّيۡنِ وَجَدَ مِن دُونِهِمَا قَوۡمࣰ ا لَّا يَكَادُونَ يَفۡقَهُونَ قَوۡلࣰ ا قَالُواْ يَٰذَا ٱلۡقَرۡنَيۡنِ إِنَّ يَأۡجُوجَ وَمَأۡجُوجَ مُفۡسِدُونَ فِي ٱلۡأَرۡضِ فَهَلۡ نَجۡعَلُ لَكَ خَرۡجࣰ ا عَلَىٰٓ أَن تَجۡعَلَ بَيۡنَنَا وَبَيۡنَهُمۡ سَدࣰّ ا قَالَ مَا مَكَّنِّي فِيهِ رَبِّي خَيۡرࣱ فَأَعِينُونِي بِقُوَّةࣲ أَجۡعَلۡ بَيۡنَكُمۡ وَبَيۡنَهُمۡ رَدۡمࣰ ا ءَاتُونِي زُبَرَ ٱلۡحَدِيدِۖ حَتَّىٰٓ إِذَا سَاوَىٰ بَيۡنَ ٱلصَّدَفَيۡنِ قَالَ ٱنفُخُواْۖ حَتَّىٰٓ إِذَا جَعَلَهُۥ نَارࣰ ا قَالَ ءَاتُونِيٓ أُفۡرِغۡ عَلَيۡهِ قِطۡرࣰ ا فَمَا ٱسۡطَٰعُوٓاْ أَن يَظۡهَرُوهُ وَمَا ٱسۡتَطَٰعُواْ لَهُۥ نَقۡبࣰ ا قَالَ هَٰذَا رَحۡمَةࣱ مِّن رَّبِّيۖ فَإِذَا جَآءَ وَعۡدُ رَبِّي جَعَلَهُۥ دَكَّآءَۖ وَكَانَ وَعۡدُ رَبِّي حَقࣰّ ا وَتَرَكۡنَا بَعۡضَهُمۡ يَوۡمَئِذࣲ يَمُوجُ فِي بَعۡضࣲۖ وَنُفِخَ فِي ٱلصُّورِ فَجَمَعۡنَٰهُمۡ جَمۡعࣰ ا﴾ [الکهف: ۸۳-۹۹] \"(اے محمد!) وہ آپ سے ذوالقرنین کے بارے میں پوچھتے ہیں۔کہہ دیجیے:میں اس کا ذکر تم سے بیان کرتا ہوں۔ہم نے اسے زمین پر عزت بخشی تھی اور اسے ہر طرح کی چیزیں دے رکھی تھی۔تو اس نے ایک راہ اختیار کی۔یہاں تک کہ وہ سورج ڈوبنے کی جگہ پہنچا۔اس نے اسے ایک دَلدَل کے چشمے میں غرق ہوتے پایا۔ اس کے قریب اسے ایک قوم بھی ملی۔ہم نے کہا :اے ذوالقرنین! چاہے تم انھیں عذاب دو اور چاہے ان کے ساتھ نیک سلوک کرو۔اس نے کہا:ان لوگو ں میں سے جو کوئی ظلم کرے گا،اسے ہم سزا دیں گے۔پھر وہ اپنے رب کی طرف واپس کیا جائے گا تو وہ اسے سخت عذاب دے گااور جو کوئی ایمان لایا اور نیک عمل کیا اس کے لیے اچھا بدلہ ہے اور اس کے ساتھ نرمی سے پیش آئیں گے۔پھر وہ ایک دوسرے راستے کی طرف چل پڑا، یہاں تک کہ سورج طلوع ہونےکی جگہ پر جاپہنچا، تواس نے اسے ایک ایسی قوم پر طلو ع ہوتے پایا، جن کے لیے ہم نے سورج کے مقابلے میں کوئی آڑ نہیں رکھی تھی۔ایسا ہی ہم نے کیا۔اس کےپاس جو کچھ تھا اس کو ہم علم کے ذریعےسے گھیرے ہوئے تھے۔پھر اس نے ایک اور مہم کا انتظام کیا۔یہاں تک کہ جب دو پہاڑوں کے درمیان پہنچا تو اسے ان کے پرے ایک ایسی قوم ملی جو کوئی بات سمجھ ہی نہیں پاتی تھی۔انهوں نے کہا:اے ذوالقرنین!یا جوج اور ماجوج اس زمین میں فساد مچا تے ہیں۔ تو کیا ہم آپ کو کچھ مال دیں تاکہ آپ ہمارے اور ان کے درمیان ایک دیوار بنادیں۔ کہا: میرے رب نے جو کچھ میرے اختیار میں دے رکھا ہے، وہی بہتر ہے۔تم بس انسانوں کی طاقت سے میری مدد کرو۔ میں تمھارے اور ان کے درمیان ایک دیوار بنادوں گا۔مجھے لوہے کی چادریں لادو۔یہاں تک کہ جب دونوں پہاڑوں کے درمیان کی خالی جگہ کو پر کردیا تو کہا:پھونکو!یہاں تک کہ جب اسے سلگاکر آگ کردیا تو کہا:مجھے پگھلا ہوا تانبہ لادو کہ اس پر انڈیل دوں۔تو وہ (یاجوج اور ماجوج) نہ تو اس پر چڑھ کر آسکتے تھے اور نہ وہ اس میں نقب لگا سکتے تھے۔ذوالقرنین نے کہا: یہ میرے رب کی مہربانی ہے۔لیکن جب میرے رب کا وعدہ آجائےگا تو وہ اسے اٹھا کربرابر کردےگا اور میرے رب کا وعدہ سچا ہے اوراس دن ہم ان میں کچھ چھوڑ دیں گے کہ وہ ایک دوسرے کے درمیان موجوں کی طرح گھوم رہے ہوں گے اورصور میں پھونک ماری جائے گی۔توپھر ہم سب کو ایک ساتھ جمع کر لیں گے\"۔\nایسا لگتا ہے کہ ذوالقرنین نام کا کوئی شخص یہودیوں میں مشہور تھا۔نبی کا امتحان لینے کے لیے قریش مکہ نے یہودیوں کےاکسانے پرنبی اکرم صلی اللہ علیہ وسلم سےیہ سوال پوچھا۔اللہ تعالیٰ نے آپ پر وحی نازل کی اور ہزاروں سال قبل کی تاریخ کو آپ نے ان کو سنایا، جس سے آپ کا نبی ہونا ثابت ہوتا ہے۔\nذوالقرنین کون تھا؟ اس کا تاریخی زمانہ کیا تھا؟ اس کے بارے میں قرآن کریم جو کچھ بیان کرتاہے اس کا اطلاق کس پر ہوتا ہے؟ اس کے بارے میں اختلاف ہے۔مولانا سیّد ابو الاعلی مودودی کا خیال ہے کہ جس شخص میں ذوالقرنین کی خصوصیات پائی جاتی ہیں، وہ قرآن مجیدمیں مذکور ایران کا بادشاہ خورس یا خسرو یا سائرس(Syrus)ہے، جس کی موت ۵۳۹قبل مسیح میں ہوئی تھی۔\nمولانا مودودی کے اس خیال کی توثیق تاریخ سے بھی ہوتی ہے۔ذوالقرنین کا مطلب ہوتا ہے دوسینگوں والا (The two horned one)۔یہ خطاب آسانی کے ساتھ (syrus) پر چسپاں ہوتا ہے۔ کیونکہ بائبل میں دانیال(daniel)نبی کا جو خواب بیان کیا گیا ہے۔ اس میں یونانیوں کے عروج سے قبل میڈیا اور فارس (Media and Persia)کی پوری ریاست کو مینڈھے کی شکل میں دکھایا گیا ہے، جس کے دوسینگ تھے۔سائرس نے میڈیا اور فارس کی ریاستوں کو ملاکر ایک بڑی ریاست قائم کی۔یہودیوں میں اس دو سینگ والے کی بڑی چرچا تھی۔کیونکہ اسی شخص نے بابل جیسی ریاست کو ہراکر بنی اسرئیل کو اس کی قید سے چھٹکارا دلایا تھا۔\nسائرس ایک عظیم فاتح تھا۔ بائبل سے یہ بھی معلوم ہوتا ہے کہ وہ اللہ کو ماننے والا اور اللہ سے ڈرنے والا تھا۔قرآن مجیدمیں ذوالقرنین کی تیسری مہم کا تذکرہ آیا ہے؛ لیکن ابھی تک شمال یا جنوب میں سائرس کی کسی بڑی مہم کا پتا نہیں چل سکا ہے۔پھر بھی یہ کوئی ناممکن بات نہیں ہے کہ کوئی اس طرح کی بڑی مہم بھی پیش آئی ہو جب کہ تاریخ سے پتا چلتا ہے کہ سائرس کی حکومت شمال میں کاکیشیا (caucasia) تک پھیلی ہوئی تھی۔ذوالقرنین کے بارے میں قرآن مجیدمیں یہ بھی بتایا گیا ہے کہ یاجوج اور ماجوج سے بچنے کے لیے اس نےایک مضبوط دیوار کی تعمیر کرائی تھی۔یہ بات قریب قریب ثابت ہوچکی ہے کہ یاجوج اور ماجوج سے مراد روس اور شمالی چین کے وہ قبیلے ہیں، جو تاتاری، منگول، سپین اور ہن وغیرہ ناموں سے مشہور ہیں اور زمانے قدیم سے مہذب ممالک پر حملے کرکے لوٹ مار مچاتے رہے ہیں اور یہ بھی معلوم ہے کہ انھیں سے بچنے کے لیے کاکیشیا(caucasia) کے جنوبی علاقے میں دربند اور داریال کی دیواروں (Wall at derbent or darband andarial) کی تعمیر ہوئی تھی۔لیکن ابھی تک یہ بات ثابت نہیں ہوسکی ہے کہ یہ دیواریں سائرس کی ہی تعمیر کرائی ہوئی ہیں۔خلاصہ یہ کہ ممکن ہے کہ ذوالقرنین قرآن میں سائرس ہی کو کہا گیا ہو، لیکن یقینی طورسے یہ نہیں کہا جاسکتا کہ سائرس ہی ذوالقرنین تھا۔ اس کے لیےابھی کچھ اور ثبوت درکارہیں۔سائرس نے کوہ قاف کی ایک گھاٹی میں بحیرۂ قزوین (caspan sea)کےمغربی کنارے پر تیس میل طویل ایک دیوار بنوائی جس کے ذریعے سے وہ ستھین نامی قوم کےحملوں سے اپنے ملک کو بچانا چاہتا تھا۔ ایسا لگتا ہے کہ یہی وہ لوگ تھے، جن کو قرآن میں یاجوج ماجوج کہا گیا ہے۔ (مزید معلومات کے لیے دیکھیے: :یاجوج ماجوج )\nکچھ علماء کا خیال ہے کہ ذوالقرنین مقدونیا کا سکندر ہے،جو چوتھی صدی قبل مسیح ایک عظیم بادشاہ کی شکل میں ظاہر ہوا۔ دیکھتے ہی دیکھتے وہ پوری دنیا پر چھاگیا۔اس کا انتقال ۳۲۳ قبل مسیح میں ہوا۔ یہ کچھ مفسرین کا خیال ہے۔لیکن اس کو ماننے میں کئی رکاوٹیں: ہیں اول تو یہ کہ وہ کوئی ایمان والا شخص نہیں تھا، جب کہ قرآن کے بیان سے اس کے ایمان والا ہونے کا اشارہ ملتا ہے اور نہ اس نے کوئی بند بنوایا تھا۔اسی طرح سکندر کوئی رحم دل بادشاہ نہیں تھا، بلکہ وہ دوسرے حاکموں کی طرح ایک حاکم تھا جو اپنے کامیاب جنگی منصوبوں کے سبب دنیا کے بڑے حصے پر فتح حاصل کرنے میں کامیاب رہا۔اس لیے حقیقت میں یہ کوئی اور ہی فاتح ہوسکتا ہے، جس کی طرف قرآن اشارہ کرتا ہے۔قرآن کریم سے یہ بات بھی ظاہر ہوتی ہے کہ اس شخص کو یہودی اچھی طرح جانتے تھے۔اسی لیے انھوں نے نبی اکرم صلی اللہ علیہ وسلم کا امتحان لینے کے لیے اس کے بارے میں سوال کیا اور وحی کے ذریعے سے جواب سن کر حیرت زدہ ہوگئے۔جب ہم ایران کے سائرس کے بارے میں پڑھتے ہیں تو ایسا معلوم ہوتا ہے کہ یہی ذوالقرنین ہے۔ کیونکہ وہ یہودیوں کے لیے بہت رحم دل تھا۔اس کے ذریعے سے یہودیوں کو بہت فائدہ ہو ا۔اسی کی کوششوں سے یہودی بابل کی قید سے آزاد ہوئے اور دوبارہ فلسطین واپس آئے اور وہاں اپنے آپ کو دوبارہ اکٹھا کرنے لگے۔لیکن یہ بات ضرورکہی جاسکتی ہےکہ جس ذوالقرنین کا بیان قرآن مجیدمیں آیا ہے اور جو کچھ اس کے بارے میں قرآن میں ذکر ہوا ہے، ابھی بہت کچھ تاریخ کے صفحات میں چھپا ہوا ہے۔اب مستقبل ہی میں آثار قدیمہ کے ذریعے سے ان چھپے صفحات پر روشنی ڈالی جا سکے گی۔ سائرس کے بارے میں مولانا ابوالکلام آزاد نے جو تحقیق کی ہے وہ بہت اہم ہے۔ (دیکھیے :ترجمان القرآن:۲:۴۳۱ـ۴۵۰)\nمولاناآزاد نے یونیورسل ہسٹری آف دی ورلڈکی مددسے سائرس کےذریعے سے فتح کیے گئے ممالک کاخاکہ بھی تیار کیا ہے۔","",{}],[291,"§ذئب\nذئب کے معنی بھیڑیا کے ہیں۔یہ ایک درندہ(چیرپھاڑ کرنے والاجانور)ہے، جو اپنے شکار کی چیر پھاڑ کےلیے مشہور ہے۔اس لیے لوٹ مار کرنے والے اور ظالم لوگوں کی مثال بھیڑیے سے دی جاتی ہے۔ بائبل کے مطابق یعقوب علیہ السلام نے اپنی موت سے قبل اپنی اولاد کو جمع کیا اور ہر ایک کو خاص طور سے بتایا کہ آخری دنوں میں ان پر کیا گزرے گی۔بنیامین، جو یوسف علیہ السلام کے چھوٹے بھائی تھے کے بارے میں بتایا۔بنیامین پھاڑنے والا بھیڑیا ہے۔ وہ صبح کو شکار کھائے گا اور شام کو لوٹ کا مال تقسیم کرےگا۔ (ملاحظہ فرمائیں : پیدائش :۴۹ :۲۷)\nیہاں بنیامین سے مطلب ان کی اولاد ہے۔اس لیے خود بائبل سے پتا چلتا ہے کہ جب بنی اسرائیل آپس میں لڑ پڑے تو بنیامین کی اولاد نے غبہ سے نکل کر اسی دن ۲۲ہزار اسرائیلی مردوں کوقتل کر کے مٹی میں ملا دیا۔ (ملاحظہ فرمائیں :انصاف:ا۲:۲۰)\nقرآن مجید کی سورہ یوسف میں بھیڑیا کے لفظ کا تین بار استعمال ہوا ہے۔جو یوسف علیہ السلام کے بارے میں ہے۔\nپہلی بار: اس وقت اس لفظ کا استعمال ہوا ہے جب یوسف کے بھائیوں نے اپنے باپ سے کہا: ﴿أَرۡسِلۡهُ مَعَنَا غَدࣰ ا يَرۡتَعۡ وَيَلۡعَبۡ وَإِنَّا لَهُۥ لَحَٰفِظُونَ قَالَ إِنِّي لَيَحۡزُنُنِيٓ أَن تَذۡهَبُواْ بِهِۦ وَأَخَافُ أَن يَأۡكُلَهُ ٱلذِّئۡبُ وَأَنتُمۡ عَنۡهُ غَٰفِلُونَ﴾ [یوسف: ۱۲-۱۳] \"ہمارے ساتھ کل اسے بھیج دیجیے کہ گھوم پھر لے اور کھیل لےاور اس کی حفاظت کےلیے تو ہم ہیں ہی۔اس (یعقوب)نے کہا:یہ بات مجھے تکلیف دے رہی ہے کہ تم اسے لے جاؤ۔ مجھے خوف ہے کہیں ایسا نہ ہو کہ تم اس کا دھیان نہ رکھ سکواور بھیڑیا اسے کہاجائے\"۔\nدوسری بار: ﴿قَالُواْ لَئِنۡ أَكَلَهُ ٱلذِّئۡبُ وَنَحۡنُ عُصۡبَةٌ إِنَّآ إِذࣰ ا لَّخَٰسِرُونَ فَلَمَّا ذَهَبُواْ بِهِۦ وَأَجۡمَعُوٓاْ أَن يَجۡعَلُوهُ فِي غَيَٰبَتِ ٱلۡجُبِّۚ وَأَوۡحَيۡنَآ إِلَيۡهِ لَتُنَبِّئَنَّهُم بِأَمۡرِهِمۡ هَٰذَا وَهُمۡ لَا يَشۡعُرُونَ﴾ [یوسف: ۱۴-۱۵] \"وہ {برادران یوسف}بولے:ہمارے ایک جتھے کے ہوتے ہوےاسے بھیڑیا کھاجائے تو ضرور ہی ہم سب کچھ گنوادینے والے ہیں۔پھر جب وہ لوگ اسے لے گئے او ر اس بات پر متفق ہوگئے کہ اسے ایک گہرے کنویں کی تہ میں ڈال دیں تو ہم نے اسے وحی کے ذریعے سے متنبہ کردیا کہ(گھبرا مت)ایک وقت آئے گا کہ تو انھیں ان کی یہ بات بتائے گا اور انھیں کچھ بھی خبر نہیں ہوگی\"۔\nتیسری بار: ﴿وَجَآءُوٓ أَبَاهُمۡ عِشَآءࣰ يَبۡكُونَ قَالُواْ يَٰٓأَبَانَآ إِنَّا ذَهَبۡنَا نَسۡتَبِقُ وَتَرَكۡنَا يُوسُفَ عِندَ مَتَٰعِنَا فَأَكَلَهُ ٱلذِّئۡبُۖ وَمَآ أَنتَ بِمُؤۡمِنࣲ لَّنَا وَلَوۡ كُنَّا صَٰدِقِينَ﴾ [یوسف: ۱۶-۱۷] \"اندھیرا ہوجانے پر وہ روتے ہوے اپنے باپ کے پاس آئے اور کہنے لگے: اے ہمارے باپ! ہم دوڑکے مقابلے میں لگ گئے اور یوسف کو اپنے سامان کے پاس چھوڑ دیا۔ اسی دوران بھیڑیا نے آکر اسے کھا لیا، آپ تو ہمارا یقین نہیں کریں گے، چاہے ہم سچے ہی کیوں نہ ہو\"۔(مزید معلومات کےلیےیوسف علیہ السلام کا قصہ ملاحظہ فرمائیں )","",{}],[292,"§راوی\nحدیثوں کے بیان کرنے والے کو راوی کہا جاتا ہے۔ اور انھی راویوں کی جانچ پڑتال کے بعد حدیث پر صحیح یا ضعیف کا حکم لگایا جاتاہے۔کیونکہ سورہ الحجرات کی آیت ۶میں ہمیں یہی حکم دیا گیا ہے کہ اگر تمھارے پاس کوئی فاسق کوئی خبر لے کر آئے تو اس کی چھان بین کر لو۔ویسے صحیح اورضعیف کا حکم لگاتے ہوےاور بھی بہت ساری باتیں دیکھنی پڑتی ہیں۔ تاہم راوی کا صادق القول (سچا) ہونا حدیث کےصحیح ہونے کےلیے لازم ہے۔ کسی جھوٹے راوی کی حدیث کبھی صحیح نہیں ہوسکتی۔راوی کے سچے اورجھوٹے ہونے کےبھی بہت سارے درجات ہیں۔جن کو حدیث کے عظیم اسکالر حافظ ابن حجر (۸۵۲ھ) نے بارہ درجوں میں تقسیم کیاہے۔ یہاں ان کو اس لیے بیان کیا جارہا ہے کہ اس بات کا اندازہ ہو جائے کہ حدیثوں کی جانچ پڑتال میں کتنے دشوار مراحل سے گزرنا پڑا ہے۔\n§راویوں کے بارہ درجے:\nپہلا درجہ: جب راوی کا صحابی ہونا ثابت ہوجائے تو اس کے بارے میں جانچ پڑتال کی ضرورت نہیں ہے۔ کیونکہ ہمارا یقین ہے کہ سارے صحابی سچے (ثقہ اورعادل)تھے،جس کا ثبوت خود قرآن اور صحیح حدیثوں میں پایا جاتا ہے۔\nدوسرا درجہ: اس درجہ کے راوی کے سچا (ثقہ اورعادل)ہونے کے لیےتوثیق کے اعلیٰ ترین الفاظ کا استعمال کیا جائے۔ یا راوی سچا بھی ہو اور اس کی یاد داشت(قوت حافظہ) بھی مضبوط ہو، جیسے کہاجائے کہ وہ تو بہت سچا راوی ہے۔ یا یہ کہا جائے کہ وہ سچا ہے، سچا۔\nتیسرا درجہ:یہ وہ درجہ ہے،جس میں روایت کرنے والا شخص سچا تو ضرور ہے، لیکن اس کی یاد داشت(حافظہ) پہلے والے سے ذرا کم ہو۔ اس کے لیے صرف ایک لفظ کا استعمال ہوگا۔ جیسے: وہ سچا ہے، یاد کرنے والا ہے، ٹھیک ہے وغیرہ۔\nچوتھا درجہ:یہ وہ درجہ ہے جس میں راوی کی قوت حافظہ تیسرے درجے سے کچھ کم ہو۔ اس کے لیے صدوق لفظ کا استعمال کرتے ہیں۔ یا یہ کہتے ہیں کہ اس میں کوئی حرج نہیں۔\nپانچواں درجہ:یہ وہ درجہ ہے جس میں راوی کی قوت حافظہ چوتھےدرجے سے بھی کم ہو۔ اس کے لیے لفظ صدوق کے ساتھ یہ بڑھا دیتے ہیں کہ اس کی قوت حافظہ کمزور ہے۔ یا اس کو حدیث روایت کرنے میں کچھ التباس ہوجاتا ہے۔ یا وہ آخر میں ملتبس ہوگیا۔ یاوہ دین میں صحیح راستوں کر ترک کر کے بدعت میں پڑگیا۔(بدعت کیا ہے؟ تفصیل کے لیے دیکھیے : بدعت)\nچھٹا درجہ:یہ وہ درجہ ہے جس میں راوی کی حدیثیں بہت کم ہوں۔لیکن اس کے متعلق ہمارے پاس کوئی ایسا علم نہیں ہے،جس کی وجہ سے اس کی حدیثوں کو چھوڑ دیا جائے تو اس کے لیےمقبول لفظ کا استعمال کیا جاتا ہے۔ایسے راوی کو قبول تو کرلیں گے لیکن ضروری ہے کہ اس کے علاوہ کوئی دوسرا راوی بھی اس حدیث کوبیان کرنے والا ہو۔اگر ایسا نہیں ہے تویہ راوی بھی مقبول نہیں اور اس کی حدیث صحیح اور ضعیف کے درمیان کی ہوگی۔ حدیثوں کے گہرے علم رکھنے والے ہی اس کے متعلق کوئی (درست) فیصلہ کرسکتے ہیں۔یہ چھے درجات ہیں، جن کی حدیثیں قبول کی جائیں گی۔ لیکن ان میں ابتدائی تین درجوں کی احادیث کو صحیح اور بعد کے تین درجوں کی احادیث کو حسن کہا جائے گا۔\nباقی چھے درجات کے راویوں کی احادیث کو ضعیف کہا جائے گا۔ پھرضعیف حدیث کے بھی درجات ہیں۔ جیسے: ضعیف، ضعیف جدا، موضوع، منکر وغیرہ۔\nاس طرح راویوں کی گہری چھان بین کرنے کے بعد ہی ان پر حکم لگایا جاتا ہے۔ یہ بہت مشکل کام ہے لیکن اللہ نے ہر زمانے میں ایسے علماء پیدا کیے جو احادیث کو پرکھنے کی پوری صلاحیت رکھتے تھے۔یہاں ایک قصہ بیان کیا جارہا ہے، جس کے پڑھنے سے یہ معلوم ہوجائے گا کہ یہ محدث کس پائے کے ہوتے تھے۔\nخلیفہ ہارون رشید نے ایک زندیق کو قتل کرنے کا حکم دیا۔ اس نے کہا: اے امیر المومنین! آپ نے مجھے قتل کرنے کا حکم کیوں دیا۔ خلیفہ نے کہا: تاکہ اللہ کے بندوں کو تمھارے ذلیل کا م سے بچا سکوں۔ اس نے کہا: آپ کیسے بچائیں گے، جب کہ میں نے ایک ہزار حدیثیں اپنی طرف سے گھڑ کر لوگوں میں پھیلا دی ہیں۔ خلیفہ نے کہا: اے اللہ کے دشمن!تو ابواسحاق فزاری اور عبداللہ بن مبارک جیسے حدیث کے عالموں کا کیا مقابلہ کر سکے گا۔ جو ایک ایک لفظ کو چھلنی میں چھان کر صاف کردیں گے۔تیری گھڑی ہوئی حدیثوں کو دیکھ کر وہ بتا دیں گے کہ یہ موضوع ہیں۔(دیکھیے: تاریخ دمشق۷۱۲۷)\nاس سے قبل بتایا جا چکا ہے کہ راویوں کی تعداد پانچ لاکھ تک پہنچتی ہے، جن کی زندگی اور سیرت (صفات، عادات واطوار) کو جاننے کے لیے تین قسم کی کتابیں لکھی گئیں:\n۱- وہ کتابیں جو ثقہ(سچے) راویوں کے متعلق ہیں۔ جیسے: الثقات:تالیف عجلی(۲۶۱ھ)، الثقات:تالیف ابن حبان (۳۵۴ھ)، الثقات:تالیف ابن شاہین(۳۸۵ھ)۔\n۲- وہ کتابیں، جو ضعیف راویوں کے متعلق لکھی گئیں۔ ان کے نام یہ ہیں : الضعفاء الکبیر:تالیف بخاری (۲۵۶ھ)، احوال الرجال:تالیف جوزجانی(۲۵۹ھ)،الضعفاء والمتروکین:تالیف نسائی(۳۰۳ھ)،الضعفاء الکبیر: تالیف عقیلی (۳۲۲ھ)، معرفۃ المجروحین:تالیف ابن حبان(۳۵۴ھ)، الکامل فی الضعفاء:تالیف ابن عدی (۳۶۵ھ)۔\n۳- وہ کتابیں جو ثقات اور ضعفاء ہر دو طرح کے راویوں کی زندگی اور عادات و اطوار پرمشتمل ہیں۔ وہ یہ ہیں: الطبقات الکبریٰ:تالیف ابن سعد (۲۳۰ھ)، التاریخ الکبیر:تالیفبخاری( ۲۵۶ھ)،التاریخ الکبیر: تالیفابن ابی خیثمہ (۲۷۹ھ)،الجرح و التعدیل:تالیف ابن ابی حاتم رازی (۳۲۷ھ)، تہذیب الکمال فی اسماء الرجال:تالیف جمال الدین مزّی،(۷۵۲ھ)۔ اس کتاب میں آٹھ ہزار لوگوں کی سیرت ہے جو چونتیس جلدوں میں چھپی ہے۔\nتہذیب التہذیب :تالیف حافظ ابن حجر(۸۵۲ھ)۔ یہ حقیقت میں مزی کی کتاب تہذیب الکمال کا اختصار ہے، جو بارہ جلدوں میں چھپی ہے۔ جس میں مؤلف نے اپنی آرا کو بھی شامل کردیا ہے اور چونکہ حافظ ابن حجر حدیث کے عظیم عالم مانے جاتے ہیں، اسی لیے ان کی آرا کی بڑی اہمیت ہے۔\nتقریب التہذیب:تالیف حافظ ابن حجر (۸۵۲ھ)،یہ تہذیب التہذیب کا خلاصہ ہے، جس میں مؤلف نے ایک یا دو لفظوں میں راوی کےدرجے کو بتایا ہے، جس کی وجہ سے حدیث پر کام کرنے والے کو بڑی آسانی ہوگئی ہے۔\nان کتابوں کے علاوہ اور بھی مختلف اقسام کی کتابیں لکھی گئی ہیں، جن میں حدیث بیان کرنے والے راویوں کی سیرتیں ہیں۔یہ مشہور کتابیں وہ ہیں جو شہروں یا ملکوں کے ناموں سے موسوم ہیں۔ جیسے: تاریخ بغداد، تاریخ اصفہان، تاریخ نیشاپور، تاریخ دمشق، تاریخ مصر، تاریخ ہندوسندھ وغیرہ۔\n§راویوں کی جرح وتعدیل کرنے والے علماء:\nراویوں کی تحقیق کرنے والے (ان پر جرح وتعدیل کرنے والے) عالموں کی تعداد تقریباً پانچ سوہے، جن کی کا وشوں اور اقوال ہی کی بنیاد پر یہ کتابیں معرض وجود میں آئی ہیں۔ ان علماء میں مشہور یہ ہیں:\nعبدالرحمن اوزاعی(۱۵۸ھ)،شعبہ بن حجاج (۱۶۰ھ)، سفیان بن سعیدثوری (۱۶۱ھ)، مالک بن انس(۱۷۹ھ)، عبداللہ بن مبارک (۱۸۱ھ)،سفیان بن عیینہ(۱۹۷ھ)، یحیی بن سعیدالقطان (۱۹۸ھ)، یحیی بن مَعین(۲۳۳ھ)، احمد بن حنبل(۲۴۱ھ)، محمدبن اسماعیل بخاری(۲۵۶ھ)،مسلم بن الحجاج (۲۶۱ھ)، ابوزرعہ رازی (۲۶۴ھ)،ابو حاتم رازی (۲۷۷ھ)،احمدبن شعیب نسائی (۳۰۳ھ)، ابوجعفرمحمد بن عمروعقیلی (۳۲۲ھ)ابوالحسن علی بن عمردارقطنی (۳۸۵ھ)وغير ہ۔\nدرحقیقت علم حدیث انتہائی وسیع اور مبسوط موضوع ہے۔ کئی صدیوں میں کوئی ایک محدث پیدا ہوتاہے، جو اپنی سخت کدوکاوش سے اس علم کو دوبارہ زندگی بخشتا ہے۔","",{}],[293,"§ربا\nرباسودکوکہتے ہیں۔یہ ایک معاشرتی برائی بل کہ بیماری ہے، جو کینسر کی طرح پھیلتی ہے۔یہ بیماری جس معاشرے میں پھیل جاتی ہے، اس کے زندہ رہنے کی صلاحیت کم سے کم ترہوتی چلی جاتی ہے۔ اسی لیے قدیم زمانےمیں بعض قومیں اپنے دشمنوں کے لیے اس کا استعمال کرتی تھیں، جب کہ خود اپنے اوپر اسے حرام کیےہوے تھیں۔ بائبل میں اس کو اپنے لوگوں کے لیے حرام کیا گیا ہے:\n\"اگر تو میری رعایا میں سے کسی محتاج کو جو تیرے پاس رہتا ہو، کچھ قرض دے تو اس سے قرض خواہ کی طرح سلوک نہ کرنااور نہ اس سے سود لینا\"۔(خروج:۲۵:۲۲)\nجو کوئی روپے سود پر نہیں دیتا اور معصوم لوگوں کو نقصان پہنچانے کے لیے رشوت نہیں لیتا۔ جو کوئی ایساکرتا ہے وہ کبھی نہ ڈگمگائے گا۔(استثناء:۵:۱۵)\n\"نحیمیاہ\" نے یہودیوں کو پھٹکارا جو اپنے بھائیوں سے سود لیتے تھے۔(نحمیاہ:۱۲ـ۶:۵)\nجہاں بائبل نے یہودیوں کو آپس میں سود لینے سے روکا ہے، وہیں غیر یہودیوں سے سود لینا صحیح اور جائز بتایا ہے:\n\"اپنے کسی بھائی کو سود پر قرض نہ دینا، چاہے روپیہ ہو، چاہے خوردنی اشیا ہو، چاہے کچھ اور جو چیز سود پر دی جاتی ہے اسے سود پر نہ دینا۔ تو غیر قوم کو سود پر قرض تو دے، لیکن اپنے کسی بھائی سے ایسا نہ کرنا\"۔(استثناء:۲۰ـ۱۹:۲۳)\nحقیقت تو یہ ہے کہ یہودیوں کو بھی سود کھانے سے روکا گیاتھا۔ لیکن انھوں نے ایسا نہ کیا، بلکہ سود کھاتے رہے۔ پہلے غیر یہودیوں سے کھایا۔ پھر آپس میں بھی کھانے لگے، جس کے پاداش میں اللہ تعالیٰ نے بہت ساری حلال چیزیں بھی ان پر حرام کردیں:﴿فَبِظُلۡمࣲ مِّنَ ٱلَّذِينَ هَادُواْ حَرَّمۡنَا عَلَيۡهِمۡ طَيِّبَٰتٍ أُحِلَّتۡ لَهُمۡ وَبِصَدِّهِمۡ عَن سَبِيلِ ٱللَّهِ كَثِيرࣰ ا وَأَخۡذِهِمُ ٱلرِّبَوٰاْ وَقَدۡ نُهُواْ عَنۡهُ وَأَكۡلِهِمۡ أَمۡوَٰلَ ٱلنَّاسِ بِٱلۡبَٰطِلِۚ وَأَعۡتَدۡنَا لِلۡكَٰفِرِينَ مِنۡهُمۡ عَذَابًا أَلِيمࣰ ا﴾ [النساء: ۱۶۰-۱۶۱] \"یہودیوں کے ظلم اور اللہ تعالیٰ کی راہ سے اکثر لوگوں کو روکنے کے باعث جوپاکیزہ چیزیں ان کے لیے حلال کی گئی تھیں، وہ ہم نےان پر حرام کردیں اور اس وجہ سے بھی کہ سود جس سے منع کیا گیا تھا، اسے لیتے تھے اور لوگوں کا مال ناحق مار کھاتے تھے اور ان میں جو کافر ہیں، ہم نے ان کے لیے المناک عذاب تیارکر رکھا ہے\"۔\nرہااسلام تو اس نے سود خوری کو ہمیشہ کے لیے حرام قراردیا، خواہ وہ مسلمانوں کے درمیان ہو، خواہ کسی مسلم اورغیرمسلم کے درمیان۔کیونکہ اسلام ایک ایسے معاشرے کو قائم کرنا چاہتا ہے، جس میں آپس میں ہمدردی اورباہمی تعاون کا جذبہ پایا جائے، جب کہ سود کوبڑھاوا دینے کا مطلب معاشرے میں نفرت اوردشمنی کو بڑھاوا دینا ہے۔سودلینے والا،سوددینےوالوں کی مجبوری سے فائدہ اٹھاتا ہے اور ان کی بے کسی کو اپنی کمائی کا ذریعہ بناتا ہے۔ بلکہ ایک بار کسی غریب کو سودی قرض دے کر اس کو ہمیشہ کے لیے اپنا غلام بنا لیتا ہے۔ کیونکہ سودمرکب (Compound Interest) ایک ایسا نظام ہے،جس کے چنگل میں ایک بار کوئی غریب پھنس جائے تو پھر وہ کبھی نہیں نکل سکتا۔ آخر ایسے معاشرے میں ہمدردی اور محبت و شفقت کے جذبات کیسے پیدا ہوسکتے ہیں۔اس لیےقرآن نے سود خوروں کی سخت مذمت کی ہے:﴿ٱلَّذِينَ يَأۡكُلُونَ ٱلرِّبَوٰاْ لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ ٱلَّذِي يَتَخَبَّطُهُ ٱلشَّيۡطَٰنُ مِنَ ٱلۡمَسِّۚ ذَٰلِكَ بِأَنَّهُمۡ قَالُوٓاْ إِنَّمَا ٱلۡبَيۡعُ مِثۡلُ ٱلرِّبَوٰاْۗ وَأَحَلَّ ٱللَّهُ ٱلۡبَيۡعَ وَحَرَّمَ ٱلرِّبَوٰاْۚ﴾ [البقرة: ۲۷۵] \"جولوگ سود کھاتے ہیں، وہ اس طرح اٹھیں گے جیسےوہ شخص اٹھتا ہے،جس کوشیطان نے چھوکرپاگل کردیا ہو۔یہ اس لیے ہوگاکہ انھوں نےکہا:تجارت بھی تو سود کی طرح ہے جب کہ اللہ نے تجارت کوحلال کیا اور سودکو حرام\"۔\nسود کھانے والے قیامت کے دن پاگلوں کی طرح اٹھیں گے اور دنیامیں بھی حرام کی اس کمائی میں وہ کسی پاگل سے کم نہیں ہوں گے، جو ہر وقت غریبوں کا خون چوسنے کی کوشش میں رہتے ہیں۔ اس لیے قرآن مومنوں کو مخاطب کرتے ہوے صاف اعلان کرتا ہے:﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَذَرُواْ مَا بَقِيَ مِنَ ٱلرِّبَوٰٓاْ إِن كُنتُم مُّؤۡمِنِينَ فَإِن لَّمۡ تَفۡعَلُواْ فَأۡذَنُواْ بِحَرۡبࣲ مِّنَ ٱللَّهِ وَرَسُولِهِۦۖ وَإِن تُبۡتُمۡ فَلَكُمۡ رُءُوسُ أَمۡوَٰلِكُمۡ لَا تَظۡلِمُونَ وَلَا تُظۡلَمُونَ﴾ [البقرة: ۲۷۸-۲۷۹] \"اے ایمان والو! اللہ تعالی سے ڈرو اور جو سود باقی رہ گیاہے اسے چھوڑدو۔ اگر تم سچے ایمان والے ہو۔ اگرتم نے ایسا نہ کیا تو اللہ اوراس کے رسول سے جنگ کے لیے تیار ہوجاؤاور اگر معافی مانگ لوتو اپنا اصل زر لینے کا تمھیں حق ہے تاکہ نہ تم کسی پر ظلم کرو اور نہ تم پر ظلم کیا جائے\"۔\nقرض دینے والے کوچاہیے کہ جتنا قرض دیا ہے، وہ واپس لے لے اور اس پر سود لینے سے توبہ کرلے۔اگر ایسا کر لیتا ہے تو نہ اس پرظلم ہوگا اور نہ قرض لینے والے پر۔ لیکن اگر وہ ایسا نہیں کرتا ہے، بلکہ سود لینے پر بضد رہتا ہے تو پھر وہ اللہ اور اس کے رسول سے جنگ کرتا ہے اور اللہ اور اس کے رسول سے جنگ کرنےوالا دنیااورآخرت میں کبھی کامیاب نہیں ہوسکتا۔دنیا میں وہ پاگلوں کی طرح زندگی گزارےگا،جس کو شیطان نے چھو لیاہو۔ یہ بھی ہو سکتا ہے کہ اس کا مال ایک جھٹکے میں ختم ہوجائے۔ کوئی ایسی مصیبت آجائے جس سے پورا مال ختم ہوجائے، جیسا کہ سود کھانے والوں کو دیکھا گیا ہے۔ قیامت میں ان کے ساتھ جو ہونے والا ہے، وہ اس سے الگ ہے۔\nاس کے برخلاف صدقہ ہے،جس کے بارے میں قرآن کریم میں آیا ہے:﴿يَمۡحَقُ ٱللَّهُ ٱلرِّبَوٰاْ وَيُرۡبِي ٱلصَّدَقَٰتِۗ﴾ [البقرة: ۲۷۶] \"اللہ تعالی سود کو مٹاتا اور صدقہ وزکاۃ کو بڑھاتا ہے\"۔\nقرآن کریم کی نظر میں سود ہر حال میں نقصان دہ ہے۔ اس کے ذریعے سےکسی بھلائی کی امید نہیں کی جاسکتی۔ اس کی تائید اب مغرب کے ماہرین معاشیات بھی کرنے لگے ہیں۔ ان کی بہت بڑی تعداد اسلامی معاشی نظام کو جاننے کی طرف متوجہ ہوگئی ہے۔\nقرآن مجیدمیں ایک دوسرے مقام پرآیا ہے: ﴿وَمَآ ءَاتَيۡتُم مِّن رِّبࣰ ا لِّيَرۡبُوَاْ فِيٓ أَمۡوَٰلِ ٱلنَّاسِ فَلَا يَرۡبُواْ عِندَ ٱللَّهِۖ وَمَآ ءَاتَيۡتُم مِّن زَكَوٰةࣲ تُرِيدُونَ وَجۡهَ ٱللَّهِ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُضۡعِفُونَ﴾ [الروم: ۳۹] \"جو سود تم دیتے ہو، تاکہ لوگوں کے اموال میں شامل ہوکر بڑھ جائے تو،اللہ کے یہاں نہیں بڑھتا اور جو زکاةتم اللہ کی خوشنودی حاصل کرنے کےلیے دیتے ہوتو ایسے ہی لوگ ہیں اپنا مال بڑھانے والے\"۔\nسود سے مال میں اضافہ نہیں ہوتا۔ بلکہ جس دولت میں سود مل جائے اس سے اس کی خیرو برکت اٹھ جاتی ہے۔ اس کے برعکس زکاة ہےجس کے دینے سے دولت میں کمی نہیں آتی۔ بلکہ اللہ کی جانب سے اس میں بر کت ہوتی اور زکاۃدینے والے کامال بڑھتا ہی رہتا ہے۔یہ تو دنیا کی بات ہے ا ور آخرت میں اس کے بدلے کیا کچھ ملنے والا ہے ہم اس کا تصور بھی نہیں کرسکتے۔\nسودکی دو قسمیں ہیں:\n۱- \"ربانسیئہ\" جسےسود مرکب کہتے ہیں۔قرض پر لیا جانے والا سود۔جیسے ایک ہزار روپے قرض دے کر ایک ماہ بعد ایک ہزار ا یک سو روپے لیے جائیں۔موجودہ دور میں بیشتر سود \"ربانسیئہ\"ہے، کیونکہ اس سود میں وقت کی بہت اہمیت ہوتی ہے۔جتنازیادہ وقت گزرےگا،اسی حساب سے سود بڑھتا جائےگا۔کبھی سود کےاوپر بھی سود لگ جاتا ہے، جس کے بارے میں قرآن کریم کہتا ہے: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَأۡكُلُواْ ٱلرِّبَوٰٓاْ أَضۡعَٰفࣰ ا مُّضَٰعَفَةࣰۖ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ﴾ [آل عمران: ۱۳۰] \"اے ایمان والو!بڑھا چڑھا کر سود مت کھاؤ،اللہ سے ڈرو،تاکہ تمھیں کامرانی نصیب ہو\"۔\nسودی کاروبارمیں ہوتا یہ ہے کہ قرض لینے والا اگر وقت پر قرض واپس نہیں کرپاتا ہے تو ساہوکار اسے کچھ اور وقت دے دیتا ہے، لیکن اس کے بدلے سودکی شرح بڑھا دیتا ہے۔پھر جتنا وقت گزرتا جاتا ہے سود کی شرح بڑھتی جاتی ہے۔یہاں تک کہ چھوٹی سی اصل رقم بڑھ کر کہیں سے کہیں پہنچ جاتی ہے، جس کو واپس کرنا کسی غریب کے لیے نا ممکن ہوجاتا ہے۔ یہاں تک کہ اس کا گھر بار سب کچھ فروخت ہوجاتا ہے۔اس کے پاس نہ رہنے کےلیے گھر ہوتا ہے، نہ کھانے کےلیے کچھ،نہ پہننے کےلیے،کیونکہ یہ سب ساہوکار کا ہوجاتا ہے۔اس حالت کو قرآن نے \"اضعافاً مضاعفہ\" کہا ہے،جس کے معنی بڑھا بڑھا کر لیناہے۔ \"ربا نسیئہ\"میں سب سے زیادہ اہمیت وقت کی ہے، جس کی وجہ سے سود بڑهتےبڑهتے کہیں سے کہیں پہنچ جاتا ہے۔ایسے ساہوکاروں کو متنبہ کیا گیاہےکہ اللہ سے ڈرو۔اس کے بعد کی آیات میں بتایا گیاہے:﴿وَٱتَّقُواْ ٱلنَّارَ ٱلَّتِيٓ أُعِدَّتۡ لِلۡكَٰفِرِينَ﴾ [آل عمران: ۱۳۱] \"اس آگ سے ڈرو جو کفر کرنے والوں کےلیے تیار کی گئی ہے\"۔\nآدمی اگر سود سے نہیں رکتاتو یہ براکام اس کو کفر تک پہنچا سکتاہے۔کیونکہ ایسا کرنا حقیقت میں اللہ اور رسول سے جنگ کرنے کے مترادف ہے۔ مختصراً یہ کہ ربا نسیئہ میں وقت کی اہمیت ہوتی ہے اور وقت کے حساب سے سود میں اضافہ ہوتاہے۔اس لیے کسی قرض سے اگر وقت اور سود کی شرح نکال دی جائے تو وہ صرف قرض رہ جائے گا۔قرض کو واپس کرتے وقت اگر لینے والے نے اپنی جانب سے کچھ بڑھا کےدے دیا تو وہ سود نہیں ہوگا، بل کہ ایسے شخص کی تو تعریف کی گئی ہے۔\n۲- دوسری قسم کے سود کو \" فضل ربا\"کہتے ہیں۔اس کے معنی کسی چیز کو بدلنے کی حالت میں زیادہ دینے کے ہیں۔فضل کے معنی ہیں:زیادہ۔\nایک صحیح حدیث میں آیا ہےکہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «الذَّهَبُ بِالذَّهَبِ وَالْفِضَّةُ بِالْفِضَّةِ وَالْبُرُّ بِالْبُرِّ وَالشَّعِيرُ بِالشَّعِيرِ وَالتَّمْرُ بِالتَّمْرِ وَالْمِلْحُ بِالْمِلْحِ مِثْلا بِمِثْلٍ سَوَاءً بِسَوَاءٍ يَدًا بِيَدٍ فَإِذَا اخْتَلَفَتْ هَذِهِ الأَصْنَافُ فَبِيعُوا کَيْفَ شِئْتُمْ إِذَا کَانَ يَدًا بِيَدٍ». (صحیح مسلم: ۱۵۸۷/۸۱ بروایت عبادہ بن صامت رضی اللہ عنہ ) \"سونے کو سونے کے بدلے میں فروخت کرو اور چاندی کو چاندی کے بدلے اور گیہوں کو گیہوں کے بدلے اور جو کو جو کے بدلے اور کھجورکو کھجور کے بدلے اور نمک کو نمک کے بدلے، جو ایک دوسرے کے برابر ہوں اورہاتھ کے ہاتھ ہوں۔ہاں یہ اشیا اگر بدل کر فروخت کرنی ہوں تو جیسے چاہو ویسے (بڑھا کر) فروخت کرو۔اگر ہاتھ کے ہاتھ ہوں\"۔قرض نہیں بل کہ نقد۔اسی طرح کی اور بھی بہت سی صحیح احادیث ہیں جن سے مندرجہ ذیل باتوں کی واقفیت ہوتی ہے:\n۱- یہ اشیا تین اقسام کی ہیں :\nاوّل :سونا، چاندی\nدوم :اناج\nسوم :مسالہ\nیہ تین اقسام کی اشیا ہیں، جن سے انسان کی خاص ضرورتیں پوری ہوتی ہیں۔اسلام نے ان کی خرید و فروخت میں اس بات کا خیال رکھا ہے کہ کہیں ان میں بھی سودکا کوئی پہلونہ نکل آئے۔ اس لیے ان کو فروخت کرنے کےلیے دو شرطیں لگائیں:ایک یہ کہ ان کو برابربرابرہم وزن فروخت کیا جائے۔ ایک کلو سونا یا چاندی کو ایک ہی کلو سونا یا چاندی سے فروخت کیا جائے۔اسی طرح ایک کلو گرام غلہ یا نمک کو ایک ہی کلو گرام غلہ یا نمک سے فروخت کیا جائے۔اس میں اچھے اورخراب سب برابر ہیں۔یہ پابندی اس لیے لگائی گئی ہے کہ کہیں کسی غریب کو سود کی دلدل میں نہ پھنسنا پڑے۔\nدوسری شرط یہ عائد کی گئی کہ خرید وفروخت ہاتھ کے ہاتھ ہو۔یعنی قرض نہ ہو۔جیسے کوئی ایک کلو گرام سوناایک کلو گرام سونا کے بدلے فروخت کرنا چاہے، لیکن قرض پر،تو یہ صحیح نہیں ہوگا،بلکہ سود بن جائے گا۔کیونکہ پہلےبتایا جاچکا ہے کہ وقت سود کا ایک اہم سبب ہے۔اس لیے ضروری ہے کہ یہ چیزیں یکساں طور پر ہاتھ کے ہاتھ فروخت کی جائیں۔\n۲- جب ان (۶)چیزوں کو بدل کر فروخت کرنا ہوتو جیسے چاہیں فروخت کرسکتے ہیں، لیکن شرط یہ ہے کہ ہاتھ کے ہاتھ فروخت کی جائیں۔جیسے سونے کو چاندی کے بدلےیا گیہوں کو جو کے بدلے فروخت کرنا ہو تو برابر کا ہوناضروری نہیں، جس طرح اور جتنے میں چاہیں فروخت کرسکتے ہیں۔لیکن ہاتھ کے ہاتھ ہونا ضروری ہے۔\nاگرایک شخص سو کلو گرام اعلی معیار کےچاول کو اس سے کم اچھے چاول کے بدلے میں فروخت کرنا چاہتاہے تاکہ وہ زیادہ مقدار میں مل جائے تو اس کو چاہیے کہ پہلے سو کلو گرام عمدہ چاول کو قیمتاً فروخت کردے،پھر اس روپے سے کم اچھا چاول جتنا ملتا ہو خرید لے۔ایسی حالت میں اس پر کوئی پابندی نہیں ہے۔\n۳- جب مذکوربالا(۶)چیزوں کے علاوہ کسی دوسری چیزکی خرید وفروخت مطلوب ہوتوکوئی شرط نہیں۔جیسےچاہیں فروخت کریں۔ہاتھ کے ہاتھ ہونا بھی ضروری نہیں ہے۔اُدھار بھی لین دین ہوسکتا ہے۔جیسے ایک گرام سونے کے بدلے (۱۰۰)گز کپڑا۔ سو کلو گرام کھجور کے بدلے پانچ سو سمنٹ کی بوریاں۔اس صورت میں دونوں جنسوں کا برابر ہونا لازم نہیں ہے۔بل کہ جس طرح آپس میں طے ہوجائےخرید و فروخت اور نقد واُدھارسب جائزہے۔\nیہ ہے اسلام کا معاشی نظام،جس کے ذریعے سےوہ غریبوں اورمسکینوں کےحقوق کی حفاظت کرتاہے، تاکہ وہ سود کی لعنت میں جکڑ کر ہمیشہ کےلیے برباد نہ ہوجائے۔\nاب چونکہ تجارت میں لین دین نوٹوں کے ذریعے سےہوتا ہے،اس لیے ایک ہزارو روپے کے بدلے کوئی ایک ہزار ایک سو روپیہ لےیا دے تو یہ سود کہلائےگا۔خواہ ہاتھ کے ہاتھ ہو یا بطور قرض۔خواہ بینک کے ذریعےسے ہویا کسی فرد کے ذریعےسے۔اس لیے بینک کےسود سے بچنے کےلیے ماہرین نے اسلامی بینک کا تصورپیش کیا جو شریعت کےاصولوں پرمبنی ہے۔خاص طور سےشرکت ومضاربتاوربیع سلم۔شرکت ومضاربت یہ ہےکہ کچھ لوگ مل کر سرمایہ اکٹھا کریں اورکوئی تاجریاتاجرگروپ اس سے تجارت کرے اورفریقین فائدے اور نقصان میں بعض ضوابط کےساتھ تجارت میں شامل ہوں۔\nسلم کااستعمال تجارت میں کیا جاتاہے جوبینک سے قرض لےکرسلم کےاصول پرواپس کیا جاتاہے۔زیادہ معلومات کےلیے بینکاری کی کتابوں کا مطالعہ کیا جاسکتا ہے۔","",{}],[294,"§رحمن\nدیکھیے: اسماے حسنی","",{}],[295,"§رحیم\nدیکھیے: اسماے حسنی","",{}],[296,"§رزاق\nدیکھیے: اسماے حسنی","",{}],[297,"§رسول\nرسول اللہ کے وہ خاص بندےہوتے ہیں،جن کو اللہ اپنا پیغام بندوں تک پہنچانے کے لیے منتخب کرتا ہے،تاکہ لوگ قیامت کے دن اللہ سے یہ نہ کہہ سکیں کہ ہم تک تیرا پیغام نہ پہنچ سکا تها۔جیسا کہ قرآن میں ہے:﴿رُّسُلࣰ ا مُّبَشِّرِينَ وَمُنذِرِينَ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَى ٱللَّهِ حُجَّةُۢ بَعۡدَ ٱلرُّسُلِۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمࣰ ا﴾ [النساء: ۱۶۵] \"(سب) نبیوں کو(اللہ تعالی نے) خوشخبری سنانے والے اور ڈرانے والے (بنا کر بھیجا تھا) تاکہ نبیوں کے آنے کے بعد لوگوں کو اللہ تعالی پر الزام کا موقع نہ رہے اور اللہ تعالی عزیزوحکیم(غالب حکمت والا) ہے\"۔\nاللہ تعالیٰ نے رسولوں کو واضح دلائل کے ساتھ بھیجا اور ان پرکتابیں نازل کیں تاکہ لوگ سیدھے راستےپرقائم رہیں۔جیسا کہ قرآن کریم میں ہے: ﴿لَقَدۡ أَرۡسَلۡنَا رُسُلَنَا بِٱلۡبَيِّنَٰتِ وَأَنزَلۡنَا مَعَهُمُ ٱلۡكِتَٰبَ وَٱلۡمِيزَانَ لِيَقُومَ ٱلنَّاسُ بِٱلۡقِسۡطِۖ وَأَنزَلۡنَا ٱلۡحَدِيدَ فِيهِ بَأۡسࣱ شَدِيدࣱ وَمَنَٰفِعُ لِلنَّاسِ وَلِيَعۡلَمَ ٱللَّهُ مَن يَنصُرُهُۥ وَرُسُلَهُۥ بِٱلۡغَيۡبِۚ إِنَّ ٱللَّهَ قَوِيٌّ عَزِيزࣱ‏﴾ [الحدید: ۲۵] \"ہم نے اپنےنبیوں کو کھلی نشانیاں دے کر بھیجا اوراُن پر کتابیں اور ترازو (عدل وانصاف کے قوانین) نازل کیے تاکہ لوگ انصاف پر قائم رہیں۔ اور لوہا پیدا کیا اس میں (اسلحہٴ جنگ کے لحاظ سے) خطرہ بھی شدیدہے اورلوگوں کے لیے فائدےبھی ہیں اور اس لیے کہ جو لوگ بن دیکھے اللہ تعالی اور اس کے نبیوں کی مدد کرتے ہیں اللہ تعالی ان کو جان لے۔ بےشک اللہ تعالی قوی اورعزیز(غالب) ہے\"۔\nانبیاکےساتھ ان کی قوموں نے کیسا برتاؤکیا۔ قرآن مجیدنے ان کے قصوں کو تفصیلی طور پر بیان کیا ہےاور اس کے مقصد پر اس طرح روشنی ڈالی ہے:﴿لَقَدۡ كَانَ فِي قَصَصِهِمۡ عِبۡرَةࣱ لِّأُوْلِي ٱلۡأَلۡبَٰبِۗ مَا كَانَ حَدِيثࣰ ا يُفۡتَرَىٰ وَلَٰكِن تَصۡدِيقَ ٱلَّذِي بَيۡنَ يَدَيۡهِ وَتَفۡصِيلَ كُلِّ شَيۡءࣲ وَهُدࣰ ى وَرَحۡمَةࣰ لِّقَوۡمࣲ يُؤۡمِنُونَ﴾ [یوسف: ۱۱۱] \"ان کے واقعات میں عقل والوں کے لیے یقیناً نصیحت اور عبرت ہے،یہ قرآن جھوٹ بنائی ہوئی بات نہیں بل کہ یہ تصدیق ہے، ان کتابوں کی جو اس سے پہلے کی ہیں اور ہر چیز کو کھول کھول کر بیان کرنے والا ہے ہرچیز کو اور ہدایت اور رحمت ہے ایمان دار لوگوں کے لیے\"۔\nرسولوں کےمتعلق قرآن مجیدنے جو اہم باتیں بتائیں ہیں ان میں سے کچھ یہ ہیں :\n۱- ہر قوم کے لیے رسول بھیجے گئے۔(سورہ الرعد:۷)\n۲- جو رسول جس قوم میں بھیجا گیا اس نے اسی قوم کی زبان میں اللہ کا پیغام سنایا۔(سورہ ابراہیم:۴)\n۳- اگر اللہ چاہتا تو ہر بستی میں رسول بھیج سکتا تھا۔(سورہ الفرقان : ۵۱) مگر ایسا نہیں کیا۔ کیونکہ اس کو معلوم تھا کہ جو نبیوں کے جھٹلانے والے ہیں وہ تب بھی جھٹلائیں گے۔\n۴- سارے انبیا کی دعوت ایک تھی۔ تمام نبیوں نے یہ پیغام دیا کہ صرف اللہ کی عبادت کرو۔کسی کو اس کاشریک مت بناؤ۔ (دیکھیے: سورہ الانبیاء:۲۵)\n۵- کچھ رسولوں کا تذکرہ اللہ نے قرآن میں کردیا ہے اور بہت سارو کا نہیں کیا۔(دیکھیے: سورہ النساء:۱۶۴)\n۶- رسولوں کاانتخاب اللہ کے ہاتھ میں ہے۔(دیکھیے: سورہ الحج:۷۵)\nمطلب یہ ہے کہ کوئی راہب، جوگی، پیر، فقیر، ملنگ اپنے ترک دیناکی قوت پر رسول نہیں بن سکتا۔ رسالت اللہ کا اختیارہے۔وہ جس کو چاہتا ہے اپنا نبی یا رسول قرار دیتا ہے۔ چونکہ نبی اکرم کی نبوت ورسالت کے بعد نبوت ورسالت کاسلسلہ مکمل طورپرختم ہوچکاہے، اس لیے اب نبوت کا دعویٰ کرنے والا بہت بڑا جھوٹا اور مکار مانا جائے گا۔\nجن نبیوں اوررسولوں کا تذکرہ قرآن میں آیا ہے ان کی تعداد پچیس ہے۔ یہاں پر ان کے نام، اوران کے زمانوں کا ذکر کیا جاتا ہے۔ یہاں جو زمانہ وجود بتایا جارہا ہے وہ بائبل اور دوسری کتابوں سے لیا گیا ہے۔ حالانکہ کچھ نبیوں کے متعلق یقینی طور پر کچھ کہنا دشوار ہے۔ خاص طور پر آدم علیہ السلام کے متعلق جن کا زمانہ وجود دوسرے ذرائع اور ثبوتوں کے ذریعہ اس سے بہت پہلے ہے جو تورات میں آیا ہے۔\nذوالکفل (۱۴۲۵ ـ۱۵۰۰ ق م)کاتذکرہ قرآن مجید میں دوبار آیاہے۔ان کےمتعلق علماءکےدرمیان اس بات پر اختلاف رائے ہے کہ وہ نبی تھےیا نہیں۔ کچھ علماء نے بائبل کی بنیاد پر ان کا نبی ہونا ثابت کیا ہے۔ ان انبیا کے متعلق مفصل تذکرہ ان کے اسما ءکے ساتھ دیکھیں۔\nجبکہ وجود آدم اور ان کی اولاد یعنی انسان کا ذکر جدید تحقیقات کی روشنی میں اس تاریخ سے جو تورات میں آیا ہے لا کھوں سال پہلے ثابت ہوتا ہے۔ کیا بعید کہ قرآن جو بار بار قرون (یعنی صدیوں) کا ذکر کرتا ہے اسی کی تردید میں ہو, جیسے اللہ تعالی کاقول:\n﴿وَكَمۡ أَهۡلَكۡنَا مِنَ ٱلۡقُرُونِ مِنۢ بَعۡدِ نُوحٖۗ وَكَفَىٰ بِرَبِّكَ بِذُنُوبِ عِبَادِهِۦ خَبِيرَۢا بَصِيرٗا﴾ [الإِسۡرَاء: ۱۷]\nترجمہ: دیکھ لو, کتنی ہی نسلیں ہیں جو نوح علیہ السلام کے بعد ہمارے حکم سے ہلاک ہوئیں۔ تیرا رب اپنے بندوں کے گناہوں سے پوری طرح باخبر ہے اور سب کچھ دیکھ رہا ہے۔\nاسی طرح اللہ تعالی کا فرمان:\n﴿وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ مِنۢ بَعۡدِ مَآ أَهۡلَكۡنَا ٱلۡقُرُونَ ٱلۡأُولَىٰ بَصَآئِرَ لِلنَّاسِ وَهُدٗى وَرَحۡمَةٗ لَّعَلَّهُمۡ يَتَذَكَّرُونَ﴾ [القَصَص: ۴۳]\nترجمہ: پچھلی نسلوں کو ہلاک کرنے کے بعد ہم نے موسی علیہ السلام کو کتاب عطا کی, لوگوں کے لئے بصیرتوں کا سامان بناکر, ہدایت اور رحمت بناکر, تاکہ شاید لوگ سبق حاصل کریں۔\nاس سے پتہ چلتا ہے کہ تورات میں جو نبیوں کی تاریخ بیان کی گئی ہے ان نبیوں کے درمیان صدیوں کے فاصلے تھے, لیکن تورات کے کاتبین اس سے نا واقف تھے۔ دراصل قرآن اسی کی تردید کرتا ہے۔ بہر حال میں نے اس وقت آپ کے سامنے تورات میں بیان کردہ نبیوں کی تاریخ ذکر کردی ہےڑ جن نبیوں کا تذکرہ قرآن مجید میں آیا ہے, مگر اس تاریخ پر مکمل اعتماد کرنا صحیح نہیں ہے۔\n§انبیا کی تعداد:\nیہاں صرف ان انبیا کا تذکرہ کیا گیا ہےجن کا نام قرآن پاک میں موجود ہے۔ جن انبیا کا نام قرآن پاک میں نہیں آیا ہے، ان کی تعداد کچھ حدیثوں میں تین سو سولہ بتائی گئی ہے اور کچھ میں ایک لاکھ بیس ہزار۔لیکن یہ حدیثیں ضعیف ہیں۔ اس کے لیے مصنف کی کتاب الجامع الکامل دیکھیے۔\nواضح رہے کہ جن کا نام قرآن یا حدیث میں نہیں آیا ہے، ان کے بارے میں یہ موقف اپنایا جائے کہ ہم نہ تو ان کی نبوت کا انکار کریں اور نہ ہی ان کو نبی یا رسول مانیں۔ جیسے گوتم بدھ، کرشن اور رام, کنفوشیش اور زردشت وغیرہ۔ کیوں کہ اگر واضح طور پر ان کی نبوت کا انکار کردیں تو ہوسکتا ہے کہ وہ نبی یا رسول رہے ہوں اور ان کی قوموں نےان کی تعلیمات میں تحریفات کردی ہوں اور اگر ان کو نبی یا رسول مان لیں: تو ہوسکتا ہے کہ وہ نبی یا رسول نہ رہے ہوں، ایک عام مصلح ہوں اور ہم ایک غیر نبی کو نبی مان بیٹھیں۔اس لیے ہاں یا نا کچھ نہ کہیں، یہی احتیاط کا تقاضا ہے۔","",{}]]);
